# ---------------------------------------------------------------------------
# Container memory-pressure logging (OOM diagnostics; the user's feedback)
# ---------------------------------------------------------------------------


class _MemHandle:
    """JobHandle double exposing a live job with IN_PROGRESS chunks.

    Records which access path the sampler used: ``snapshot()`` is the diagnostic READ
    (must NOT stamp the stall watchdog), ``update()`` is the write path (does stamp).
    """

    def __init__(self, in_progress: list[str]) -> None:
        from dsql_migrator.core.models import ChunkState, MigrationJob

        self.job_id = "mem-job"
        self._job = MigrationJob(
            job_id="mem-job",
            chunks=[ChunkState(chunk_id=n, status="IN_PROGRESS") for n in in_progress],
        )
        self.updates = 0
        self.snapshots = 0

    def snapshot(self):
        self.snapshots += 1
        return self._job.model_copy(deep=True)

    def update(self, fn):
        self.updates += 1
        return fn(self._job)


def test_memory_pressure_logger_noop_off_fargate(monkeypatch, caplog) -> None:
    # No cgroup memory file (macOS/dev) -> disabled, samples nothing, never logs.
    from dsql_migrator.ui.data_migration import _full_load_engine as _engine

    monkeypatch.setattr(_engine, "_read_cgroup_memory", lambda: None)
    logger = _engine._MemoryPressureLogger(_MemHandle([]))
    assert logger._enabled is False
    with caplog.at_level("INFO", logger="dsql_migrator.ui.data_migration._full_load_engine"):
        logger.sample()
        logger.sample()
    assert not [r for r in caplog.records if "memory" in r.getMessage().lower()]


def test_memory_pressure_logger_high_water_info_and_80pct_warning(monkeypatch, caplog) -> None:
    # A climbing usage logs a new high-water at INFO, then a single WARNING once it
    # crosses 80% of the limit, tagging the currently-loading table.
    from dsql_migrator.ui.data_migration import _full_load_engine as _engine

    limit = 1024 * 1024 * 1024  # 1 GiB task limit
    readings = iter([
        (270 * 1024 * 1024, limit),   # consumed by __init__'s enable probe
        (270 * 1024 * 1024, limit),   # 270 MiB — first high-water (INFO)
        (270 * 1024 * 1024, limit),   # same — no new high-water, below 80%
        (900 * 1024 * 1024, limit),   # 900 MiB ≈ 88% — new high-water INFO + WARNING
    ])
    monkeypatch.setattr(_engine, "_read_cgroup_memory", lambda: next(readings))
    # Capture the DURABLE activity-log event (surfaces in the UI timeline / download).
    activity: list[dict] = []
    monkeypatch.setattr(
        _engine, "log_activity",
        lambda category, action, **kw: activity.append({"action": action, **kw}),
    )
    logger = _engine._MemoryPressureLogger(_MemHandle(["ecommerce.product_media"]))
    assert logger._enabled is True
    # Defeat the 5 s sample throttle so each sample() actually reads (set AFTER __init__
    # so the probe above doesn't consume a tick).
    ticks = iter([0.0, 1000.0, 2000.0, 3000.0])
    monkeypatch.setattr(_engine._time, "monotonic", lambda: next(ticks))
    with caplog.at_level("INFO", logger="dsql_migrator.ui.data_migration._full_load_engine"):
        logger.sample()  # 270 -> INFO high-water
        logger.sample()  # 270 -> nothing
        logger.sample()  # 900 -> INFO high-water + WARNING

    infos = [r for r in caplog.records if r.levelname == "INFO" and "high-water" in r.getMessage()]
    warns = [r for r in caplog.records if r.levelname == "WARNING" and "memory pressure" in r.getMessage()]
    assert len(infos) == 2                     # 270 and 900, not the middle repeat
    assert len(warns) == 1                     # crossed 80% exactly once
    w = warns[0].getMessage()
    assert "ecommerce.product_media" in w      # names the culprit table
    assert "88%" in w or "87%" in w            # 900/1024 ≈ 88%
    assert "task limit" in w

    # The durable activity-log event fires exactly once, at INFO, naming the table.
    mem_events = [e for e in activity if e["action"] == "memory pressure"]
    assert len(mem_events) == 1
    assert mem_events[0]["status"].value == "info"
    assert "ecommerce.product_media" in mem_events[0]["detail"]
    assert "task limit" in mem_events[0]["detail"]


def test_memory_pressure_warning_rearms_only_after_receding(monkeypatch, caplog) -> None:
    # The WARNING fires once, does not repeat while still high, and re-arms after usage
    # drops below the re-arm threshold (so a run hovering near the limit doesn't flap).
    from dsql_migrator.ui.data_migration import _full_load_engine as _engine

    limit = 1000 * 1024 * 1024
    readings = iter([
        (500 * 1024 * 1024, limit),   # consumed by __init__'s enable probe
        (850 * 1024 * 1024, limit),   # 85% -> WARNING
        (860 * 1024 * 1024, limit),   # still high -> no repeat
        (600 * 1024 * 1024, limit),   # 60% < 70% re-arm -> silent, re-arms
        (900 * 1024 * 1024, limit),   # 90% -> WARNING again
    ])
    monkeypatch.setattr(_engine, "_read_cgroup_memory", lambda: next(readings))
    logger = _engine._MemoryPressureLogger(_MemHandle([]))
    # AFTER __init__ so the probe doesn't consume a tick.
    ticks = iter([0.0, 100.0, 200.0, 300.0, 400.0])
    monkeypatch.setattr(_engine._time, "monotonic", lambda: next(ticks))
    with caplog.at_level("WARNING", logger="dsql_migrator.ui.data_migration._full_load_engine"):
        for _ in range(4):
            logger.sample()

    warns = [r for r in caplog.records if "memory pressure" in r.getMessage()]
    assert len(warns) == 2  # once at 85%, silent at 86% and 60%, again at 90%


def test_read_cgroup_memory_prefers_v2_and_handles_max(monkeypatch, tmp_path) -> None:
    # v2 "max" (unlimited) -> limit None; a numeric max -> that limit.
    from dsql_migrator.ui.data_migration import _full_load_engine as _engine

    cur = tmp_path / "memory.current"
    mx = tmp_path / "memory.max"
    cur.write_text("123456\n")
    monkeypatch.setattr(_engine, "_CGROUP_V2_CURRENT", str(cur))
    monkeypatch.setattr(_engine, "_CGROUP_V2_MAX", str(mx))

    mx.write_text("max\n")
    assert _engine._read_cgroup_memory() == (123456, None)

    mx.write_text(str(2 * 1024 * 1024 * 1024) + "\n")
    used, limit = _engine._read_cgroup_memory()
    assert used == 123456 and limit == 2 * 1024 * 1024 * 1024


# ---------------------------------------------------------------------------
# Full-load-only -> CDC: enforced FKs must block the stream (silent-data-loss bug)
# ---------------------------------------------------------------------------


def test_preserved_foreign_key_names_come_from_the_same_ddls_the_apply_uses() -> None:
    """Ownership must be derived from foreign_key_ddls, the apply pass's own source.

    If the two ever disagreed, the CDC gate would either fail to remove an FK this
    migration created (stream dead-letters child rows) or offer to drop one it did not
    create and cannot put back.
    """
    from dsql_migrator.core.converter import TableConversion
    from dsql_migrator.ui.data_migration._full_load_engine import (
        preserved_foreign_key_names,
    )

    conversions = {
        "ecommerce.orders": TableConversion(
            table="ecommerce.orders",
            target_ddl="CREATE TABLE x (id INT)",
            foreign_key_ddls=[
                'ALTER TABLE "ecommerce"."orders" ADD CONSTRAINT "fk_orders_users" '
                'FOREIGN KEY ("user_id") REFERENCES "ecommerce"."users" ("id") NOT VALID'
            ],
        ),
        # FK preservation off / no FKs -> absent from the map entirely.
        "ecommerce.products": TableConversion(
            table="ecommerce.products",
            target_ddl="CREATE TABLE y (id INT)",
            foreign_key_ddls=[],
        ),
    }
    assert preserved_foreign_key_names(conversions) == {
        "ecommerce.orders": ["fk_orders_users"]
    }


def test_start_cdc_job_refuses_when_the_target_still_has_enforced_foreign_keys(
    monkeypatch,
) -> None:
    """The backstop that closes the Full-load-only -> CDC-only hole.

    A ``Full load only`` run applies AND validates the preserved FKs at the end of the
    load (its three CDC signals are all unset, because at load time nothing knows CDC
    will follow). If the user then switches to ``CDC only`` and streams, the sink applies
    change records across several tasks with no parent-before-child ordering -> a child
    row can arrive first, get SQLSTATE 23503, and be dead-lettered permanently while
    offsets advance: silent data loss. The job body re-checks and refuses BEFORE creating
    any connector, which also covers the dialog-less "Retry CDC" path.
    """
    from types import SimpleNamespace

    import dsql_migrator.ui.data_migration._cdc_ui as _cdcui
    from dsql_migrator.core.cdc import CdcBlockingForeignKeys

    class _SubmitOnlyJM:
        def __init__(self) -> None:
            self.work = None

        def submit(self, work):
            self.work = work
            return "job-1"

    class _Ui:
        def notify(self, *_a, **_k):
            return None

    monkeypatch.setattr(_cdcui, "_log_cdc_event", lambda *a, **k: None)
    monkeypatch.setattr(_cdcui, "_read_cdc_template_body", lambda: "TEMPLATE-BODY")
    monkeypatch.setattr(
        _cdcui,
        "_probe_cdc_blocking_foreign_keys",
        lambda *a, **k: CdcBlockingForeignKeys(
            ours=[("ecommerce.order_items", "fk_order_items_orders")],
            foreign=[],
            unknown_tables=[],
        ),
    )
    built = {"deployer": 0}
    monkeypatch.setattr(
        "dsql_migrator.core.cdc_deployer.build_cdc_stack_deployer",
        lambda *a, **k: built.__setitem__("deployer", built["deployer"] + 1),
    )

    session = SimpleNamespace(
        target_config=SimpleNamespace(region="us-east-1", cluster_endpoint="c.dsql"),
        aws_profile=None,
        source_config=None,
        source_secret_id=None,
    )
    state = DataMigrationState()
    state.set_selection(TableSelection(selected_tables=["orders"]))
    jm = _SubmitOnlyJM()
    _cdcui._start_cdc_deploy(
        _Ui(), state, jm, lambda: None, inventory=_inventory(), session=session
    )
    assert jm.work is not None  # submitted; the refusal happens on the worker thread

    with pytest.raises(RuntimeError) as excinfo:
        jm.work(SimpleNamespace())
    message = str(excinfo.value)
    assert "enforced foreign keys" in message
    assert "fk_order_items_orders" in message      # names exactly what blocks
    assert "23503" in message                       # and why it matters
    assert built["deployer"] == 0                   # nothing was created


def test_start_cdc_job_proceeds_when_the_target_has_no_enforced_foreign_keys(
    monkeypatch,
) -> None:
    # The normal CDC-only case must NOT be gated: a clean probe lets the deploy run, so
    # the fix cannot regress every ordinary CDC start.
    from types import SimpleNamespace

    import dsql_migrator.core.cdc_deployer as _dep
    import dsql_migrator.ui.data_migration._cdc_ui as _cdcui

    class _SubmitOnlyJM:
        def __init__(self) -> None:
            self.work = None

        def submit(self, work):
            self.work = work
            return "job-1"

    class _Ui:
        def notify(self, *_a, **_k):
            return None

    class _Deployer:
        template_s3_bucket = ""

        def _client(self, _svc):
            return SimpleNamespace(
                get_caller_identity=lambda: {"Account": "123456789012"}
            )

    ran = {"start": 0}
    monkeypatch.setattr(_cdcui, "_log_cdc_event", lambda *a, **k: None)
    monkeypatch.setattr(_cdcui, "_read_cdc_template_body", lambda: "TEMPLATE-BODY")
    # A genuinely CLEAN verdict (read the catalog, nothing enforced) -- not the
    # None "no tables resolved" sentinel, so the clean path is really exercised.
    from dsql_migrator.core.cdc import CdcBlockingForeignKeys

    monkeypatch.setattr(
        _cdcui,
        "_probe_cdc_blocking_foreign_keys",
        lambda *a, **k: CdcBlockingForeignKeys(ours=[], foreign=[], unknown_tables=[]),
    )
    monkeypatch.setattr(_dep, "build_cdc_stack_deployer", lambda *a, **k: _Deployer())
    monkeypatch.setattr(
        _dep, "run_cdc_start",
        lambda *a, **k: ran.__setitem__("start", ran["start"] + 1),
    )

    session = SimpleNamespace(
        target_config=SimpleNamespace(region="us-east-1", cluster_endpoint="c.dsql"),
        aws_profile=None,
        source_config=None,
        source_secret_id=None,
    )
    state = DataMigrationState()
    state.set_selection(TableSelection(selected_tables=["orders"]))
    jm = _SubmitOnlyJM()
    _cdcui._start_cdc_deploy(
        _Ui(), state, jm, lambda: None, inventory=_inventory(), session=session
    )
    jm.work(SimpleNamespace())
    assert ran["start"] == 1


def test_probe_cdc_blocking_foreign_keys_covers_non_streamed_children() -> None:
    """The probe must ask about every table this migration gives FKs to.

    An FK on a NON-streamed child still blocks: a streamed DELETE on the parent is
    rejected (23503) because the static child rows still reference it, and that DELETE is
    dead-lettered permanently. Scoping the probe to the streamed set alone would miss it.
    """
    from types import SimpleNamespace

    import dsql_migrator.ui.data_migration._cdc_ui as _cdcui

    asked: dict = {}

    def _fake_target_foreign_keys(table_names, *, connection_factory):
        asked["names"] = list(table_names)
        connection_factory()  # prove the real factory seam is used
        return {name: [] for name in table_names}

    state = DataMigrationState()
    state.set_selection(TableSelection(selected_tables=["orders"]))
    # 'archive_orders' is NOT streamed but this migration gives it an FK.
    state.set_cdc_preserved_foreign_keys({"archive_orders": ["fk_archive_orders"]})

    session = SimpleNamespace(
        target_config=SimpleNamespace(region="us-east-1", cluster_endpoint="c.dsql"),
        aws_profile=None,
    )
    import dsql_migrator.core.target_introspector as _ti

    _orig = _ti.target_foreign_keys
    _ti.target_foreign_keys = _fake_target_foreign_keys
    _cdcui_orig = _cdcui._cdc_fk_connection_factory
    _cdcui._cdc_fk_connection_factory = lambda _s: (lambda: object())
    try:
        result = _cdcui._probe_cdc_blocking_foreign_keys(
            state, session, _inventory(), None
        )
    finally:
        _ti.target_foreign_keys = _orig
        _cdcui._cdc_fk_connection_factory = _cdcui_orig

    assert "archive_orders" in asked["names"]      # the non-streamed child was checked
    assert "orders" in asked["names"]
    assert result is not None and result.blocking is False


def test_probe_cdc_blocking_foreign_keys_fails_closed_without_a_target() -> None:
    # No target configured -> every table UNKNOWN (never "clean"), so the gate holds.
    from types import SimpleNamespace

    import dsql_migrator.ui.data_migration._cdc_ui as _cdcui

    state = DataMigrationState()
    state.set_selection(TableSelection(selected_tables=["orders"]))
    result = _cdcui._probe_cdc_blocking_foreign_keys(
        state, SimpleNamespace(target_config=None, aws_profile=None), _inventory(), None
    )
    assert result is not None
    assert result.blocking is True
    assert result.ours == [] and result.foreign == []
    assert result.unknown_tables  # unreadable, not "none"


def test_drop_cdc_blocking_foreign_keys_drops_each_and_logs_it(monkeypatch) -> None:
    # Each drop is its own single DDL and each is named in the activity log, so an
    # operator can reconstruct exactly what was removed and when.
    from types import SimpleNamespace

    import dsql_migrator.ui.data_migration._cdc_ui as _cdcui

    dropped: list[tuple] = []
    logged: list[tuple] = []
    monkeypatch.setattr(
        "dsql_migrator.core.schema_applier.drop_foreign_key",
        lambda table, name, **kw: dropped.append((table, name)),
    )
    monkeypatch.setattr(
        _cdcui, "_log_cdc_event",
        lambda action, **kw: logged.append((action, kw.get("detail", ""))),
    )
    monkeypatch.setattr(_cdcui, "_cdc_fk_connection_factory", lambda _s: (lambda: object()))

    ok, failed = _cdcui._drop_cdc_blocking_foreign_keys(
        [("ecommerce.orders", "fk_orders_users"),
         ("ecommerce.order_items", "fk_items_orders")],
        SimpleNamespace(),
    )
    assert (ok, failed) == (2, 0)
    assert dropped == [
        ("ecommerce.orders", "fk_orders_users"),
        ("ecommerce.order_items", "fk_items_orders"),
    ]
    assert len(logged) == 2
    assert all("fk_" in detail for _a, detail in logged)
    assert all("re-created" in detail for _a, detail in logged)  # says how to get them back


def test_drop_cdc_blocking_foreign_keys_reports_failures_without_aborting(
    monkeypatch,
) -> None:
    # One bad drop must not silently stop the rest, and it must be logged as a failure --
    # a half-removed set that reads as success would let the user start CDC into 23503.
    from types import SimpleNamespace

    import dsql_migrator.ui.data_migration._cdc_ui as _cdcui

    logged: list[tuple] = []

    def _drop(table, name, **kw):
        if name == "fk_bad":
            raise RuntimeError("permission denied")

    monkeypatch.setattr("dsql_migrator.core.schema_applier.drop_foreign_key", _drop)
    monkeypatch.setattr(
        _cdcui, "_log_cdc_event",
        lambda action, **kw: logged.append((action, str(kw.get("status")))),
    )
    monkeypatch.setattr(_cdcui, "_cdc_fk_connection_factory", lambda _s: (lambda: object()))

    ok, failed = _cdcui._drop_cdc_blocking_foreign_keys(
        [("t", "fk_bad"), ("t", "fk_good")], SimpleNamespace()
    )
    assert (ok, failed) == (1, 1)
    assert any("not removed" in action for action, _s in logged)


def test_cdc_fk_block_copy_distinguishes_found_from_unreadable() -> None:
    """An unreadable catalog must not be reported as "enforced foreign keys exist".

    That is the likeliest block in practice (a transient DSQL connect), and the wrong
    wording sends the operator to pg_constraint to find nothing instead of to the
    connection test. It is also the case with NO Remove button, so the copy must not
    point at one.
    """
    import dsql_migrator.ui.data_migration._cdc_ui as _cdcui
    from dsql_migrator.core.cdc import CdcBlockingForeignKeys

    found = CdcBlockingForeignKeys(
        ours=[("ecommerce.orders", "fk_orders_users")], foreign=[], unknown_tables=[]
    )
    clause, header = _cdcui._cdc_fk_block_reason(found)
    assert "still has enforced foreign keys" in clause
    assert "Remove" in header
    assert "Remove them below" in _cdcui._cdc_fk_block_body(found)
    # The job error has no button, so it points at where the control lives instead.
    no_button = _cdcui._cdc_fk_block_body(found, can_remove_here=False)
    assert "Remove them below" not in no_button
    assert "Reopen Start CDC" in no_button

    unreadable = CdcBlockingForeignKeys(
        ours=[], foreign=[], unknown_tables=["ecommerce.orders"]
    )
    clause, header = _cdcui._cdc_fk_block_reason(unreadable)
    assert "could not be verified" in clause
    assert "Could not verify" in header
    body = _cdcui._cdc_fk_block_body(unreadable)
    assert "were created by this migration" not in body
    assert "Re-test the target connection" in body


def test_fk_ownership_is_independent_of_the_preserve_foreign_keys_toggle() -> None:
    """Ownership must survive unticking "Preserve foreign keys" — else CDC dead-ends.

    An operator blocked by the CDC foreign-key gate does the obvious thing: goes to Schema
    Conversion and unticks "Preserve foreign keys" to get rid of them. That blanks
    ``foreign_key_ddls``, so deriving ownership from the toggle made the tool DISOWN the
    very constraints it had created — classifying them as the user's, hiding the Remove
    button, and leaving CDC blocked with no in-UI way out. Ownership is a fact about what
    this migration's conversion RENDERS; whether the user still wants them re-applied is a
    separate choice.
    """
    from dsql_migrator.core.converter import SchemaConverter
    from dsql_migrator.core.models import (
        ColumnDef, ForeignKeyDef, SourceInventory, TableDef,
    )
    from dsql_migrator.ui.data_migration._full_load_engine import (
        preserved_foreign_key_names,
    )
    from dsql_migrator.ui.schema_conversion_apply import applied_table_conversions

    users = TableDef(
        name="users",
        columns=[ColumnDef(name="id", mysql_type="int", nullable=False)],
        primary_key=["id"],
    )
    orders = TableDef(
        name="orders",
        columns=[
            ColumnDef(name="id", mysql_type="int", nullable=False),
            ColumnDef(name="user_id", mysql_type="int", nullable=False),
        ],
        primary_key=["id"],
        foreign_keys=[
            ForeignKeyDef(
                name="fk_orders_users",
                columns=["user_id"],
                referenced_table="users",
                referenced_columns=["id"],
            )
        ],
    )
    conversion = SchemaConverter().convert(SourceInventory(tables=[users, orders]))

    owned = preserved_foreign_key_names(
        applied_table_conversions(conversion, {}, preserve_foreign_keys=True)
    )
    assert owned == {"orders": ["fk_orders_users"]}

    # The trap the fix avoids: the OFF toggle blanks foreign_key_ddls, so an ownership map
    # derived from it is EMPTY -- the tool would disown its own constraint.
    assert (
        preserved_foreign_key_names(
            applied_table_conversions(conversion, {}, preserve_foreign_keys=False)
        )
        == {}
    )

    # And the app stores the toggle-INDEPENDENT view: assert the wiring passes True.
    import inspect

    from dsql_migrator.ui import data_migration as _dm

    src = inspect.getsource(_dm.build_data_migration_screen)
    assert "set_cdc_preserved_foreign_keys" in src
    assert "preserve_foreign_keys=True" in src


# ---------------------------------------------------------------------------
# FK post-pass vs CREATE INDEX ASYNC race (composite-PK parent)
# ---------------------------------------------------------------------------


def test_fk_pass_waits_while_the_referenced_unique_index_is_still_building(
    monkeypatch,
) -> None:
    """The race: the FK post-pass ran seconds after CREATE INDEX ASYNC and did not wait.

    A composite-PK re-key makes Full Load RECREATE the parent, so its single-column unique
    index (the only thing giving `id` alone the uniqueness a child FK needs) is built AFTER
    the load by `CREATE INDEX ASYNC`, which returns immediately. The FK pass then failed
    42830 and the run still reported SUCCESS with integrity silently missing -- and being a
    race, the same procedure passed on one run and dropped an FK on the next.
    """
    from dsql_migrator.core.models import ForeignKeyDef
    from dsql_migrator.ui.data_migration import _full_load_engine as _engine

    states = ["building", "building", "valid"]
    asked: list = []

    def _fake_state(table_name, columns, *, connection_factory):  # noqa: ANN001
        asked.append((table_name, list(columns)))
        return states[min(len(asked) - 1, len(states) - 1)]

    monkeypatch.setattr(
        "dsql_migrator.core.target_introspector.unique_index_state", _fake_state
    )
    slept: list = []
    fk = ForeignKeyDef(
        name="fk_order_items_orders", columns=["order_id"],
        referenced_table="ecommerce.orders", referenced_columns=["id"],
    )

    state, waited = _engine._wait_for_referenced_unique_index(
        fk, lambda: object(),
        sleep=slept.append, monotonic=lambda: 0.0,   # budget never expires
    )
    assert state == "valid"
    # The elapsed wait is REPORTED, which is the only evidence in the field that the
    # race was handled rather than merely won (a successful run used to leave no trace).
    assert waited == 0.0   # this fake clock never advances; see the bounded test below
    assert len(asked) == 3            # polled until the async build finished
    assert len(slept) == 2            # waited between polls
    assert asked[0] == ("ecommerce.orders", ["id"])


def test_fk_pass_does_not_wait_when_the_unique_index_is_absent(monkeypatch) -> None:
    # "absent" means waiting is pointless (no CREATE INDEX ASYNC is in flight), so it must
    # return at once and let the ADD fail with an actionable reason -- not burn the budget.
    from dsql_migrator.core.models import ForeignKeyDef
    from dsql_migrator.ui.data_migration import _full_load_engine as _engine

    calls = {"n": 0}

    def _absent(table_name, columns, *, connection_factory):  # noqa: ANN001
        calls["n"] += 1
        return "absent"

    monkeypatch.setattr(
        "dsql_migrator.core.target_introspector.unique_index_state", _absent
    )
    slept: list = []
    fk = ForeignKeyDef(
        name="fk", columns=["pid"], referenced_table="parent", referenced_columns=["id"],
    )
    state, waited = _engine._wait_for_referenced_unique_index(
        fk, lambda: object(), sleep=slept.append, monotonic=lambda: 0.0
    )
    assert state == "absent"
    assert waited == 0.0   # nothing was waited for -> the caller logs nothing
    assert calls["n"] == 1
    assert slept == []


def test_fk_pass_wait_is_bounded_so_a_stuck_build_cannot_hang_the_run(
    monkeypatch,
) -> None:
    # Always-building must give up at the budget rather than spin forever.
    from dsql_migrator.core.models import ForeignKeyDef
    from dsql_migrator.ui.data_migration import _full_load_engine as _engine

    monkeypatch.setattr(
        "dsql_migrator.core.target_introspector.unique_index_state",
        lambda *a, **k: "building",
    )
    clock = {"t": 0.0}

    def _monotonic() -> float:
        return clock["t"]

    def _sleep(seconds: float) -> None:
        clock["t"] += seconds

    fk = ForeignKeyDef(
        name="fk", columns=["pid"], referenced_table="parent", referenced_columns=["id"],
    )
    state, waited = _engine._wait_for_referenced_unique_index(
        fk, lambda: object(), budget_seconds=10.0, poll_seconds=2.0,
        sleep=_sleep, monotonic=_monotonic,
    )
    assert state == "building"          # gave up, did not hang
    assert clock["t"] >= 10.0
    # The duration is carried out so the failure detail can name it -- that is what
    # separates "the index build is slow" from "there is no such index" for an operator.
    assert waited >= 10.0


def test_fk_failure_detail_records_the_real_reason_and_the_statement() -> None:
    """The old detail was the fixed string "could not be created automatically".

    The exception went only to the module logger, so the activity log -- the artifact an
    operator downloads and pastes into a runbook -- recorded NO reason, and there was no way
    to know what to apply manually. CloudWatch showed only the one-line warning.
    """
    from dsql_migrator.ui.data_migration import _full_load_engine as _engine

    class _Err(Exception):
        sqlstate = "42830"

    exc = _Err("there is no unique constraint matching given keys for referenced table")
    ddl = (
        'ALTER TABLE "ecommerce"."order_items" ADD CONSTRAINT "fk_order_items_orders" '
        'FOREIGN KEY ("order_id") REFERENCES "ecommerce"."orders" ("id") NOT VALID'
    )

    still_building = _engine._fk_failure_detail(exc, ddl, "building")
    assert "42830" in still_building
    assert "CREATE INDEX ASYNC" in still_building          # names the actual cause
    assert "ADD CONSTRAINT" in still_building              # copy-pasteable statement

    absent = _engine._fk_failure_detail(exc, ddl, "absent")
    assert "no UNIQUE index" in absent
    assert "create one first" in absent
    assert "42830" in absent

    other = _engine._fk_failure_detail(RuntimeError("boom"), ddl, None)
    assert "boom" in other
    assert "SQLSTATE=unknown" in other
    assert "ADD CONSTRAINT" in other


def test_apply_foreign_keys_returns_the_full_triple_for_the_step_to_report(
    monkeypatch,
) -> None:
    """The WHOLE outcome has to leave this function, not just the failure count.

    It is what the Data Migration step's explicit "Apply foreign keys" action reports back
    -- "15 applied" / "13 applied, 2 skipped (orphan rows)". It used to return only the
    failed count (the load needed one summary clause), and when the action started storing
    that value the step tried `list(<int>)` and raised TypeError on the next render. A LIVE
    run caught that; no unit test did, because none carried the value into the renderer --
    which `test_the_fk_action_result_renders` now does.
    """
    import dsql_migrator.ui.data_migration._full_load_engine as engine

    monkeypatch.setattr(engine, "log_activity", lambda *a, **k: None)

    class _Partial:
        def apply_foreign_keys(self):
            return (5, 0, 1)          # the workshop's real outcome

    assert engine._apply_foreign_keys(_Partial()) == (5, 0, 1)

    class _Clean:
        def apply_foreign_keys(self):
            return (6, 0, 0)

    assert engine._apply_foreign_keys(_Clean()) == (6, 0, 0)

    # Tolerated shapes must not blow up, and must report nothing applied or missing.
    class _Legacy:
        def apply_foreign_keys(self):
            return None

    assert engine._apply_foreign_keys(_Legacy()) == (0, 0, 0)
    assert engine._apply_foreign_keys(object()) == (0, 0, 0)   # no hook at all


def test_the_fk_action_result_renders(monkeypatch) -> None:
    """Carry what the action STORES into the renderer -- the gap that let a TypeError ship.

    The action does `set_fk_apply_result(_apply_foreign_keys(...))` and the step renders that
    value. Nothing joined the two, so an int flowed into `list(applied)`.
    """
    import dsql_migrator.ui.data_migration._full_load_engine as engine
    from dsql_migrator.ui.data_migration._full_load_ui import _render_foreign_key_action
    from dsql_migrator.ui.data_migration._state import DataMigrationState

    monkeypatch.setattr(engine, "log_activity", lambda *a, **k: None)

    class _M:
        def apply_foreign_keys(self, **_kw):
            return (13, 2, 0)

    state = DataMigrationState()
    state.set_fk_apply_result(engine._apply_foreign_keys(_M()))

    class _Ui:
        def __init__(self):
            self.texts: list = []

        class _El:
            def __init__(self, ui): self._ui = ui
            def __enter__(self): return self
            def __exit__(self, *e): return False
            def __getattr__(self, _n): return lambda *a, **k: self

        def label(self, text="", *a, **k):
            self.texts.append(str(text)); return _Ui._El(self)

        def __getattr__(self, _n):
            return lambda *a, **k: _Ui._El(self)

    ui = _Ui()
    # Must not raise -- this is the exact call that failed with an int.
    _render_foreign_key_action(
        ui, terminal=True, pending=0, applied=state.fk_apply_result,
        apply_foreign_keys=lambda: None, connections_ready=True,
    )
    joined = " ".join(ui.texts)
    assert "13 applied" in joined, ui.texts
    assert "2 skipped" in joined, ui.texts


def test_run_completed_names_foreign_keys_that_were_not_applied(monkeypatch) -> None:
    """`run completed` used to read SUCCESS / "7 table(s) loaded" with an FK missing.

    That is how a workshop participant saw `5 applied, 1 failed` and assumed their own
    mistake: the summary line said nothing was wrong.
    """
    import dsql_migrator.ui.data_migration._full_load_engine as engine

    events: list = []
    monkeypatch.setattr(engine, "log_activity", lambda *a, **k: events.append((a, k)))

    class _Handle:
        cancelled = False

    counts = engine._RunCounts(real_failed=0, quarantined=0)

    engine._finalize_run(
        _Handle(), "job-1", ["a", "b"], counts, object(),
        accept_quarantined_rows=False, foreign_keys_pending=1,
    )
    detail = [k.get("detail", "") for _a, k in events if "run completed" in str(_a)]
    assert detail and "2 table(s) loaded" in detail[0]
    assert "1 foreign key(s) NOT YET APPLIED" in detail[0]
    assert "Apply foreign keys" in detail[0], "the summary must name the action to take"

    # A clean run keeps the original wording exactly (no noise).
    events.clear()
    engine._finalize_run(
        _Handle(), "job-1", ["a", "b"], counts, object(),
        accept_quarantined_rows=False,
    )
    detail = [k.get("detail", "") for _a, k in events if "run completed" in str(_a)]
    assert detail == ["2 table(s) loaded"]


def test_apply_preserved_fk_logs_the_real_reason_end_to_end(monkeypatch) -> None:
    """Pins the WIRING, not just the helper: the activity log must carry the reason.

    A helper-only test let a revert to the old fixed string ("could not be created
    automatically; apply it manually") pass green, which is exactly the regression this
    guards -- the activity log is the artifact an operator pastes into a runbook, and the
    exception used to go only to the module logger.
    """
    import dsql_migrator.ui.data_migration._full_load_engine as engine

    class _NoUniqueIndex(Exception):
        sqlstate = "42830"

    def _boom(add_ddl, *, connection_factory):  # noqa: ANN001
        raise _NoUniqueIndex(
            "there is no unique constraint matching given keys for referenced table"
        )

    monkeypatch.setattr(engine, "apply_foreign_key", _boom)
    monkeypatch.setattr(engine, "validate_foreign_key", lambda *a, **k: None)
    # The referenced unique index simply is not there -> no waiting, actionable reason.
    monkeypatch.setattr(
        "dsql_migrator.core.target_introspector.unique_index_state",
        lambda *a, **k: "absent",
    )
    events: list = []
    monkeypatch.setattr(engine, "log_activity", lambda *a, **k: events.append((a, k)))

    result = engine.apply_preserved_foreign_keys(
        {"orders": _fk_conv(foreign_key_ddls=[_FK_DDL])}, lambda: _FkProbeConnection(0)
    )
    assert result == (0, 0, 1)

    details = [k.get("detail", "") for _a, k in events if "not applied" in str(_a)]
    assert details, events
    detail = details[0]
    assert "42830" in detail                       # the SQLSTATE
    assert "no unique constraint matching" in detail  # the driver's own message
    assert "no UNIQUE index" in detail              # why, in operator terms
    assert "ADD CONSTRAINT" in detail               # the statement to run
    assert detail != "could not be created automatically; apply it manually"


def test_a_real_index_wait_is_logged_and_a_normal_run_stays_quiet(monkeypatch) -> None:
    """The wait must leave a trace, or the 0.1.446 fix cannot be verified in the field.

    It previously logged nothing: on a SUCCESSFUL run "the wait held the FK back until the
    index was ready" and "the race happened to be won" were indistinguishable -- the gap
    between the last table load and the FK pass was ~5.4s either way, and neither the
    activity log nor CloudWatch had an entry for the interval.
    """
    import dsql_migrator.ui.data_migration._full_load_engine as engine

    events: list = []
    monkeypatch.setattr(engine, "log_activity", lambda *a, **k: events.append((a, k)))
    monkeypatch.setattr(engine, "apply_foreign_key", lambda *a, **k: None)
    monkeypatch.setattr(engine, "validate_foreign_key", lambda *a, **k: None)

    # A wait really happened (2.5s), then the index became valid.
    monkeypatch.setattr(
        engine, "_wait_for_referenced_unique_index", lambda *a, **k: ("valid", 2.5)
    )
    result = engine.apply_preserved_foreign_keys(
        {"orders": _fk_conv(foreign_key_ddls=[_FK_DDL])}, lambda: _FkProbeConnection(0)
    )
    assert result == (1, 0, 0)
    waited = [k for _a, k in events if "waited" in str(_a)]
    assert waited, events
    detail = waited[0].get("detail", "")
    assert "2.5s" in detail                      # names how long
    assert "CREATE INDEX ASYNC" in detail        # and what it waited on
    assert waited[0].get("status") is engine.ActivityStatus.INFO   # not an alarm

    # The normal case (index already valid, nothing waited) logs NO wait entry.
    events.clear()
    monkeypatch.setattr(
        engine, "_wait_for_referenced_unique_index", lambda *a, **k: ("valid", 0.0)
    )
    engine.apply_preserved_foreign_keys(
        {"orders": _fk_conv(foreign_key_ddls=[_FK_DDL])}, lambda: _FkProbeConnection(0)
    )
    assert not [k for _a, k in events if "waited" in str(_a)], events


def test_fk_failure_detail_names_how_long_it_waited() -> None:
    # With the elapsed wait in the message an operator can tell "the index build is slow,
    # retry shortly" from "there is no such index" -- the two produce the same SQLSTATE.
    from dsql_migrator.ui.data_migration import _full_load_engine as _engine

    class _Err(Exception):
        sqlstate = "42830"

    exc = _Err("there is no unique constraint matching given keys for referenced table")
    ddl = 'ALTER TABLE "e"."order_items" ADD CONSTRAINT "fk" FOREIGN KEY ("o") REFERENCES "e"."orders" ("id") NOT VALID'

    detail = _engine._fk_failure_detail(exc, ddl, "building", waited_seconds=300.0)
    assert "300.0s" in detail
    assert "wait budget" in detail
    assert "42830" in detail

    # "absent" never waits, so it must not claim a wait happened.
    absent = _engine._fk_failure_detail(exc, ddl, "absent", waited_seconds=0.0)
    assert "waiting" not in absent
    assert "no UNIQUE index" in absent


def test_lob_card_on_the_full_load_screen_explains_its_own_lock() -> None:
    """A frozen LOB tick box must say WHY and how to change it.

    The Full Load screen passed ``lock_reason=None``, and the panel only renders text
    ``if locked and lock_reason`` -- so the boxes were frozen with NO explanation at all,
    the "silent frozen box reads as a bug" state that panel's own comment forbids. The
    table picker's copy does not help either: it talks about "a different set of tables",
    while a user who forgot to exclude a column is trying to change the COLUMNS, so that
    sentence does not read as applying to them. The LOB-specific reason names the cause
    AND the way out (Start over).
    """
    import inspect

    from dsql_migrator.ui import data_migration as _dm
    from dsql_migrator.ui.data_migration._cdc_monitoring import lob_exclusion_lock

    # The screen wires the LOB-specific lock into the panel call (not a bare None).
    # NB source-TEXT assertions are why the v0.1.448 blocker shipped: `inspect.getsource`
    # passes even when the helper was never imported, so the call site's NameError went
    # unseen until users hit the screen. The name is therefore resolved through the
    # module namespace here, and every call site in the package is checked mechanically
    # by tests/test_no_undefined_globals.py.
    assert callable(_dm.lob_exclusion_lock), (
        "build_data_migration_screen calls lob_exclusion_lock, so the name must resolve "
        "in the module namespace -- a missing import only raises when content() runs"
    )
    src = inspect.getsource(_dm.build_data_migration_screen)
    assert "lob_exclusion_lock(" in src
    assert "lock_reason=_lob_reason" in src

    # And that reason actually addresses a column change + names the escape hatch.
    state = DataMigrationState()
    locked, reason = lob_exclusion_lock(state, None, full_load_committed=True)
    assert locked is True
    assert "excluded columns are fixed" in reason
    assert "Start over" in reason


# ---------------------------------------------------------------------------
# Drop & reload: the tool must not be blocked by the FKs it created itself
# ---------------------------------------------------------------------------


def test_foreign_keys_blocking_replace_selects_only_parents_being_replaced() -> None:
    """`DROP TABLE orders` is refused while order_items' FK still references it.

    A `Full load only` run creates that FK in its own post-load pass, so choosing
    Drop & reload afterwards hit a wall the tool itself built -- and the error blamed a
    view and told the user to pick the dependent object in the object browser, which is
    impossible for a foreign key. Only FKs whose PARENT is being replaced need removing;
    an FK that merely lives ON a replaced table goes away with the DROP.
    """
    from dsql_migrator.core.converter import TableConversion
    from dsql_migrator.core.models import ForeignKeyDef
    from dsql_migrator.ui.data_migration._full_load_engine import (
        foreign_keys_blocking_replace,
    )

    fk_ddl = (
        'ALTER TABLE "ecommerce"."order_items" ADD CONSTRAINT "fk_order_items_orders" '
        'FOREIGN KEY ("order_id") REFERENCES "ecommerce"."orders" ("id") NOT VALID'
    )
    conversions = {
        "ecommerce.order_items": TableConversion(
            table="ecommerce.order_items",
            target_ddl="CREATE TABLE x (id INT)",
            foreign_key_ddls=[fk_ddl],
            preserved_foreign_keys=[
                ForeignKeyDef(
                    name="fk_order_items_orders", columns=["order_id"],
                    referenced_table="ecommerce.orders", referenced_columns=["id"],
                )
            ],
        ),
    }

    # Replacing the PARENT -> the child's FK must be dropped first.
    assert foreign_keys_blocking_replace(conversions, {"ecommerce.orders"}) == [
        ("ecommerce.order_items", "fk_order_items_orders")
    ]
    # Replacing the CHILD -> nothing to do (DROP TABLE takes its own constraints).
    assert foreign_keys_blocking_replace(conversions, {"ecommerce.order_items"}) == []
    # An append run replaces nothing.
    assert foreign_keys_blocking_replace(conversions, set()) == []
    # A table outside this migration's conversion is never implicated.
    assert foreign_keys_blocking_replace(conversions, {"other.thing"}) == []


def test_predrop_blocking_foreign_keys_drops_them_and_logs(monkeypatch) -> None:
    # The pre-pass mirrors the dependent-VIEW pre-drop: remove first, and the EXISTING
    # post-load pass re-creates them, so no new restore code is needed.
    from types import SimpleNamespace

    import dsql_migrator.ui.data_migration._full_load_engine as engine

    dropped: list = []
    events: list = []
    monkeypatch.setattr(
        "dsql_migrator.core.schema_applier.drop_foreign_key",
        lambda table, name, **kw: dropped.append((table, name)),
    )
    monkeypatch.setattr(engine, "log_activity", lambda *a, **k: events.append((a, k)))
    monkeypatch.setattr(
        engine, "foreign_keys_blocking_replace",
        lambda *a, **k: [("ecommerce.order_items", "fk_order_items_orders")],
    )

    class _Migrator:
        _inputs = SimpleNamespace(table_conversions={}, replace_tables=frozenset({"x"}))

        def _view_connection_factory(self):
            return lambda: object()

        predrop_blocking_foreign_keys = (
            engine.BatchedTableMigrator.predrop_blocking_foreign_keys
        )

    _Migrator().predrop_blocking_foreign_keys()
    assert dropped == [("ecommerce.order_items", "fk_order_items_orders")]
    detail = [k.get("detail", "") for _a, k in events if "removed for reload" in str(_a)]
    # The detail must NOT promise an automatic re-create: nothing has done that since
    # v0.1.461, when applying foreign keys became the explicit "Apply foreign keys" action.
    assert detail and "Nothing re-creates it automatically" in detail[0], detail
    assert "Apply foreign keys" in detail[0], detail


def test_predrop_blocking_foreign_keys_runs_before_the_load(monkeypatch) -> None:
    """Record the actual CALL ORDER, not the source text.

    The order matters: if the pre-drop ran after the load, the replace's DROP would still
    hit the foreign key. Asserting it by comparing offsets in `inspect.getsource` is the
    same instrument that missed the v0.1.448 NameError -- and it would silently keep
    passing if a refactor moved the call inside a helper. So the passes are stubbed and the
    sequence they execute in is recorded.
    """
    from types import SimpleNamespace

    import dsql_migrator.ui.data_migration._full_load_engine as engine

    calls: list[str] = []
    monkeypatch.setattr(
        engine, "_predrop_blocking_foreign_keys", lambda m: calls.append("fk-predrop")
    )
    monkeypatch.setattr(
        engine, "_predrop_dependent_views", lambda m: calls.append("view-predrop")
    )
    monkeypatch.setattr(
        engine, "_migrate_tables_in_parallel",
        lambda *a, **k: calls.append("load") or engine._RunCounts(
            real_failed=0, quarantined=0
        ),
    )
    monkeypatch.setattr(
        engine, "_recreate_dependent_views", lambda m: calls.append("view-recreate")
    )
    monkeypatch.setattr(
        engine, "_apply_foreign_keys",
        # Signature-tolerant on purpose: the pass now also receives the JobHandle so it
        # can report liveness during a wait that can legitimately exceed the 900s stall
        # window. A fixed-arity double here would break on that (it did).
        lambda *_a, **_k: calls.append("fk-apply") or 0,
    )
    monkeypatch.setattr(engine, "_finalize_run", lambda *a, **k: None)
    monkeypatch.setattr(engine, "log_activity", lambda *a, **k: None)
    monkeypatch.setattr(engine, "_log_excluded_lob_columns", lambda *a, **k: None)

    class _Handle:
        cancelled = False
        job_id = "job-1"

        def __getattr__(self, _name):
            return lambda *a, **k: None

    class _Migrator:
        """Only what run_full_load itself calls; the passes above are stubbed out."""

        def capture_watermark(self, _tables):
            return None

    engine.run_full_load(
        _Handle(), [], migrator=_Migrator(), error_log=SimpleNamespace()
    )

    # The FK pre-drop must precede the load.
    assert calls.index("fk-predrop") < calls.index("load"), calls
    # The load no longer APPLIES foreign keys: that is an explicit operator action on the
    # Data Migration step now (it was holding the END of the load for many minutes -- 28.0
    # min serial / 7.9 min at 8-way, measured -- after every row was already written). The
    # PRE-DROP still runs before the load; that one is required, or a replaced parent table
    # cannot be dropped.
    assert "fk-apply" not in calls, calls
    # And it runs before the view pre-drop (a view can sit on top of the FK'd table).
    assert calls.index("fk-predrop") < calls.index("view-predrop"), calls


def test_cdc_run_predrops_fks_and_deliberately_does_not_restore_them(monkeypatch) -> None:
    """On a CDC-bearing run the pre-drop stands: cut over restores, not this run.

    `apply_foreign_keys` returns (0,0,0) when `is_cdc_migration` / `cdc_coexisting` /
    `cdc_stack_name` is set, so a Drop & reload on a Full-load+CDC migration drops the FKs
    and does NOT re-create them before the run ends. That is CORRECT -- an enforced FK
    makes the sink dead-letter out-of-order child rows, so cut over adds them once the
    stream has drained -- but it looks like a missing restore, so pin it here to stop
    someone "fixing" it later.
    """
    from types import SimpleNamespace

    import dsql_migrator.ui.data_migration._full_load_engine as engine

    dropped: list = []
    monkeypatch.setattr(
        "dsql_migrator.core.schema_applier.drop_foreign_key",
        lambda table, name, **kw: dropped.append((table, name)),
    )
    monkeypatch.setattr(engine, "log_activity", lambda *a, **k: None)
    monkeypatch.setattr(
        engine, "foreign_keys_blocking_replace",
        lambda *a, **k: [("ecommerce.order_items", "fk_order_items_orders")],
    )

    class _CdcMigrator:
        _inputs = SimpleNamespace(
            table_conversions={},
            replace_tables=frozenset({"ecommerce.orders"}),
            is_cdc_migration=True,          # the CDC-bearing signal
            cdc_coexisting=False,
            cdc_stack_name=None,
            inventory=None,
        )

        def _view_connection_factory(self):
            return lambda: object()

        predrop_blocking_foreign_keys = (
            engine.BatchedTableMigrator.predrop_blocking_foreign_keys
        )
        apply_foreign_keys = engine.BatchedTableMigrator.apply_foreign_keys

    migrator = _CdcMigrator()

    # 1) the pre-drop still runs -- the replace would otherwise be blocked
    migrator.predrop_blocking_foreign_keys()
    assert dropped == [("ecommerce.order_items", "fk_order_items_orders")]

    # 2) and the post-load pass deliberately restores NOTHING on a CDC run
    assert migrator.apply_foreign_keys() == (0, 0, 0)

    # 3) contrast: a Full-load-ONLY run does restore (same class, CDC signals unset)
    class _LoadOnlyMigrator(_CdcMigrator):
        _inputs = SimpleNamespace(
            table_conversions={},
            replace_tables=frozenset({"ecommerce.orders"}),
            is_cdc_migration=False,
            cdc_coexisting=False,
            cdc_stack_name=None,
            inventory=None,
        )

    applied: list = []
    monkeypatch.setattr(
        engine, "apply_preserved_foreign_keys",
        lambda *a, **k: applied.append("restored") or (1, 0, 0),
    )
    assert _LoadOnlyMigrator().apply_foreign_keys() == (1, 0, 0)
    assert applied == ["restored"]


def test_confirm_dialog_opens_when_cdc_is_live_and_the_target_holds_rows(
    monkeypatch,
) -> None:
    """Regression: the dialog raised UnboundLocalError in exactly this combination.

    The append/drop radio is created only `if tables_with_data_now and not cdc_live_now`
    (replace is disabled while a sink streams), but its change handler was attached under
    the looser `if tables_with_data_now` -- so with CDC streaming AND the probed table
    already holding target rows, `reload_choice` was never bound and BUILDING the dialog
    raised, so it never opened at all. Reachable today from the per-table Reload and
    "Retry unfinished tables".

    The rows must come from the PROBE, not from pre-seeded state: the confirm handler
    resets `tables_with_data` before probing, so a pre-seeded value is discarded.
    """
    from dsql_migrator.ui.data_migration import _full_load_ui as fl

    monkeypatch.setattr(fl, "DsqlConnector", lambda *a, **k: _StubConnector())
    # The probed table ALREADY HOLDS ROWS on the target ...
    monkeypatch.setattr(
        fl, "tables_with_rows", lambda names, **k: ["ecommerce.orders"]
    )
    monkeypatch.setattr(fl, "target_primary_keys", lambda names, **k: {})
    monkeypatch.setattr(fl, "tables_present", lambda names, **k: {"ecommerce.orders"})
    # ... while CDC is streaming, so no append/drop radio is rendered.
    monkeypatch.setattr(fl, "cdc_streaming_started", lambda *a, **k: True)

    ui = _open_full_load_confirm_dialog(
        monkeypatch,
        recreate_candidates=lambda: [],
        migration_state=DataMigrationState(),
        session=_StubSession(),
        selected_names=["ecommerce.orders"],
    )

    # It must OPEN (building it used to raise) and offer its actions.
    assert ui.dialogs, "the confirm dialog did not open"
    assert "Cancel" in " ".join(ui.buttons)
    # And it must NOT offer the drop/append choice while CDC streams.
    body = " ".join(ui.texts)
    assert "Choose how to load them" not in body


# ---------------------------------------------------------------------------
# Exclude an oversized LOB column and reload (the post-load recovery path)
# ---------------------------------------------------------------------------


def test_preselect_lob_columns_narrows_by_the_dsql_type_in_the_reason() -> None:
    """The offending COLUMN is not in the quarantine record -- only the DSQL TYPE is.

    `DataErrorRecord` carries table/pk/error_code/message, and the message keeps just the
    first line of the driver error: "datatype limit greater than 1048576 bytes not
    supported for bytea" -- the type, never the column. But the mapping is deterministic
    (mediumblob/longblob -> bytea, mediumtext/longtext -> text), so that token narrows a
    table with BOTH kinds. product_media really has two candidates (content longblob,
    full_description longtext), which is why auto-picking without this would be a coin flip.
    """
    from dsql_migrator.ui.data_migration._models import preselect_lob_columns_for_reason

    cols = [("content", "longblob"), ("full_description", "longtext")]
    assert preselect_lob_columns_for_reason(
        cols, "quarantined row pk[id=3]: datatype limit greater than 1048576 bytes "
              "not supported for bytea"
    ) == ("content",)
    assert preselect_lob_columns_for_reason(
        cols, "datatype limit greater than 1048576 bytes not supported for text"
    ) == ("full_description",)

    # Type sizes/precision in the declared type must not defeat the match.
    assert preselect_lob_columns_for_reason(
        [("blob_col", "LONGBLOB")], "not supported for bytea"
    ) == ("blob_col",)

    # No recognisable type, or no column of that kind -> make the user choose.
    assert preselect_lob_columns_for_reason(cols, "some other failure") == ()
    assert preselect_lob_columns_for_reason([("t", "longtext")], "for bytea") == ()
    assert preselect_lob_columns_for_reason([], "for bytea") == ()


def test_exclude_and_reload_is_allowed_after_a_load_but_refused_once_cdc_owns_the_set() -> None:
    """The bundled action is deliberately NARROWER than the tick-box lock.

    `lob_exclusion_lock`'s `full_load_committed` clause fires because changing the
    exclusion would leave ALREADY-LOADED rows inconsistent with what CDC captures -- but
    this action DROPS and reloads the table, so those rows cease to exist and the
    inconsistency cannot arise. What stays unsafe is a pipeline already given the old set.
    """
    from dsql_migrator.ui.data_migration import _cdc_monitoring as cm

    # The case the tick boxes lock but this action must allow: a finished Full Load,
    # no CDC anywhere. (This is the dead end the feature exists to remove.)
    clean = DataMigrationState()
    assert cm.exclude_and_reload_block_reason(clean, None) is None
    assert cm.lob_exclusion_lock(clean, None, full_load_committed=True)[0] is True

    # A deployed cdc-stack bakes ColumnExcludeList at create time -> refuse. "unstable"
    # is included on purpose: cdc_infra_prep_state treats it as ready, so omitting it
    # (as lob_exclusion_lock's own tuple does) would let the action through.
    for phase in ("infra", "running", "provisioning", "partial", "unstable"):
        state = DataMigrationState()
        state.cdc_stack_phase = phase
        reason = cm.exclude_and_reload_block_reason(state, None)
        assert reason, f"phase {phase} must block"
        # Either clause may claim it -- "running" also reads as streaming -- but it must
        # always name CDC as the owner of the set and give a way forward.
        assert "CDC" in reason, phase

    # A torn-down stack no longer owns the set.
    gone = DataMigrationState()
    gone.cdc_stack_phase = "deleted"
    assert cm.exclude_and_reload_block_reason(gone, None) is None


def test_exclude_and_reload_refused_while_cdc_streams(monkeypatch) -> None:
    # Offsets are committed on MSK under the old excluded-column set, so history was
    # captured with different columns -- a reload cannot reconcile that.
    from dsql_migrator.ui.data_migration import _cdc_monitoring as cm

    monkeypatch.setattr(cm, "cdc_streaming_started", lambda *a, **k: True)
    reason = cm.exclude_and_reload_block_reason(DataMigrationState(), None)
    assert reason and "stop CDC first" in reason


def _quar_render_ui():
    """A NiceGUI double that records buttons AND runs checkbox/click handlers."""
    from dsql_migrator.core.models import ChunkState, MigrationJob

    class _Ui:
        def __init__(self):
            self.buttons: list[tuple[str, str, str]] = []   # (text, props, tooltip)
            self.handlers: dict[str, object] = {}           # button text -> on_click
            self.texts: list[str] = []
            self.checkboxes: list[str] = []
            self.dialogs = 0

        class _El:
            def __init__(self, ui, kind, text="", on_click=None):
                self._ui, self._kind, self._text = ui, kind, text
                self._props = ""
                if kind == "button" and on_click is not None:
                    ui.handlers[text] = on_click
            def __enter__(self): return self
            def __exit__(self, *e): return False
            def props(self, spec="", *a, **k):
                if self._kind == "button":
                    self._props = str(spec)
                    self._ui.buttons.append((self._text, self._props, ""))
                return self
            def tooltip(self, text="", *a, **k):
                if self._kind == "button":
                    # replace the last record for this button with the tooltip filled in
                    for i in range(len(self._ui.buttons) - 1, -1, -1):
                        if self._ui.buttons[i][0] == self._text:
                            self._ui.buttons[i] = (
                                self._text, self._ui.buttons[i][1], str(text)
                            )
                            break
                    else:
                        self._ui.buttons.append((self._text, self._props, str(text)))
                return self
            def on_value_change(self, fn, *a, **k):
                self._ui.handlers.setdefault("__boxes__", []).append((self._text, fn))
                return self
            def __getattr__(self, _n): return lambda *a, **k: self

        def button(self, text="", on_click=None, *a, **k):
            return _Ui._El(self, "button", str(text), on_click)

        def checkbox(self, text="", value=False, *a, **k):
            self.checkboxes.append(f"{text}={value}")
            return _Ui._El(self, "checkbox", str(text))

        def label(self, text="", *a, **k):
            self.texts.append(str(text)); return _Ui._El(self, "other")

        def dialog(self, *a, **k):
            self.dialogs += 1
            return _Ui._El(self, "other")

        def notify(self, *a, **k):
            return None

        def __getattr__(self, _n):
            return lambda *a, **k: _Ui._El(self, "other")

    def _job():
        j = MigrationJob(job_id="j1"); j.status = "DONE"; j.progress_pct = 100.0
        j.chunks = [ChunkState(chunk_id="ecommerce.product_media", status="DONE",
                               rows_loaded=12, rows_quarantined=3, attempts=1)]
        return j

    reason = ("quarantined row pk[id=3]: datatype limit greater than 1048576 bytes "
              "not supported for bytea")
    return _Ui, _job, reason


def test_quarantine_card_offers_exclude_and_reload_and_gates_it() -> None:
    """The recovery affordance must appear where the quarantine is reported.

    Before this, an oversized-LOB quarantine was a dead end: the exclusion tick boxes lock
    once a Full Load has run and the only escape was Start over. The action must also be
    SHOWN-but-disabled when a CDC pipeline owns the excluded-column set (a silently absent
    control reads as a missing feature, and the reason is the actionable part).
    """
    from dsql_migrator.ui.data_migration import (
        _render_full_load_progress,
        build_full_load_table_rows,
    )

    _Ui, _job, reason = _quar_render_ui()
    records = [("ecommerce.product_media", reason)]
    rows = lambda: build_full_load_table_rows(  # noqa: E731
        _job(), None, {"ecommerce.product_media": reason}
    )
    cands = lambda _t: (("content", "longblob"), ("full_description", "longtext"))  # noqa: E731

    # Offered, enabled.
    ui = _Ui()
    _render_full_load_progress(
        ui, _job(), rows(), quarantine_only=True, quarantine_records=records,
        connections_ready=True, lob_candidates_for=cands,
        exclude_lob_and_reload=lambda *_a: None,
    )
    btns = [b for b in ui.buttons if b[0] == "Exclude column & reload"]
    assert btns, f"action not offered; buttons={[b[0] for b in ui.buttons]}"
    assert all("disable" not in b[1] for b in btns)

    # Blocked (CDC owns the set): shown, disabled, reason as the tooltip.
    ui2 = _Ui()
    _render_full_load_progress(
        ui2, _job(), rows(), quarantine_only=True, quarantine_records=records,
        connections_ready=True, lob_candidates_for=cands,
        exclude_lob_and_reload=lambda *_a: None,
        exclude_lob_block_reason="CDC is streaming — stop CDC first.",
    )
    blocked = [b for b in ui2.buttons if b[0] == "Exclude column & reload"]
    assert blocked and all("disable" in b[1] for b in blocked)
    assert any("stop CDC first" in b[2] for b in blocked)

    # No excludable column on the table -> no dead button at all.
    ui3 = _Ui()
    _render_full_load_progress(
        ui3, _job(), rows(), quarantine_only=True, quarantine_records=records,
        connections_ready=True, lob_candidates_for=lambda _t: (),
        exclude_lob_and_reload=lambda *_a: None,
    )
    assert not [b for b in ui3.buttons if b[0] == "Exclude column & reload"]


def test_exclude_and_reload_dialog_preticks_the_matching_column_and_confirms() -> None:
    # The dialog must PICK (not auto-apply): product_media has two LOB candidates, and
    # excluding the wrong one silently NULLs it for every row. The one whose source type
    # maps to the type in the reason (bytea -> longblob) is pre-ticked.
    from dsql_migrator.ui.data_migration import (
        _render_full_load_progress,
        build_full_load_table_rows,
    )

    _Ui, _job, reason = _quar_render_ui()
    applied: list = []
    ui = _Ui()
    _render_full_load_progress(
        ui, _job(),
        build_full_load_table_rows(_job(), None, {"ecommerce.product_media": reason}),
        quarantine_only=True,
        quarantine_records=[("ecommerce.product_media", reason)],
        connections_ready=True,
        lob_candidates_for=lambda _t: (
            ("content", "longblob"), ("full_description", "longtext")
        ),
        exclude_lob_and_reload=lambda table, cols: applied.append((table, list(cols))),
    )

    ui.handlers["Exclude column & reload"]()          # open the picker
    assert ui.dialogs == 1
    # bytea in the reason -> the longblob column is pre-ticked, the longtext one is not
    assert "content  (longblob)=True" in ui.checkboxes, ui.checkboxes
    assert "full_description  (longtext)=False" in ui.checkboxes, ui.checkboxes
    # The confirm is destructive and spells out the impact.
    confirm = [b for b in ui.buttons if b[0] == "Exclude and reload"]
    assert confirm and any("negative" in b[1] for b in confirm)
    body = " ".join(ui.texts)
    assert "product_media" in body

    ui.handlers["Exclude and reload"]()               # confirm
    assert applied == [("ecommerce.product_media", ["content"])]


def test_index_wait_reports_zero_when_it_never_waited_even_as_the_clock_advances() -> None:
    """The first probe's own latency must not be reported as a wait.

    It is a DSQL round trip (IAM token + TLS handshake), so timing it made
    ``waited_seconds`` non-zero for EVERY foreign key. Every pre-existing test for this
    helper injected ``monotonic=lambda: 0.0`` -- a FROZEN clock -- so the probe's cost was
    structurally invisible and this could not be caught. Here the clock ADVANCES on every
    read, which is what a real one does.
    """
    from dsql_migrator.core.models import ForeignKeyDef
    from dsql_migrator.ui.data_migration import _full_load_engine as _engine

    fk = ForeignKeyDef(
        name="fk", columns=["pid"], referenced_table="parent", referenced_columns=["id"],
    )
    ticks = {"t": 0.0}

    def _advancing() -> float:
        ticks["t"] += 0.75          # every read costs time, as a round trip does
        return ticks["t"]

    for first in ("valid", "absent", None):
        import dsql_migrator.core.target_introspector as _ti
        saved = _ti.unique_index_state
        _ti.unique_index_state = lambda *a, **k: first  # noqa: B023
        try:
            state, waited = _engine._wait_for_referenced_unique_index(
                fk, lambda: object(), sleep=lambda _s: None, monotonic=_advancing,
            )
        finally:
            _ti.unique_index_state = saved
        assert state == first
        assert waited == 0.0, f"{first!r} never waited, yet reported {waited}s"


def test_a_normal_fk_pass_logs_no_wait_line_through_the_real_timer(monkeypatch) -> None:
    """End-to-end with the REAL helper: an already-valid index must log NOTHING.

    The call site keys its log on ``index_waited > 0``. The prior call-site test injected
    ``_wait_for_referenced_unique_index -> ("valid", 0.0)``, so it asserted the guard
    while never running the code that computes the value -- it passed against the bug.
    This one lets the real timer run, so the microseconds the probe costs are enough to
    trip the guard if the timer starts too early (which is how the field log filled up
    with "still building ... waited 0.0s" for every FK).
    """
    import dsql_migrator.ui.data_migration._full_load_engine as engine

    events: list = []
    monkeypatch.setattr(engine, "log_activity", lambda *a, **k: events.append((a, k)))
    monkeypatch.setattr(engine, "apply_foreign_key", lambda *a, **k: None)
    monkeypatch.setattr(engine, "validate_foreign_key", lambda *a, **k: None)
    # NOT patched: _wait_for_referenced_unique_index. Only the catalog probe is faked, and
    # it reports the index as already valid -- the normal case.
    monkeypatch.setattr(
        "dsql_migrator.core.target_introspector.unique_index_state",
        lambda *a, **k: "valid",
    )

    result = engine.apply_preserved_foreign_keys(
        {"orders": _fk_conv(foreign_key_ddls=[_FK_DDL])}, lambda: _FkProbeConnection(0)
    )
    assert result == (1, 0, 0)                       # the FK was applied
    waited = [k for _a, k in events if "waited" in str(_a)]
    assert not waited, f"a normal run must stay quiet, got {waited}"


def test_a_genuine_index_wait_still_logs_with_the_real_timer(monkeypatch) -> None:
    # The other half of the fix: silencing the false line must not silence the true one.
    # Guards against "just never log". The reported time covers the polling only, so it
    # can never round to the self-contradictory "still building ... waited 0.0s".
    from dsql_migrator.core.models import ForeignKeyDef
    from dsql_migrator.ui.data_migration import _full_load_engine as _engine

    states = ["building", "building", "valid"]
    asked = {"n": 0}

    def _fake(table_name, columns, *, connection_factory):  # noqa: ANN001
        asked["n"] += 1
        return states[min(asked["n"] - 1, len(states) - 1)]

    monkeypatch.setattr(
        "dsql_migrator.core.target_introspector.unique_index_state", _fake
    )
    clock = {"t": 100.0}

    def _monotonic() -> float:
        clock["t"] += 0.01          # reads cost time too
        return clock["t"]

    def _sleep(seconds: float) -> None:
        clock["t"] += seconds

    fk = ForeignKeyDef(
        name="fk", columns=["pid"], referenced_table="parent", referenced_columns=["id"],
    )
    state, waited = _engine._wait_for_referenced_unique_index(
        fk, lambda: object(), budget_seconds=300.0, poll_seconds=2.0,
        sleep=_sleep, monotonic=_monotonic,
    )
    assert state == "valid"
    assert asked["n"] == 3                       # polled until the build finished
    assert waited >= 4.0                         # the two 2.0s polls, at least
    assert f"{waited:.1f}s" != "0.0s"            # never the contradictory message


def _lineage_log(entries):
    """An ErrorLogStore holding (job_id, table, message) rows."""
    from dsql_migrator.core.error_log import ErrorLogStore
    from dsql_migrator.core.models import DataErrorRecord

    from datetime import datetime, timedelta, timezone

    base = datetime(2026, 9, 18, 5, 0, tzinfo=timezone.utc)
    log = ErrorLogStore()
    for index, (job_id, table, message) in enumerate(entries):
        log.record(
            job_id,
            DataErrorRecord(
                table=table, message=message, chunk_id=table,
                occurred_at=base + timedelta(seconds=index),
            ),
        )
    return log


_QUAR = "quarantined row pk[id={n}]: datatype limit greater than 1048576 bytes not supported for bytea"


def test_a_retry_keeps_the_quarantine_reason_for_tables_it_did_not_rerun() -> None:
    """A retry must not blank the reason for tables it left alone.

    The error log is keyed by job id and a retry runs under a NEW one (the job manager
    refuses to reuse an id), while _seed_retry_chunks carries non-retried chunks forward
    WITH their quarantined-row count. So those tables rendered a count and no reason --
    and because the oversized-LOB recovery action is keyed on those records, it vanished
    for exactly the table that still needed it, leaving Start over as the only escape.
    """
    from dsql_migrator.core.models import ChunkState, MigrationJob
    from dsql_migrator.ui.data_migration._cdc_status import (
        full_load_error_records_for,
        full_load_error_summary_for,
        full_load_latest_messages_for,
    )
    from dsql_migrator.ui.data_migration import _full_load_engine as _engine

    prior_chunks = [
        ChunkState(chunk_id="ecommerce.product_media", status="DONE",
                   rows_loaded=12, rows_quarantined=3, attempts=1),
        ChunkState(chunk_id="ecommerce.attachments", status="DONE",
                   rows_loaded=40, rows_quarantined=2, attempts=1),
    ]
    log = _lineage_log([
        ("job-A", "ecommerce.product_media", _QUAR.format(n=1)),
        ("job-A", "ecommerce.product_media", _QUAR.format(n=2)),
        ("job-A", "ecommerce.product_media", _QUAR.format(n=3)),
        ("job-A", "ecommerce.attachments", _QUAR.format(n=7)),
        ("job-A", "ecommerce.attachments", _QUAR.format(n=8)),
    ])

    # Retry ONLY product_media (what exclude-and-reload does: it scopes to one table).
    retry = MigrationJob(job_id="job-B")
    _engine._seed_retry_chunks(
        retry, prior_chunks, {"ecommerce.product_media"}, prior_job_id="job-A",
    )
    assert retry.table_error_job_ids == {"ecommerce.attachments": "job-A"}

    # attachments keeps its reason AND its records; product_media gets a clean slate.
    messages = full_load_latest_messages_for(log, retry)
    assert "ecommerce.attachments" in messages, messages
    assert "not supported for bytea" in messages["ecommerce.attachments"]
    assert "ecommerce.product_media" not in messages, (
        "the retried table must NOT resurrect its old reasons"
    )
    records = full_load_error_records_for(log, retry)
    assert [r.table for r in records] == ["ecommerce.attachments"] * 2
    assert full_load_error_summary_for(log, retry).errors_by_table == {
        "ecommerce.attachments": 2
    }

    # After the retry succeeds and records its own drop, both are visible, unmixed.
    from datetime import datetime, timezone

    from dsql_migrator.core.models import DataErrorRecord

    log.record(
        "job-B",
        DataErrorRecord(
            table="ecommerce.product_media", message=_QUAR.format(n=9),
            chunk_id="ecommerce.product_media",
            occurred_at=datetime(2026, 9, 18, 6, 0, tzinfo=timezone.utc),
        ),
    )
    assert full_load_error_summary_for(log, retry).errors_by_table == {
        "ecommerce.attachments": 2, "ecommerce.product_media": 1,
    }


def test_repeated_retries_compose_the_error_lineage() -> None:
    # A third run must still reach records written by the FIRST, or the reason decays
    # after two retries instead of one.
    from dsql_migrator.core.models import ChunkState, MigrationJob
    from dsql_migrator.ui.data_migration._cdc_status import full_load_latest_messages_for
    from dsql_migrator.ui.data_migration import _full_load_engine as _engine

    log = _lineage_log([("job-A", "t.untouched", _QUAR.format(n=1))])
    chunks = [
        ChunkState(chunk_id="t.untouched", status="DONE", rows_loaded=1,
                   rows_quarantined=1, attempts=1),
        ChunkState(chunk_id="t.retried", status="FAILED", rows_loaded=0, attempts=1),
    ]

    b = MigrationJob(job_id="job-B")
    _engine._seed_retry_chunks(b, chunks, {"t.retried"}, prior_job_id="job-A")
    c = MigrationJob(job_id="job-C")
    _engine._seed_retry_chunks(
        c, b.chunks, {"t.retried"}, prior_job_id="job-B",
        prior_table_error_job_ids=b.table_error_job_ids,
    )
    assert c.table_error_job_ids == {"t.untouched": "job-A"}   # NOT job-B
    assert "t.untouched" in full_load_latest_messages_for(log, c)


def test_the_accepted_quarantine_count_spans_the_retry_lineage() -> None:
    # The audit line "N row(s) quarantined and ACCEPTED" is what the operator is agreeing
    # to. Counting only the retry's own job id understated it by every table not re-run.
    from dsql_migrator.ui.data_migration import _full_load_engine as _engine

    log = _lineage_log([
        ("job-A", "t.left_alone", _QUAR.format(n=1)),
        ("job-A", "t.left_alone", _QUAR.format(n=2)),
        ("job-A", "t.reloaded", _QUAR.format(n=3)),   # superseded by the retry
        ("job-B", "t.reloaded", _QUAR.format(n=4)),
    ])
    owners = {"t.left_alone": "job-A"}
    assert _engine._count_quarantined_rows(log, "job-B", owners) == 3
    # No lineage (a first run) counts only its own, exactly as before.
    assert _engine._count_quarantined_rows(log, "job-B", None) == 1


