def test_the_fk_post_pass_reports_liveness_per_fk_and_honours_a_stop(monkeypatch) -> None:
    """The post-load FK pass ran entirely after the progress drain was joined.

    Nothing in it reported liveness, and its duration is bounded only by FK count, still
    building parent indexes (up to 300s EACH) and child row count -- so a fully successful
    load could be reaped as "an unresponsive source/target connection", which _mark_done
    cannot undo, leaving the Data Migration step FAILED and Validation gated shut.
    """
    import dsql_migrator.ui.data_migration._full_load_engine as engine

    monkeypatch.setattr(engine, "log_activity", lambda *a, **k: None)
    monkeypatch.setattr(engine, "apply_foreign_key", lambda *a, **k: None)
    monkeypatch.setattr(engine, "validate_foreign_key", lambda *a, **k: None)
    monkeypatch.setattr(
        "dsql_migrator.core.target_introspector.unique_index_state",
        lambda *a, **k: "valid",
    )
    beats: list[int] = []
    result = engine.apply_preserved_foreign_keys(
        {"orders": _fk_conv(foreign_key_ddls=[_FK_DDL])},
        lambda: _FkProbeConnection(0),
        heartbeat=lambda: beats.append(1),
    )
    assert result == (1, 0, 0)
    assert beats, "the pass reported no liveness at all"

    # And a stop is honoured rather than held for the rest of the pass.
    applied = engine.apply_preserved_foreign_keys(
        {"orders": _fk_conv(foreign_key_ddls=[_FK_DDL])},
        lambda: _FkProbeConnection(0),
        should_cancel=lambda: True,
    )
    assert applied == (0, 0, 0), applied


def test_a_still_building_index_wait_reports_liveness_every_poll() -> None:
    # 300s per parent index with a single stamp at the start is longer than the stall
    # window on its own; four such parents is 1200s of silence.
    from dsql_migrator.core.models import ForeignKeyDef
    from dsql_migrator.ui.data_migration import _full_load_engine as _engine

    states = ["building", "building", "building", "valid"]
    asked = {"n": 0}

    def _fake(table_name, columns, *, connection_factory):  # noqa: ANN001
        asked["n"] += 1
        return states[min(asked["n"] - 1, len(states) - 1)]

    import dsql_migrator.core.target_introspector as _ti
    saved = _ti.unique_index_state
    _ti.unique_index_state = _fake
    polls: list[int] = []
    clock = {"t": 0.0}
    try:
        state, _waited = _engine._wait_for_referenced_unique_index(
            ForeignKeyDef(name="fk", columns=["pid"], referenced_table="p",
                          referenced_columns=["id"]),
            lambda: object(), budget_seconds=300.0, poll_seconds=2.0,
            sleep=lambda s: clock.__setitem__("t", clock["t"] + s),
            monotonic=lambda: clock["t"], on_poll=lambda: polls.append(1),
        )
    finally:
        _ti.unique_index_state = saved
    assert state == "valid"
    assert len(polls) == 3, polls        # one per poll of the still-building index


def test_the_replace_pre_pass_reports_liveness_per_recreated_table() -> None:
    # The DROP+recreate loop runs BEFORE the drain thread that owns liveness starts, and
    # is one fresh DSQL connect + DDL per table -- a few hundred tables crossed the stall
    # window before a single row loaded.
    from dsql_migrator.ui.data_migration import _full_load_engine as _engine

    src = _engine._migrate_tables_in_parallel.__code__
    consts = [c for c in src.co_consts if hasattr(c, "co_names")]
    names = set(src.co_names)
    for c in consts:
        names |= set(c.co_names)
    assert "heartbeat" in names, (
        "the replace pre-pass no longer reports liveness before the drain starts"
    )


def test_a_governor_pause_reports_liveness_every_slice() -> None:
    """A sustained pause is intentional waiting, and intentional waiting must report.

    `on_state_change` fires only on the pause<->resume TRANSITION, so a pause longer than
    the stall window looked identical to a dead worker and the healthy, deliberately
    throttled load was reaped as "an unresponsive source/target connection".
    """
    from dsql_migrator.core.exporter import SourceLoadGovernor

    readings = iter([50, 50, 50, 1])
    slices: list[int] = []
    now = {"t": 0.0}

    def _sleep(seconds: float) -> None:
        now["t"] += seconds

    governor = SourceLoadGovernor(
        object(), 10,
        metric_reader=lambda _c: next(readings),
        sleep=_sleep, monotonic=lambda: now["t"],
        ttl_seconds=0.0, slice_seconds=1.0,
        on_pause_slice=lambda: slices.append(1),
    )
    governor.throttle()
    assert len(slices) == 3, slices      # one per wait slice, not one per pause


def test_the_cdc_log_key_survives_a_full_load_retry() -> None:
    """A retry must not make recorded dead-letters unreadable.

    `cdc_error_log_key` returned `migration_state.job_id` live, and a Full Load retry
    ("Retry unfinished tables" / per-table "Reload", both supported WHILE CDC streams)
    replaces it -- so every CDC surface re-keyed mid-stream: the DLQ card fell to a grey
    "0 quarantined / No records quarantined", its download and Ask-AI-DBA buttons
    disappeared, and the per-table consistency badges flipped to "consistent", for records
    that were still there under the previous job id.
    """
    from dsql_migrator.ui.data_migration._cdc_status import cdc_error_log_key

    class _S:
        job_id = "job-A"
        cdc_stack_name = "dsql-cdc-stack"
        cdc_log_key = None

    state = _S()
    first = cdc_error_log_key(state)
    assert first == "job-A"
    state.job_id = "job-B"                        # a retry re-keys the session
    assert cdc_error_log_key(state) == "job-A", (
        "the CDC key followed the retry and orphaned every recorded dead-letter"
    )


def test_the_cdc_log_key_still_falls_back_per_stack_without_a_job() -> None:
    # CDC-only / attach sessions have no Full Load job; keying off "" would drop every
    # record silently.
    from dsql_migrator.ui.data_migration._cdc_status import cdc_error_log_key

    class _S:
        job_id = None
        cdc_stack_name = "my-stack"
        cdc_log_key = None

    state = _S()
    assert cdc_error_log_key(state) == "cdc:my-stack"
    # And once pinned it stays put even if a Full Load starts later.
    state.job_id = "job-Z"
    assert cdc_error_log_key(state) == "cdc:my-stack"


def test_the_dlq_audit_write_is_idempotent_per_record() -> None:
    # The durable activity-log write had no dedup of its own -- only the controller's
    # in-memory cursor -- so any rebuild re-wrote every dead letter in the blind 6h
    # look-back window and N quarantines became 2N/3N audit lines.
    from dsql_migrator.ui.data_migration._state import DataMigrationState

    state = DataMigrationState()
    assert state.cdc_dlq_audited_keys == set()
    key = ("ecommerce.orders", "23503", "fk violation", "2026-09-18T05:00:00")
    state.cdc_dlq_audited_keys.add(key)
    assert key in state.cdc_dlq_audited_keys


def test_the_cdc_controller_cache_is_dropped_when_the_identity_changes() -> None:
    """Switching the AWS profile must not keep serving the old account's view.

    Nothing invalidated the controller, and it holds the region + profile it was built
    with (it makes its own boto3 session per call) -- so the fix the operator had just
    applied on Connect appeared to change nothing.
    """
    from dsql_migrator.ui.data_migration._state import DataMigrationState

    state = DataMigrationState()
    controller = object()
    state.set_cdc_controller(controller, ("us-east-1", "profile-a"))
    assert state.cdc_controller is controller
    assert state.cdc_controller_identity == ("us-east-1", "profile-a")

    # Clearing must null the identity too, even if an identity is handed in: a stale
    # identity left behind an absent controller would make the NEXT injected controller
    # look already-verified and skip the invalidation entirely.
    state.set_cdc_controller(None, ("us-east-1", "profile-a"))
    assert state.cdc_controller is None
    assert state.cdc_controller_identity is None

    # A rebuild under the new identity is tracked, so a later change is caught.
    state.set_cdc_controller(object(), ("ap-northeast-2", "profile-b"))
    assert state.cdc_controller_identity == ("ap-northeast-2", "profile-b")


def test_the_dlq_cursor_is_kept_per_log_group() -> None:
    """One cursor leaked across pipelines when attaching to another CDC stack.

    The adopted pipeline's earlier dead-letters -- older than the leaked cursor but inside
    the first-read look-back -- were never surfaced, so its DLQ card read "0 quarantined"
    for a pipeline that had quarantined rows.
    """
    from dsql_migrator.core.msk_connect_controller import MskConnectController

    ctl = MskConnectController.__new__(MskConnectController)
    ctl._dlq_cursor_ms = {}
    ctl._dlq_seen_ids = {}
    ctl.seed_dlq_cursor({"/msk-connect/a-cdc": 1000}, {"/msk-connect/a-cdc": {"e1"}})
    cursors, seen = ctl.dlq_cursor_state()
    assert cursors == {"/msk-connect/a-cdc": 1000}
    assert seen == {"/msk-connect/a-cdc": {"e1"}}
    # A different pipeline starts with NO cursor, so its look-back window applies.
    assert cursors.get("/msk-connect/b-cdc") is None


def test_a_retry_resyncs_the_identity_sequence_for_every_loaded_table() -> None:
    """A recovered migration must not repair only part of the schema.

    The first (incomplete) attempt syncs nothing by design, and the retry narrowed the
    sync to the retried subset -- so every table that succeeded on the FIRST attempt kept
    its DSQL sequence at its start value while its rows already occupied those values, and
    the first application insert after cut over could fail with a duplicate key.
    """
    import inspect

    from dsql_migrator.ui.data_migration import _full_load_engine as _engine

    assert "sync_table_names" in inspect.signature(_engine._finalize_run).parameters
    # The retry entry point must hand it the WHOLE prior chunk set, not retry_names.
    retry_src = inspect.getsource(_engine.run_full_load_retry)
    assert "sync_table_names=" in retry_src
    assert "prior_chunks" in retry_src.split("sync_table_names=")[1][:200], (
        "the retry still narrows the identity sync to the retried tables"
    )


def test_the_orphan_pre_gate_reports_liveness_per_page() -> None:
    """Per-FK liveness was too coarse: the pass spends its time INSIDE one FK.

    v0.1.456 reported liveness once per foreign key, but the orphan pre-gate pages a large
    child at 5000 rows per round trip -- ~600 round trips for a 3M-row child -- so a single
    FK left the pass silent for minutes. A LIVE run under an armed 90s watchdog was reaped
    mid-pass with the last liveness report 1.2s after the pass started, which is how this
    was found.
    """
    import inspect

    from dsql_migrator.core.models import ForeignKeyDef
    from dsql_migrator.ui.data_migration import _full_load_engine as _engine

    assert "on_page" in inspect.signature(_engine._count_orphans).parameters
    assert "on_page" in inspect.signature(_engine._count_orphans_keyset).parameters

    # Behaviour: one report per page, not one per call.
    pages = [(0, 10, 5), (0, 20, 5), (0, 30, 2)]   # 3 pages, last one short
    state = {"n": 0}

    class _Cur:
        def execute(self, *_a, **_k):
            return None

        def fetchone(self):
            row = pages[min(state["n"], len(pages) - 1)]
            state["n"] += 1
            return row

        def close(self):
            return None

    class _Conn:
        def cursor(self):
            return _Cur()

    beats: list[int] = []
    total = _engine._count_orphans_keyset(
        _Conn(), "e.child",
        ForeignKeyDef(name="fk", columns=["pid"], referenced_table="e.parent",
                      referenced_columns=["id"]),
        "id", 5, on_page=lambda: beats.append(1),
    )
    assert total == 0
    assert len(beats) == state["n"] == 3, (beats, state)


def test_the_fk_pass_threads_its_heartbeat_into_the_orphan_pre_gate() -> None:
    # Wiring guard: the per-page seam is useless unless the pass actually passes its
    # heartbeat down. Bytecode names, not a source substring.
    from dsql_migrator.ui.data_migration import _full_load_engine as _engine

    code = _engine.apply_preserved_foreign_keys.__code__
    names = set(code.co_names)
    for const in code.co_consts:
        if hasattr(const, "co_names"):
            names |= set(const.co_names)
    assert "_count_orphans" in names
    assert "on_page" in set(code.co_varnames) | set(code.co_names) | {
        n for c in code.co_consts if hasattr(c, "co_varnames") for n in c.co_varnames
    } or True   # kwarg name lives in co_consts as a keyword tuple; checked below
    # The keyword really is passed: it appears in the call's keyword-argument names.
    kwnames = [c for c in code.co_consts if isinstance(c, tuple) and "on_page" in c]
    assert kwnames, "the FK pass no longer passes on_page into the orphan pre-gate"


def test_the_orphan_pre_gates_run_concurrently_not_one_after_another() -> None:
    """The FK pass was serial over every FK, and the pre-gate is its whole cost.

    Measured live: 0.022 ms per child row after v0.1.459, ~6 min for a 15-FK / 15.5M-row
    schema. Removing the pre-gate is not an option -- a failed `ALTER TABLE ASYNC ...
    VALIDATE CONSTRAINT` is unobservable on DSQL (convalidated stays false, no sys.jobs row,
    and a synchronous VALIDATE is FeatureNotSupported), so the tool's own count is the only
    reliable verdict. Concurrency is the remaining lever.
    """
    import threading
    import time

    from dsql_migrator.core.models import ForeignKeyDef
    from dsql_migrator.ui.data_migration import _full_load_engine as _engine

    pending = []
    for i in range(8):
        fk = ForeignKeyDef(name=f"fk{i}", columns=["pid"],
                           referenced_table="e.parent", referenced_columns=["id"])
        pending.append((f"e.child{i}", f"fk{i}", fk, "ALTER TABLE ..."))

    live = {"now": 0, "peak": 0}
    lock = threading.Lock()
    conns: list = []

    class _Conn:
        def close(self):
            return None

    def factory():
        c = _Conn()
        conns.append(c)
        return c

    def slow_count(_conn, _table, _fk, _pk, on_page=None):  # noqa: ANN001
        with lock:
            live["now"] += 1
            live["peak"] = max(live["peak"], live["now"])
        try:
            if on_page is not None:
                on_page()
            time.sleep(0.25)
            return 0
        finally:
            with lock:
                live["now"] -= 1

    real = _engine._count_orphans
    _engine._count_orphans = slow_count
    beats: list[int] = []
    try:
        t0 = time.monotonic()
        out = _engine._pregate_orphans(
            pending, factory, {}, beat=lambda: beats.append(1), stopped=lambda: False
        )
        elapsed = time.monotonic() - t0
    finally:
        _engine._count_orphans = real

    assert len(out) == 8 and all(v == 0 for v in out.values()), out
    # Serial would be 8 x 0.25s = 2.0s; concurrent must be far less.
    assert elapsed < 1.2, f"the pre-gates ran serially ({elapsed:.2f}s for 8 x 0.25s)"
    assert live["peak"] > 1, f"only {live['peak']} pre-gate ran at a time"
    assert live["peak"] <= _engine._FK_PREGATE_WORKERS, "the fan-out is unbounded"
    # The value itself is measured (a live sweep saturated at 16), not arbitrary; the test
    # asserts the BOUND is honoured, so it survives re-tuning.
    assert _engine._FK_PREGATE_WORKERS >= 2
    # Each worker gets its OWN connection: one psycopg connection cannot serve concurrent
    # queries, and they are closed again.
    assert len(conns) == 8, conns
    assert beats, "the pre-gate reported no liveness"


def test_a_failing_pre_gate_falls_back_to_the_serial_check() -> None:
    # The concurrent pass is an OPTIMISATION only: anything it could not determine must fall
    # through to the existing serial pre-check so the verdict and its error handling are
    # unchanged. A wrong answer here would add a constraint over violating rows.
    from dsql_migrator.core.models import ForeignKeyDef
    from dsql_migrator.ui.data_migration import _full_load_engine as _engine

    fk = ForeignKeyDef(name="fk", columns=["pid"], referenced_table="e.parent",
                       referenced_columns=["id"])
    pending = [("e.child", "fk", fk, "ALTER TABLE ...")]

    class _Conn:
        def close(self):
            return None

    def boom(*_a, **_k):
        raise RuntimeError("catalog unreadable")

    real = _engine._count_orphans
    _engine._count_orphans = boom
    try:
        out = _engine._pregate_orphans(
            pending, lambda: _Conn(), {}, beat=lambda: None, stopped=lambda: False
        )
    finally:
        _engine._count_orphans = real
    # Recorded as an exception, NOT as "0 orphans" -- the caller then re-checks serially.
    assert isinstance(out.get(0), Exception), out
    assert not isinstance(out.get(0), int)


def test_the_pre_gate_fan_out_honours_a_stop() -> None:
    # Stop must not be held for a whole concurrent sweep of large children.
    from dsql_migrator.core.models import ForeignKeyDef
    from dsql_migrator.ui.data_migration import _full_load_engine as _engine

    fk = ForeignKeyDef(name="fk", columns=["pid"], referenced_table="e.parent",
                       referenced_columns=["id"])
    pending = [(f"e.c{i}", f"fk{i}", fk, "ALTER ...") for i in range(6)]
    calls = {"n": 0}

    def counted(*_a, **_k):
        calls["n"] += 1
        return 0

    real = _engine._count_orphans
    _engine._count_orphans = counted
    try:
        out = _engine._pregate_orphans(
            pending, lambda: type("C", (), {"close": lambda s: None})(), {},
            beat=lambda: None, stopped=lambda: True,
        )
    finally:
        _engine._count_orphans = real
    assert out == {}, out
    assert calls["n"] == 0, "a stop did not prevent the pre-gate work"


def test_the_load_no_longer_applies_foreign_keys_and_says_so() -> None:
    """The load must report complete when the DATA is complete.

    The orphan pre-check that gates each foreign key is O(child rows) -- measured 28.0 min
    serial / 7.9 min at 8-way for 15 FKs over 15.5M child rows -- and it ran as the last act
    of the load, after every row was already written. So "Full Load" stayed unfinished for
    minutes with nothing left to load. It is an explicit action now, exactly as a CDC
    migration has always applied them at cut over.

    The risk that buys is a FORGOTTEN click, and an unapplied constraint is invisible (DSQL
    cannot tell us later -- a failed async VALIDATE is unobservable). So the run summary MUST
    name the outstanding count.
    """
    import inspect

    import dsql_migrator.ui.data_migration._full_load_engine as engine

    src = inspect.getsource(engine.run_full_load)
    assert "_apply_foreign_keys(" not in src, (
        "the load applies foreign keys again; that holds its completion for minutes"
    )
    assert "pending_foreign_key_count(" in src

    events: list = []
    import pytest
    monkeypatch = pytest.MonkeyPatch()
    monkeypatch.setattr(engine, "log_activity", lambda *a, **k: events.append((a, k)))

    class _H:
        cancelled = False

    try:
        engine._finalize_run(
            _H(), "j", ["a", "b"], engine._RunCounts(real_failed=0, quarantined=0),
            object(), accept_quarantined_rows=False, foreign_keys_pending=3,
        )
    finally:
        monkeypatch.undo()
    detail = [k.get("detail", "") for _a, k in events if "run completed" in str(_a)][0]
    assert "3 foreign key(s) NOT YET APPLIED" in detail
    assert "Apply foreign keys" in detail, "the summary must name the action to take"


def test_pending_foreign_key_count_is_zero_for_a_cdc_migration() -> None:
    # A CDC migration applies them at CUT OVER, after the stream drains -- never here. If
    # this counted them, the Data Migration step would show an action that must not run yet
    # (an FK during the stream makes the sink dead-letter a violation, SQLSTATE 23503).
    from dsql_migrator.ui.data_migration import pending_foreign_key_count

    class _Conv:
        foreign_key_ddls = ("ALTER TABLE a ADD CONSTRAINT x ...",)

    class _Inputs:
        is_cdc_migration = False
        cdc_coexisting = False
        cdc_stack_name = None
        table_conversions = {"a": _Conv(), "b": _Conv()}

    class _M:
        def __init__(self, inputs):
            self._inputs = inputs

    plain = _Inputs()
    assert pending_foreign_key_count(_M(plain)) == 2

    for flag, value in (("is_cdc_migration", True), ("cdc_coexisting", True),
                        ("cdc_stack_name", "dsql-cdc-x")):
        cdc = _Inputs()
        setattr(cdc, flag, value)
        assert pending_foreign_key_count(_M(cdc)) == 0, flag


def test_outstanding_foreign_keys_are_rendered_as_an_error_not_a_quiet_button() -> None:
    """A forgotten click must not be easy: the outstanding state is loud, or it is a trap."""
    from dsql_migrator.ui.data_migration._full_load_ui import (
        _render_foreign_key_action,
    )

    class _Ui:
        def __init__(self):
            self.notices: list = []
            self.buttons: list = []

        class _El:
            def __init__(self, ui, kind, text=""):
                self._ui, self._kind, self._text = ui, kind, text
            def __enter__(self): return self
            def __exit__(self, *e): return False
            def props(self, spec="", *a, **k):
                if self._kind == "button":
                    self._ui.buttons.append((self._text, str(spec)))
                return self
            def tooltip(self, text="", *a, **k):
                if self._kind == "button":
                    self._ui.buttons.append((self._text, "tooltip:" + str(text)))
                return self
            def __getattr__(self, _n): return lambda *a, **k: self

        def button(self, text="", on_click=None, *a, **k):
            return _Ui._El(self, "button", str(text))

        def label(self, text="", *a, **k):
            self.notices.append(str(text)); return _Ui._El(self, "o")

        def __getattr__(self, _n):
            return lambda *a, **k: _Ui._El(self, "o")

    # Outstanding, connections verified -> loud notice + an enabled action.
    ui = _Ui()
    _render_foreign_key_action(
        ui, terminal=True, pending=15, applied=None,
        apply_foreign_keys=lambda: None, connections_ready=True,
    )
    text = " ".join(ui.notices)
    assert "15 foreign key(s) not yet applied" in text, ui.notices
    assert "referential integrity is NOT in place" in text.replace("  ", " ") or \
        "NOT in place" in text, ui.notices
    btns = [b for b in ui.buttons if b[0] == "Apply foreign keys"]
    assert btns and all("disable" not in b[1] for b in btns)

    # Unverified connection -> shown, disabled, with the reason.
    ui2 = _Ui()
    _render_foreign_key_action(
        ui2, terminal=True, pending=15, applied=None,
        apply_foreign_keys=lambda: None, connections_ready=False,
    )
    assert any("disable" in b[1] for b in ui2.buttons if b[0] == "Apply foreign keys")

    # Already applied cleanly -> a success statement, no action.
    ui3 = _Ui()
    _render_foreign_key_action(
        ui3, terminal=True, pending=0, applied=(15, 0, 0),
        apply_foreign_keys=lambda: None, connections_ready=True,
    )
    assert "15 applied" in " ".join(ui3.notices)
    assert not [b for b in ui3.buttons if b[0] == "Apply foreign keys"]

    # Applied with skips -> must NOT read as a clean success.
    ui4 = _Ui()
    _render_foreign_key_action(
        ui4, terminal=True, pending=0, applied=(13, 2, 0),
        apply_foreign_keys=lambda: None, connections_ready=True,
    )
    joined = " ".join(ui4.notices)
    assert "13 applied" in joined and "2 skipped" in joined

    # While the load still runs -> nothing yet.
    ui5 = _Ui()
    _render_foreign_key_action(
        ui5, terminal=False, pending=15, applied=None,
        apply_foreign_keys=lambda: None, connections_ready=True,
    )
    assert not ui5.buttons and not ui5.notices


def test_the_fk_action_never_writes_the_full_load_job_slot() -> None:
    """Applying foreign keys must ADD to the load's result, not replace it.

    The action was submitted with `migration_state.job_id = job_manager.submit(work)` --
    copied from the retry path, where the new job IS the load. Here it made the Full Load
    panel read the FK job instead: per-table rows became "No data available", 7/7 settled
    became 0/0, the completion badge vanished, and the EXPORT WATERMARK was replaced by "the
    consistency point is captured when the migration starts". CDC then reported "no usable
    Full Load watermark", leaving the operator to choose between CDC and referential
    integrity -- destroyed by the very action the tool told them to run.
    """
    import inspect

    from dsql_migrator.ui import data_migration as dm
    from dsql_migrator.ui.data_migration._state import DataMigrationState

    import re

    src = inspect.getsource(dm.build_data_migration_screen)
    # Count ASSIGNMENTS, not mentions: exactly two are legitimate -- starting the load, and
    # the retry (there the new job IS the load). A third means something else re-keyed the
    # slot the Full Load panel and the CDC handoff read.
    writes = re.findall(r"migration_state\.job_id\s*=(?!=)", src)
    assert len(writes) == 2, (
        f"{len(writes)} writes to migration_state.job_id; only starting the load and the "
        "retry may re-key it. A third erases the load's per-table rows, completion badge "
        "and export watermark, and blocks the CDC handoff."
    )
    action = src[src.index("def apply_foreign_keys_now("):]
    action = action[:action.index("def accept_quarantine_and_continue(")]
    assert not re.search(r"migration_state\.job_id\s*=(?!=)", action), (
        "the FK action writes the Full Load's job slot again"
    )
    assert "set_fk_apply_job(" in action

    # The slots are genuinely separate, and the setter does not touch job_id.
    state = DataMigrationState()
    state.job_id = "load-job"
    state.set_fk_apply_job("fk-job")
    assert state.job_id == "load-job", "the load's job slot was overwritten"
    assert state.fk_apply_job_id == "fk-job"
    state.set_fk_apply_progress(2, 6)
    assert state.fk_apply_progress == (2, 6)
    assert state.job_id == "load-job"


def test_outstanding_foreign_keys_read_as_a_next_step_not_a_failure() -> None:
    # This notice sits directly under a GREEN "Full Load complete". A red card there reads as
    # "my load failed" -- a workshop participant read it exactly that way. The load DID
    # succeed; foreign keys are the next required step, which is what `warning` means here.
    import inspect

    from dsql_migrator.ui.data_migration import _full_load_ui as ui_mod

    src = inspect.getsource(ui_mod._render_foreign_key_action)
    outstanding = src[src.index("not yet applied") - 400:src.index("not yet applied")]
    assert 'tone="error"' not in outstanding, (
        "the outstanding-FK notice is error-toned again; under a green 'complete' banner "
        "that reads as a failed load"
    )
    assert 'tone="warning"' in outstanding
    assert "The load itself succeeded" in src


def test_a_running_fk_apply_shows_progress_and_a_way_to_stop() -> None:
    """No confirm dialog, no spinner, no count -- the operator assumes it hung and re-clicks.

    The card itself warns the orphan pre-check "reads the whole child table", so a running
    state has to be visible and stoppable.
    """
    from dsql_migrator.ui.data_migration._full_load_ui import (
        _render_foreign_key_action,
    )

    class _Ui:
        def __init__(self):
            self.texts: list = []
            self.buttons: list = []
            self.spinners = 0

        class _El:
            def __init__(self, ui, kind="o", text=""):
                self._ui, self._kind, self._text = ui, kind, text
            def __enter__(self): return self
            def __exit__(self, *e): return False
            def props(self, spec="", *a, **k):
                if self._kind == "button":
                    self._ui.buttons.append((self._text, str(spec)))
                return self
            def __getattr__(self, _n): return lambda *a, **k: self

        def button(self, text="", on_click=None, *a, **k):
            return _Ui._El(self, "button", str(text))

        def label(self, text="", *a, **k):
            self.texts.append(str(text)); return _Ui._El(self)

        def spinner(self, *a, **k):
            self.spinners += 1; return _Ui._El(self)

        def __getattr__(self, _n):
            return lambda *a, **k: _Ui._El(self)

    stopped: list = []
    ui = _Ui()
    _render_foreign_key_action(
        ui, terminal=True, pending=6, applied=None,
        apply_foreign_keys=lambda: None, connections_ready=True,
        running=True, progress=(2, 6), cancel_foreign_keys=lambda: stopped.append(1),
    )
    joined = " ".join(ui.texts)
    assert "2 of 6 done" in joined, ui.texts
    assert ui.spinners == 1, "no spinner while it runs"
    stop = [b for b in ui.buttons if b[0] == "Stop applying"]
    assert stop, f"no way to stop; buttons={[b[0] for b in ui.buttons]}"
    # While running, the start button must NOT also be offered (double-click re-runs it).
    assert not [b for b in ui.buttons if b[0] == "Apply foreign keys"], ui.buttons


def test_the_schema_conversion_notices_name_the_explicit_action() -> None:
    # Both notices said foreign keys are "(re)created at the end of Full Load", which reads
    # as automatic. They are not: the operator clicks a button.
    import inspect

    from dsql_migrator.ui import schema_conversion as sc

    src = inspect.getsource(sc)
    assert "(re)created at the end of Full Load" not in src
    assert "as a post-load ALTER TABLE … ADD CONSTRAINT pass after Full Load" not in src
    # Both surviving notices must name the button.
    fk_notices = [
        chunk for chunk in src.split("render_notice(")
        if "Foreign keys" in chunk[:400] and "not" in chunk[:400]
    ]
    assert len(fk_notices) >= 2, len(fk_notices)
    for chunk in fk_notices:
        assert "Apply foreign keys" in chunk[:1400], chunk[:200]


# --------------------------------------------------------------------------- #
# "Apply foreign keys": the progress card must actually advance and then settle
#
# Reported from a workshop on 0.1.463: the card appeared correctly (0 of 6, spinner,
# Stop applying, start button withdrawn) and then NEVER changed -- polled for 110s, all
# "0 of 6 done" -- and after all six constraints existed on the target (convalidated=t,
# checked in psql) the card was STILL spinning until the page was reloaded by hand. Two
# independent causes, both covered here:
#   1. no per-FK progress was ever published: the action wrote only (0, total) before
#      submitting and (total, total) in a finally;
#   2. the card is rendered inside the step's @ui.refreshable live region, but its inputs
#      were passed as VALUES captured at page render, and nothing re-armed the poll once
#      the LOAD job was terminal -- so the region never re-read them and never re-rendered.
# --------------------------------------------------------------------------- #


def _three_fk_conv():
    """One child with three FKs, so a pass can settle them to three different buckets."""
    from dsql_migrator.core.converter import TableConversion
    from dsql_migrator.core.models import ForeignKeyDef

    ddls = [
        f'ALTER TABLE "child" ADD CONSTRAINT "fk_{n}" FOREIGN KEY ("{n}_id") '
        f'REFERENCES "p{n}" ("id") NOT VALID'
        for n in ("a", "b", "c")
    ]
    return ddls, TableConversion(
        table="child",
        target_ddl='CREATE TABLE "child" ("id" integer PRIMARY KEY)',
        foreign_key_ddls=ddls,
        preserved_foreign_keys=[
            ForeignKeyDef(
                name=f"fk_{n}", columns=[f"{n}_id"],
                referenced_table=f"p{n}", referenced_columns=["id"],
            )
            for n in ("a", "b", "c")
        ],
    )


def test_fk_pass_reports_progress_for_every_settled_fk(monkeypatch) -> None:
    import dsql_migrator.ui.data_migration._full_load_engine as engine

    ddls, conv = _three_fk_conv()
    # Mixed outcomes so the count cannot be an artefact of the happy path alone:
    # fk_a applies, fk_b has orphans (skipped), fk_c's ALTER raises (failed).
    monkeypatch.setattr(engine, "_pregate_orphans",
                        lambda pending, *a, **k: {0: 0, 1: 4, 2: 0})
    monkeypatch.setattr(engine, "validate_foreign_key", lambda *a, **k: None)

    def _apply(add_ddl, *, connection_factory):
        if '"fk_c"' in add_ddl:
            raise RuntimeError("ALTER rejected")

    monkeypatch.setattr(engine, "apply_foreign_key", _apply)
    monkeypatch.setattr(engine, "log_activity", lambda *a, **k: None)

    seen: list[tuple[int, int]] = []
    result = engine.apply_preserved_foreign_keys(
        {"child": conv}, lambda: _FkProbeConnection(0), on_progress=lambda d, t: seen.append((d, t))
    )
    assert result == (1, 1, 1), result
    # The denominator is the real number of FKs the pass works through, published up front
    # so the card never shows a total it will not reach.
    assert seen[0] == (0, 3), seen
    # Every intermediate count appears, and the pass ends at "all three settled".
    assert seen[-1] == (3, 3), seen
    assert [d for d, _t in seen] == sorted(d for d, _t in seen), f"not monotonic: {seen}"
    assert {d for d, _t in seen} == {0, 1, 2, 3}, seen
    assert all(t == 3 for _d, t in seen), seen


def test_fk_pass_final_progress_is_the_partial_count_when_stopped(monkeypatch) -> None:
    # Stop applying must leave the card reporting what it ACTUALLY finished. The old
    # unconditional (total, total) write would have claimed a stopped pass was complete.
    import dsql_migrator.ui.data_migration._full_load_engine as engine

    _ddls, conv = _three_fk_conv()
    monkeypatch.setattr(engine, "_pregate_orphans", lambda pending, *a, **k: {0: 0, 1: 0, 2: 0})
    monkeypatch.setattr(engine, "validate_foreign_key", lambda *a, **k: None)
    monkeypatch.setattr(engine, "apply_foreign_key", lambda add_ddl, *, connection_factory: None)
    monkeypatch.setattr(engine, "log_activity", lambda *a, **k: None)

    calls = {"n": 0}

    def _stop() -> bool:
        # False for the first FK's check, then True: exactly one FK settles.
        calls["n"] += 1
        return calls["n"] > 1

    seen: list[tuple[int, int]] = []
    applied, skipped, failed = engine.apply_preserved_foreign_keys(
        {"child": conv}, lambda: _FkProbeConnection(0),
        should_cancel=_stop, on_progress=lambda d, t: seen.append((d, t)),
    )
    assert (applied, skipped, failed) == (1, 0, 0)
    assert seen[-1] == (1, 3), f"a stopped pass must not report itself complete: {seen}"


def test_fk_pass_survives_a_progress_reporter_that_raises(monkeypatch) -> None:
    # Progress is display only; a reporter error must never cost a foreign key.
    import dsql_migrator.ui.data_migration._full_load_engine as engine

    _ddls, conv = _three_fk_conv()
    monkeypatch.setattr(engine, "_pregate_orphans", lambda pending, *a, **k: {0: 0, 1: 0, 2: 0})
    monkeypatch.setattr(engine, "validate_foreign_key", lambda *a, **k: None)
    monkeypatch.setattr(engine, "apply_foreign_key", lambda add_ddl, *, connection_factory: None)
    monkeypatch.setattr(engine, "log_activity", lambda *a, **k: None)

    def _boom(_done, _total):
        raise RuntimeError("the UI went away")

    assert engine.apply_preserved_foreign_keys(
        {"child": conv}, lambda: _FkProbeConnection(0), on_progress=_boom
    ) == (3, 0, 0)


def test_apply_foreign_keys_wrapper_forwards_the_progress_reporter() -> None:
    import dsql_migrator.ui.data_migration._full_load_engine as engine

    got = {}

    class _Migrator:
        def apply_foreign_keys(self, heartbeat=None, should_cancel=None, on_progress=None):
            got["on_progress"] = on_progress
            if on_progress is not None:
                on_progress(2, 5)
            return (2, 0, 0)

    seen: list[tuple[int, int]] = []
    assert engine._apply_foreign_keys(
        _Migrator(), None, on_progress=lambda d, t: seen.append((d, t))
    ) == (2, 0, 0)
    assert got["on_progress"] is not None
    assert seen == [(2, 5)], "the reporter must reach the pass, not be swallowed"


def test_apply_foreign_keys_wrapper_still_drives_a_hook_without_progress() -> None:
    # The degrade chain must drop on_progress FIRST: a double that predates it keeps
    # heartbeat/should_cancel instead of losing both to a single TypeError.
    import dsql_migrator.ui.data_migration._full_load_engine as engine

    got = {}

    class _Older:
        def apply_foreign_keys(self, heartbeat=None, should_cancel=None):
            got["heartbeat"] = heartbeat is not None
            got["should_cancel"] = should_cancel is not None
            return (1, 0, 0)

    assert engine._apply_foreign_keys(_Older(), None, on_progress=lambda d, t: None) == (1, 0, 0)
    assert got == {"heartbeat": True, "should_cancel": True}


def test_fk_card_inputs_are_providers_not_values_captured_at_page_render() -> None:
    # THE staleness defect. The step renders the FK card inside its @ui.refreshable live
    # region, so a value evaluated at the call site is frozen for the life of the page:
    # refreshing the region replayed "not running, no result" from before the click, which
    # is why the spinner never became "6 applied" without a manual reload.
    import inspect

    import dsql_migrator.ui.data_migration as dm

    src = inspect.getsource(dm.build_data_migration_screen)
    for frozen in (
        "foreign_keys_running=_fk_apply_running()",
        "foreign_keys_progress=migration_state.fk_apply_progress,",
        "foreign_keys_applied=migration_state.fk_apply_result,",
        "foreign_keys_pending=fk_pending_count(),",
    ):
        assert frozen not in src, (
            f"{frozen!r} is evaluated once at page render; the live region must be given a "
            "provider it can re-read on every refresh"
        )
    assert "foreign_keys_running=_fk_apply_running," in src
    assert "foreign_keys_progress=lambda: migration_state.fk_apply_progress," in src


def test_fk_card_providers_are_resolved_on_every_refresh() -> None:
    # Not just "a callable is passed" -- the renderer must CALL it. Drive the real inner
    # renderer through the resolver and show a second render sees the new value.
    from dsql_migrator.ui.data_migration import _full_load_ui as flu

    state = {"running": True, "progress": (1, 6)}
    assert flu._call_or(lambda: state["running"], False) is True
    assert flu._call_or(lambda: state["progress"], None) == (1, 6)
    state["running"], state["progress"] = False, (6, 6)
    assert flu._call_or(lambda: state["running"], False) is False
    assert flu._call_or(lambda: state["progress"], None) == (6, 6)
    # A plain value still works (existing callers/tests), and a raising provider falls back
    # rather than tearing down the region it renders into.
    assert flu._call_or(7, 0) == 7
    assert flu._call_or(None, "d") == "d"

    def _boom():
        raise RuntimeError("status read failed")

    assert flu._call_or(_boom, "fallback") == "fallback"


def test_the_live_region_rearms_its_poll_while_only_the_fk_job_runs() -> None:
    # The FK pass is a SEPARATE job that starts only once the LOAD is terminal, so gating
    # the re-arm on the load alone left nothing to refresh the card: it could neither
    # advance its counter nor replace the spinner with the result.
    import inspect

    from dsql_migrator.ui.data_migration import _full_load_ui as flu

    src = inspect.getsource(flu._render_full_load_step)
    assert "if running or fk_running:" in src, (
        "the live region must re-arm its poll while the foreign-key job runs, not only "
        "while the load does"
    )
    # And the poll itself must not fall into its terminal branch (a FULL page refresh every
    # tick, and no re-arm) while that job is live.
    assert 'if bool(_call_or(foreign_keys_running, False)):\n            _live_detail.refresh()' in src


def test_the_fk_action_publishes_per_fk_progress_and_no_fake_completion() -> None:
    import inspect

    import dsql_migrator.ui.data_migration as dm

    src = inspect.getsource(dm.build_data_migration_screen)
    assert "on_progress=migration_state.set_fk_apply_progress," in src, (
        "the action must hand the engine a reporter, or the card cannot advance"
    )
    # The old finally wrote (total, total) unconditionally: with Stop that claimed a
    # partially-applied pass was complete.
    assert "set_fk_apply_progress(total, total)" not in src


# --------------------------------------------------------------------------- #
# A STOPPED foreign-key pass must not read as a clean success
#
# "Stop applying" breaks the engine's loop, so the foreign keys it never reached land in
# no bucket: stopping after 2 of 6 returns (2, 0, 0). The card reported only the buckets,
# so it rendered a GREEN "Foreign keys: 2 applied -- referential integrity is in place on
# the target" while four constraints did not exist, and withdrew the Apply button. Nothing
# clears fk_apply_result, so that screen was the end of the road: Start over was the only
# way out. Present since v0.1.461; v0.1.467 only made it VISIBLE (before, the card needed a
# manual page reload to update at all).
# --------------------------------------------------------------------------- #


class _FkCardUi:
    """NiceGUI double that records notice text and buttons for the FK card."""

    def __init__(self):
        self.notices: list[str] = []
        self.buttons: list[tuple[str, str]] = []
        self.tones: list[str] = []

    class _El:
        def __init__(self, ui, kind="o", text=""):
            self._ui, self._kind, self._text = ui, kind, text
        def __enter__(self): return self
        def __exit__(self, *_e): return False
        def props(self, spec="", *_a, **_k):
            if self._kind == "button":
                self._ui.buttons.append((self._text, str(spec)))
            return self
        def tooltip(self, *_a, **_k): return self
        def classes(self, *_a, **_k): return self
        def __getattr__(self, _n): return lambda *_a, **_k: self

    def button(self, text="", on_click=None, *_a, **_k):
        return _FkCardUi._El(self, "button", str(text))

    def label(self, text="", *_a, **_k):
        self.notices.append(str(text))
        return _FkCardUi._El(self)

    def icon(self, name="", *_a, **_k):
        self.tones.append(str(name))
        return _FkCardUi._El(self)

    def __getattr__(self, _n):
        return lambda *_a, **_k: _FkCardUi._El(self)


def _render_fk_card(*, pending, applied, terminal=True, connections_ready=True):
    from dsql_migrator.ui.data_migration._full_load_ui import _render_foreign_key_action

    ui = _FkCardUi()
    _render_foreign_key_action(
        ui, terminal=terminal, pending=pending, applied=applied,
        apply_foreign_keys=lambda: None, connections_ready=connections_ready,
    )
    return ui, " ".join(ui.notices)


def _has_apply_button(ui) -> bool:
    return any(b[0] == "Apply foreign keys" for b in ui.buttons)


def test_a_stopped_fk_pass_is_not_reported_as_referential_integrity_in_place() -> None:
    # THE defect: 2 of 6 applied, then stopped.
    ui, text = _render_fk_card(pending=6, applied=(2, 0, 0))
    assert "Referential integrity is in place" not in text, (
        "a stopped pass left 4 constraints missing; this claims the opposite: " + text
    )
    assert "2 of 6 applied" in text, text
    assert "NOT reached" in text or "NOT in place" in text, text
    # And it must stay actionable -- the operator who clicked Stop needs a way back.
    assert _has_apply_button(ui), "the Apply action must remain so the pass can be resumed"


def test_a_stopped_fk_pass_is_not_toned_as_success() -> None:
    # The tone carries the severity in this design system, so assert it directly rather
    # than inferring it from the copy.
    import dsql_migrator.ui.data_migration._full_load_ui as flu

    captured: list[str] = []
    real = flu.render_notice
    try:
        flu.render_notice = lambda ui, *, tone="info", header="", body="", **k: (
            captured.append(tone), real(ui, tone=tone, header=header, body=body, **k)
        )[-1]
        _render_fk_card(pending=6, applied=(2, 0, 0))
    finally:
        flu.render_notice = real
    assert captured and "success" not in captured, captured


def test_a_complete_fk_pass_still_reads_as_a_clean_success() -> None:
    # The negative control: nothing outstanding must still be green, or the fix would just
    # alarm every successful run.
    import dsql_migrator.ui.data_migration._full_load_ui as flu

    captured: list[str] = []
    real = flu.render_notice
    try:
        flu.render_notice = lambda ui, *, tone="info", header="", body="", **k: (
            captured.append(tone), real(ui, tone=tone, header=header, body=body, **k)
        )[-1]
        ui, text = _render_fk_card(pending=6, applied=(6, 0, 0))
    finally:
        flu.render_notice = real
    assert "success" in captured, captured
    assert "6 applied" in text and "of 6 applied" not in text, text
    assert "Referential integrity is in place" in text, text
    assert not _has_apply_button(ui), "nothing is outstanding, so offer no action"


def test_a_pass_that_died_does_not_render_as_a_green_zero_applied() -> None:
    # _apply_foreign_keys swallows an exception from the pass and returns (0, 0, 0). With
    # the buckets alone that was a green "0 applied -- referential integrity is in place".
    ui, text = _render_fk_card(pending=6, applied=(0, 0, 0))
    assert "Referential integrity is in place" not in text, text
    assert "0 of 6 applied" in text, text
    assert _has_apply_button(ui)


def test_skips_and_failures_are_still_reported_and_need_no_resume() -> None:
    # Every FK was reached: 4 applied, 2 skipped for orphan rows. Outstanding is 0, so the
    # card must NOT invent a "not reached" claim, and must not offer a pointless resume --
    # re-running would only repeat the same orphan verdict.
    ui, text = _render_fk_card(pending=6, applied=(4, 2, 0))
    assert "2 skipped (orphan rows)" in text, text
    assert "NOT reached" not in text, text
    assert "4 applied" in text and "of 6 applied" not in text, text
    assert not _has_apply_button(ui)


def test_outstanding_is_not_invented_when_the_total_is_unknown() -> None:
    # pending=0 means "no total available" (e.g. the advisory count failed). Deriving
    # outstanding from it would report every applied FK as missing.
    ui, text = _render_fk_card(pending=0, applied=(15, 0, 0))
    assert "15 applied" in text and "NOT reached" not in text, text
    assert not _has_apply_button(ui)


def test_the_total_provider_no_longer_zeroes_itself_once_a_result_exists() -> None:
    # The card derives "outstanding" as total - settled, so a provider that returns 0 as
    # soon as fk_apply_result is set makes the whole fix a no-op -- outstanding is always 0
    # in exactly the branch that needs it.
    import inspect

    import dsql_migrator.ui.data_migration as dm

    src = inspect.getsource(dm.build_data_migration_screen)
    start = src.index("def fk_pending_count()")
    body = src[start:start + src[start:].index("def cancel_foreign_keys()")]
    assert "if migration_state.fk_apply_result is not None:" not in body, (
        "fk_pending_count must report the run's TOTAL; zeroing it on a result hides a "
        "stopped pass entirely:\n" + body
    )


def test_resuming_a_stopped_fk_pass_reports_as_running() -> None:
    """A resumed pass must clear the previous result, or it is invisible and unstoppable.

    `_fk_apply_running()` returns False while `fk_apply_result` is set, and nothing used to
    clear it. Keeping the Apply button after a stopped pass (so it can be resumed) therefore
    opened a path where the resumed job reported NOT running for its whole duration: the card
    re-rendered the stale "2 of 6 applied" summary with no spinner, no per-FK progress and no
    "Stop applying" (the running branch owns the cancel), the poll never re-armed
    (`if running or fk_running`), and the still-enabled Apply button could submit a SECOND
    concurrent pass whose job id displaced the first -- leaving the first uncancellable.
    """
    import inspect

    import dsql_migrator.ui.data_migration as dm

    src = inspect.getsource(dm.build_data_migration_screen)
    start = src.index("def apply_foreign_keys_now()")
    body = src[start:start + src[start:].index("def _fk_apply_running()")]
    assert "set_fk_apply_result(None)" in body, (
        "the action must clear the previous result, or a resumed pass never reports as "
        "running:\n" + body
    )
    # Ordering is load-bearing: clearing AFTER submit can wipe a fast worker's fresh result.
    assert body.index("set_fk_apply_result(None)") < body.index("job_manager.submit(work)"), (
        "the result must be cleared BEFORE the job is submitted"
    )


def test_the_denominator_falls_back_to_the_passs_own_total() -> None:
    # `pending` is advisory: its provider returns 0 on ANY error and 0 by design for a CDC
    # run. With a 0 total the outstanding count clamps to 0 and the card printed the exact
    # green "referential integrity is in place" this branch exists to prevent -- so it falls
    # back to the total the engine published on `progress`.
    from dsql_migrator.ui.data_migration._full_load_ui import _render_foreign_key_action

    ui = _FkCardUi()
    _render_foreign_key_action(
        ui, terminal=True, pending=0, applied=(2, 0, 0), progress=(2, 6),
        apply_foreign_keys=lambda: None, connections_ready=True,
    )
    text = " ".join(ui.notices)
    assert "Referential integrity is in place" not in text, text
    assert "2 of 6 applied" in text and "of 0 applied" not in text, text
    assert _has_apply_button(ui)


def test_the_card_does_not_promise_an_action_it_will_not_render() -> None:
    # "Apply them below" was printed even where the button is not rendered (load not
    # terminal, or no handler wired), telling the operator to use a control that is absent.
    from dsql_migrator.ui.data_migration._full_load_ui import _render_foreign_key_action

    ui = _FkCardUi()
    _render_foreign_key_action(
        ui, terminal=True, pending=6, applied=(2, 0, 0),
        apply_foreign_keys=None, connections_ready=True,   # nothing to click
    )
    text = " ".join(ui.notices)
    assert "NOT reached" in text, text
    assert "below" not in text, "promises a button that is not rendered: " + text
    assert not _has_apply_button(ui)


def test_resuming_says_what_it_costs() -> None:
    # The outstanding-state notice (which carries the "reads the whole child table" warning)
    # is suppressed under the applied summary, so this render is the only place the cost of
    # resuming can be stated -- and resume re-checks EVERY foreign key, not just the rest.
    ui, text = _render_fk_card(pending=6, applied=(2, 0, 0))
    assert "EVERY foreign key" in text and "whole child table" in text, text


def test_cutover_does_not_claim_foreign_keys_were_applied_automatically() -> None:
    # Since v0.1.461 foreign keys are an explicit action, but the Cut over screen still told
    # a Full-Load-only operator they "were applied automatically at the end of the load" --
    # so someone who never clicked it, or clicked Stop, was told integrity was in place.
    import inspect

    import dsql_migrator.ui.validation as v

    src = inspect.getsource(v)
    assert "were applied automatically at the" not in src, (
        "the cut-over copy still asserts the load applied the foreign keys"
    )
    assert 'explicit \\"Apply foreign keys\\" action' in src, (
        "the copy must name the explicit action that does apply them"
    )


def test_a_reload_that_replaces_a_table_clears_the_stale_fk_result() -> None:
    """A dropped table loses its foreign keys, so "N applied" must not survive the reload.

    Structural, because the two write sites live inside closures of
    ``build_data_migration_screen`` that cannot be driven without the whole screen. The
    reachable case is the tool's OWN recovery advice: "Exclude column & reload" forces
    ``set_replace_targets({table})``, DSQL drops that table's foreign keys with the table,
    and nothing cleared ``fk_apply_result`` -- so the card went on reporting "referential
    integrity is in place on the target" for constraints that no longer existed.
    """
    import inspect

    import dsql_migrator.ui.data_migration as dm

    src = inspect.getsource(dm.build_data_migration_screen)

    # 1. a fresh load supersedes any earlier application outright.
    fresh = src[src.index("migration_state.clear_outputs()"):]
    fresh = fresh[:fresh.index("set_prereq_gated_mode")]
    assert "set_fk_apply_result(None)" in fresh, (
        "a new load must clear the previous foreign-key result:\n" + fresh
    )

    # 2. a retry clears it ONLY when it will actually replace a table -- an append-only
    #    retry leaves the constraints in place, and clearing then would nag for no reason.
    retry = src[src.index("retry_replace = ("):]
    retry = retry[:retry.index("_retry_conversion = SchemaConverter")]
    assert "if retry_replace:" in retry, (
        "the retry's clear must be scoped to replacements:\n" + retry
    )
    assert "set_fk_apply_result(None)" in retry, retry
    assert retry.index("if retry_replace:") < retry.index("set_fk_apply_result(None)")


def test_a_confirmed_schema_replace_forgets_the_applied_foreign_keys() -> None:
    """A REPLACE recreates target tables, so both steps' FK verdicts stop being true.

    DSQL drops a table's foreign keys with the table. Nothing cleared the verdicts, so Data
    Migration kept rendering a green "N applied -- referential integrity is in place on the
    target" with its Apply button withdrawn, and cut over's finish gate stopped blocking with
    nothing enforced. Wired as an injected callback because Schema Conversion owns neither
    store.
    """
    import inspect

    import dsql_migrator.ui.app as app

    src = inspect.getsource(app._forget_applied_foreign_keys)
    assert "set_fk_apply_result(None)" in src, src
    assert "set_fk_apply_progress(0, 0)" in src, src
    assert "clear_cutover_outcomes()" in src, src

    wiring = inspect.getsource(app)
    assert "on_target_tables_replaced=" in wiring, "the screen is not given the callback"

    # It must fire on "a table is being replaced", NOT on "the pre-drop dropped something":
    # the selector is parent-side only, so replacing a CHILD table destroys its own foreign
    # keys while producing no pair at all.
    import dsql_migrator.ui.schema_conversion as sc

    screen = inspect.getsource(sc.build_schema_conversion_screen)
    assert screen.count("_invalidate_applied_foreign_keys()") >= 2, (
        "both apply paths (bulk and per-object) must invalidate"
    )
    guard = "confirmed and replace_table_names("
    assert guard in screen, screen[:0] or "not gated on a table replace"
    body = screen[screen.index("def _invalidate_applied_foreign_keys"):]
    body = body[:body.index("def _predrop_replace_blocking_foreign_keys")]
    assert "foreign_keys_blocking_replace" not in body, (
        "it must NOT be gated on the pre-drop's pairs -- a replaced CHILD produces none"
    )


# --------------------------------------------------------------------------- #
# An EMPTY live connector listing must clear remembered names, not be ignored
#
# Observed live (event account, 2026-09-20): the Schema Conversion screen warned "CDC is
# streaming to the target — the schema is already applied" for a cdc-stack that had been
# DELETE_COMPLETE for twelve hours, while the Data Migration panel -- from the SAME
# discovery pass -- correctly said "No cdc-stack is deployed yet" and the chip read
# CDC: NOT_STARTED.
#
# Cause: _ensure_cdc_controller stores the controller, then returns on an empty listing
# WITHOUT writing the names. cdc_pipeline_live is
# (controller is not None AND cdc_connector_names), so it stayed TRUE on leftover names --
# and after a restart those come from the session snapshot, restored with no AWS
# confirmation (gated only on the last action not being delete/stop, so a console-side
# delete leaves them). The Schema Conversion warning reads that predicate with no AWS call
# of its own, so nothing else could ever correct it.
# --------------------------------------------------------------------------- #


def test_an_empty_live_listing_clears_remembered_connector_names(monkeypatch) -> None:
    from types import SimpleNamespace

    import dsql_migrator.ui.data_migration._cdc_status as cdc_status
    from dsql_migrator.ui.data_migration._cdc_state import cdc_pipeline_live

    state = DataMigrationState()
    # What a session snapshot restores: the names, with nothing confirming they still exist.
    state.set_cdc_stack_name("dsql-cdc-stack")
    state.set_cdc_connector_names(
        ["dsql-cdc-stack-debezium-source", "dsql-cdc-stack-dsql-sink"]
    )
    state.set_cdc_connector_running_names(["dsql-cdc-stack-debezium-source"])

    class _Controller:
        def list_connectors(self):
            return []  # the stack is gone -- and this is ALSO what an access error returns

    # The builder is imported function-locally, so patch it on its OWN module.
    import dsql_migrator.core.msk_connect_controller as msk

    monkeypatch.setattr(
        msk, "build_msk_connect_controller", lambda *a, **k: _Controller()
    )
    session = SimpleNamespace(
        target_config=SimpleNamespace(region="us-east-2"), aws_profile=None,
        workflow=None, set_workflow=lambda *_a, **_k: None,
    )
    monkeypatch.setattr(cdc_status, "_sync_cdc_step_status", lambda *_a, **_k: None)
    monkeypatch.setattr(cdc_status, "_probe_cdc_stack_phase", lambda *_a, **_k: None)

    # Signature is (migration_state, session) -- not the other way round.
    cdc_status._ensure_cdc_controller(state, session)

    assert state.cdc_connector_names == [], (
        "an empty live listing must CLEAR the remembered names; leaving them makes "
        "cdc_pipeline_live true with zero connectors in AWS"
    )
    assert state.cdc_connector_running_names == []
    assert state.cdc_controller is not None, "the controller is still stored (a later deploy needs it)"
    assert cdc_pipeline_live(state) is False, (
        "this is the predicate behind Schema Conversion's 'CDC is streaming' warning, "
        "which makes no AWS call of its own -- so it must not outlive the evidence"
    )


def test_a_failed_connector_read_does_not_clear_the_known_names(monkeypatch) -> None:
    """"Cannot see them" is not "they do not exist".

    ``list_connectors()`` folds a missing ``kafkaconnect:ListConnectors`` permission into an
    empty list, so v0.1.474's "an empty listing clears the names" -- correct for a stack that
    really is gone -- would report a LIVE, streaming pipeline as absent. That is the more
    dangerous lie of the two: an operator who believes nothing is streaming may edit the CDC
    inputs or apply foreign keys, and applying them while the sink streams out-of-order child
    rows dead-letters them (23503). A failed read must leave the state UNKNOWN.
    """
    from types import SimpleNamespace

    import dsql_migrator.core.msk_connect_controller as msk
    import dsql_migrator.ui.data_migration._cdc_status as cdc_status
    from dsql_migrator.ui.data_migration._cdc_state import cdc_pipeline_live

    live = ["dsql-cdc-stack-debezium-source", "dsql-cdc-stack-dsql-sink"]

    class _Denied:
        """What a task without kafkaconnect:ListConnectors sees."""

        def list_connectors_checked(self):
            return False, []

        def list_connectors(self):
            return []

    monkeypatch.setattr(msk, "build_msk_connect_controller", lambda *a, **k: _Denied())
    monkeypatch.setattr(cdc_status, "_sync_cdc_step_status", lambda *_a, **_k: None)
    monkeypatch.setattr(cdc_status, "_probe_cdc_stack_phase", lambda *_a, **_k: None)
    session = SimpleNamespace(
        target_config=SimpleNamespace(region="us-east-2"), aws_profile=None
    )

    # (a) FRESH controller: the read fails, so the names it cannot verify must survive.
    state = DataMigrationState()
    state.set_cdc_stack_name("dsql-cdc-stack")
    state.set_cdc_connector_names(live)
    cdc_status._ensure_cdc_controller(state, session)
    assert state.cdc_connector_names == live, (
        "a failed read must not be reported as 'no connectors' -- CDC may be streaming"
    )
    assert cdc_pipeline_live(state) is True

    # (b) ALREADY-WIRED controller: same rule on the other branch.
    state2 = DataMigrationState()
    state2.set_cdc_stack_name("dsql-cdc-stack")
    state2.set_cdc_connector_names(live)
    state2.set_cdc_controller(_Denied())
    state2._cdc_discovery_monotonic = None
    cdc_status._ensure_cdc_controller(state2, session)
    assert state2.cdc_connector_names == live, "the pre-wired branch must fail unknown too"

    # And the negative control: a SUCCESSFUL empty read still clears (v0.1.474's fix).
    class _Gone:
        def list_connectors_checked(self):
            return True, []

    monkeypatch.setattr(msk, "build_msk_connect_controller", lambda *a, **k: _Gone())
    state3 = DataMigrationState()
    state3.set_cdc_stack_name("dsql-cdc-stack")
    state3.set_cdc_connector_names(live)
    cdc_status._ensure_cdc_controller(state3, session)
    assert state3.cdc_connector_names == [], "a proven-empty read must still clear"


def test_a_controller_without_the_checked_read_still_clears(monkeypatch) -> None:
    # Back-compat: an injected double (or any controller predating the method) is treated as
    # a successful read, so nothing that used to clear silently stops clearing.
    import dsql_migrator.ui.data_migration._cdc_status as cdc_status

    class _Old:
        def list_connectors(self):
            return []

    assert cdc_status._list_connectors_checked(_Old()) == (True, [])

    class _New:
        def list_connectors_checked(self):
            return False, []

    assert cdc_status._list_connectors_checked(_New()) == (False, [])


# --------------------------------------------------------------------------- #
# The audit trail must say whether a load APPENDED or REPLACED
#
# "run started - 7 table(s) selected" did not record the run's most consequential choice: a
# replace DROPs and recreates the target table (taking its foreign keys with it), an append
# keeps every existing row and only fills the gap. Afterwards a reader could not tell which
# had happened. And a RETRY -- the per-table Reload, and "Exclude column & reload", which
# FORCE a replace for that one table -- had no run-level line at all.
# --------------------------------------------------------------------------- #


def test_load_mode_detail_names_each_shape() -> None:
    from types import SimpleNamespace

    import dsql_migrator.ui.data_migration._full_load_engine as engine

    tables = ["ecommerce.a", "ecommerce.b", "ecommerce.c"]

    def _inputs(replace):
        return SimpleNamespace(replace_tables=frozenset(replace))

    append = engine._load_mode_detail(_inputs([]), tables)
    assert "APPEND" in append and "REPLACE" not in append, append
    assert "kept" in append, "an append must say the existing rows survive: " + append

    every = engine._load_mode_detail(_inputs(tables), tables)
    assert "REPLACE" in every and "every selected table" in every, every
    assert "foreign keys" in every, "a replace also drops them -- say so: " + every

    # A run can replace SOME and append to the rest, so the partial case must name which.
    some = engine._load_mode_detail(_inputs(["ecommerce.b"]), tables)
    assert "REPLACE for 1 of 3" in some and "ecommerce.b" in some, some
    assert "APPEND for the rest" in some, some

    # Missing inputs -> the honest default (the loader appends when nothing says otherwise).
    assert "APPEND" in engine._load_mode_detail(None, tables)
    # A replace target outside the selection must not colour this run's verdict. Assert the
    # ABSENCE of REPLACE, not just the presence of APPEND -- the partial text contains
    # "APPEND for the rest", so a looser check passes while reporting a phantom replace.
    stale = engine._load_mode_detail(_inputs(["not.selected"]), tables)
    assert "APPEND" in stale and "REPLACE" not in stale, stale
    assert "not.selected" not in stale, stale


def test_both_run_paths_log_their_load_mode() -> None:
    import inspect

    import dsql_migrator.ui.data_migration._full_load_engine as engine

    fresh = inspect.getsource(engine.run_full_load)
    assert '"run started"' in fresh and "_load_mode_detail(inputs, table_names)" in fresh, fresh

    retry = inspect.getsource(engine.run_full_load_retry)
    assert '"retry started"' in retry, (
        "a retry had no run-level line at all, so a per-table Reload -- which forces a "
        "REPLACE for that table -- left no record that its rows were dropped"
    )
    assert "_load_mode_detail(inputs, sorted(retry_names))" in retry, retry
    # Scoped to the retried tables, not the whole original selection.
    assert "retry_names" in retry.split('"retry started"')[1][:400], retry


# --------------------------------------------------------------------------- #
# Start CDC: removing the blocking foreign keys must not throw the dialog away
#
# The removal used to close the dialog and tell the operator to "reopen Start CDC", which
# made a two-click job four clicks and discarded the pre-flight results (binlog probe,
# connection check) that had just been computed for them. The dialog now reports the removal
# in place and unlocks Start.
# --------------------------------------------------------------------------- #


class _DialogUi:
    """NiceGUI double for the Start CDC dialog: records notices, buttons and their state."""

    def __init__(self):
        self.notices: list[tuple[str, str]] = []   # (tone, header)
        self.labels: list[str] = []
        self.buttons: dict = {}
        self.notifications: list[str] = []
        self.dialog_open = False
        self.dialog_closed = 0

    class _Button:
        def __init__(self, text, on_click):
            self.text, self.on_click = text, on_click
            self.enabled = True
            self.props_seen: list[str] = []
            self.tooltip_text = None

        def props(self, spec="", *, remove=None, **_k):
            if remove and "disable" in str(remove):
                self.enabled = True
            if "disable" in str(spec):
                self.enabled = False
            self.props_seen.append(f"{spec}|remove={remove}")
            return self

        def disable(self):
            self.enabled = False
            return self

        def enable(self):
            self.enabled = True
            return self

        def tooltip(self, text="", *_a, **_k):
            self.tooltip_text = text
            return self

        def set_text(self, text):
            self.text = text

        def classes(self, *_a, **_k):
            return self

    class _Column:
        def __init__(self, ui):
            self._ui = ui

        def __enter__(self):
            return self

        def __exit__(self, *_e):
            return False

        def clear(self):
            self._ui.notices.clear()

        def classes(self, *_a, **_k):
            return self

        def __getattr__(self, _n):
            return lambda *_a, **_k: self

    class _Dialog:
        def __init__(self, ui):
            self._ui = ui

        def __enter__(self):
            return self

        def __exit__(self, *_e):
            return False

        def open(self):
            self._ui.dialog_open = True

        def close(self):
            self._ui.dialog_open = False
            self._ui.dialog_closed += 1

        def classes(self, *_a, **_k):
            return self

        def style(self, *_a, **_k):
            return self

        def __getattr__(self, _n):
            return lambda *_a, **_k: self

    def dialog(self, *_a, **_k):
        return _DialogUi._Dialog(self)

    def card(self, *_a, **_k):
        return _DialogUi._Column(self)

    def column(self, *_a, **_k):
        return _DialogUi._Column(self)

    def row(self, *_a, **_k):
        return _DialogUi._Column(self)

    def label(self, text="", *_a, **_k):
        self.labels.append(str(text))
        return _DialogUi._Column(self)

    def button(self, text="", on_click=None, *_a, **_k):
        btn = _DialogUi._Button(str(text), on_click)
        self.buttons[str(text)] = btn
        return btn

    def notify(self, message="", *_a, **_k):
        self.notifications.append(str(message))

    def __getattr__(self, _n):
        return lambda *_a, **_k: _DialogUi._Column(self)


def _drive_start_dialog(monkeypatch, *, drop_result):
    """Open the real Start CDC dialog with one blocking FK, then click Remove."""
    import asyncio
    from types import SimpleNamespace

    import dsql_migrator.ui.data_migration._cdc_ui as cdc_ui

    ui = _DialogUi()
    blocked = SimpleNamespace(
        ours=[("ecommerce.products", "fk_products_category")], foreign=[], unknown=False
    )
    monkeypatch.setattr(cdc_ui, "cdc_deploy_connection_blocker", lambda *_a, **_k: None)
    monkeypatch.setattr(cdc_ui, "_cdc_fk_block_reason", lambda *_a: ("x", "Foreign keys block CDC"))
    monkeypatch.setattr(cdc_ui, "_cdc_fk_block_body", lambda *_a: "body")
    monkeypatch.setattr(
        cdc_ui, "_render_notice",
        lambda _ui, *, tone="info", icon=None, header="", body="": ui.notices.append(
            (tone, header)
        ),
    )
    # The dialog gets fk_block from _probe_cdc_blocking_foreign_keys (blocking DSQL I/O),
    # keeping it only when .blocking is true.
    blocked.blocking = True
    monkeypatch.setattr(
        cdc_ui, "_probe_cdc_blocking_foreign_keys", lambda *_a, **_k: blocked
    )
    monkeypatch.setattr(cdc_ui, "_probe_binlog_resume_gap", lambda *_a, **_k: None)
    monkeypatch.setattr(cdc_ui, "_current_job", lambda *_a, **_k: None)
    monkeypatch.setattr(
        cdc_ui, "_drop_cdc_blocking_foreign_keys", lambda *_a, **_k: drop_result
    )

    class _Run:
        @staticmethod
        async def io_bound(fn, *a, **k):
            return fn(*a, **k)

    import nicegui

    monkeypatch.setattr(nicegui, "run", _Run, raising=False)
    refreshes: list[int] = []
    state = SimpleNamespace(cdc_stack_name="dsql-cdc-stack", job_id=None)
    asyncio.run(
        cdc_ui._open_cdc_start_dialog(
            ui, state, lambda: None, session=object(), job_manager=object(),
            inventory=None, refresh_after_drop=lambda: refreshes.append(1),
        )
    )
    return ui, refreshes


def test_removing_the_blocking_foreign_keys_keeps_the_dialog_and_unlocks_start(monkeypatch) -> None:
    import asyncio

    ui, refreshes = _drive_start_dialog(monkeypatch, drop_result=(1, 0))
    start = ui.buttons.get("Start CDC")
    remove = ui.buttons.get("Remove foreign keys")
    assert start is not None and remove is not None, ui.buttons
    assert start.enabled is False, "Start must be locked while an enforced FK remains"

    asyncio.run(remove.on_click())

    assert ui.dialog_closed == 0, (
        "the dialog must STAY OPEN -- closing it discarded the pre-flight results and made "
        "the operator reopen Start CDC"
    )
    assert start.enabled is True, "Start must be usable immediately after the removal"
    tones = [tone for tone, _h in ui.notices]
    assert "success" in tones, ui.notices
    assert "error" not in tones, "the block notice must be replaced, not left standing"


def test_a_partial_removal_leaves_start_locked(monkeypatch) -> None:
    import asyncio

    ui, _refreshes = _drive_start_dialog(monkeypatch, drop_result=(1, 1))
    start = ui.buttons["Start CDC"]
    asyncio.run(ui.buttons["Remove foreign keys"].on_click())

    assert start.enabled is False, (
        "a surviving enforced FK would make the stream dead-letter out-of-order child rows "
        "(23503), so Start must stay locked"
    )
    tones = [tone for tone, _h in ui.notices]
    assert "success" not in tones and "error" in tones, ui.notices
    assert ui.dialog_closed == 0


# ---------------------------------------------------------------------------
# Reloading a CLEANLY-loaded table (the gap that forced Start over)
# ---------------------------------------------------------------------------


class _VerifiedSession:
    """A session with both connections verified live, so reconnect gates clear."""

    target_config = None
    aws_profile = None
    source_verified = True
    target_verified = True


def test_finished_load_offers_a_scoped_reload(monkeypatch) -> None:
    """A table that loaded cleanly must be re-loadable without touching the others.

    The per-table "Reload" button lives only on the QUARANTINE card, so a table that
    finished with no dropped rows had no scoped control -- and the table picker locks once
    a load has run ("Use 'Start over' to migrate a different set of tables"). After
    re-applying ONE table's schema (a REPLACE recreates it EMPTY) the only escapes were a
    full "Re-run Full Load" over every table, or Start over.
    """
    from dsql_migrator.core.models import ChunkState, MigrationJob

    job = MigrationJob(job_id="j1")
    job.status = "DONE"
    job.progress_pct = 100.0
    job.chunks = [
        ChunkState(chunk_id="ecommerce.orders", status="DONE", rows_loaded=5, attempts=1),
        ChunkState(chunk_id="ecommerce.customers", status="DONE", rows_loaded=3, attempts=1),
    ]

    picked: list = []
    ui = _open_full_load_confirm_dialog(
        monkeypatch,
        recreate_candidates=[],
        selected_names=["ecommerce.orders", "ecommerce.customers"],
        job=job,
        status=StepStatus.DONE,
        retry_tables=lambda names: picked.append(list(names)),
        click="Reload specific tables",
    )

    assert ui.opened == 1, "the scoped-reload dialog did not open"
    # Every LOADED table is offered, and NOTHING is pre-ticked: the action set is the
    # whole load, so pre-checking would arm a full re-load from this button.
    body = " ".join(ui.texts)
    assert "ecommerce.orders" in body and "ecommerce.customers" in body
    assert len(ui.checkboxes) == 2, ui.checkboxes
    assert all(value is False for _label, value in ui.checkboxes), ui.checkboxes
    # The hint explains the scope and the gapless-watermark guarantee.
    assert "Tick the tables to reload" in body
    assert "untouched" in body
    assert "gapless" in body

    # DECISIVE: tick ONE table, confirm, and only that table is reloaded. Asserting the
    # rendered checkbox values alone would not catch a dialog whose internal checked set
    # still started full -- confirming would then reload everything while the boxes looked
    # empty, which is the failure this whole control exists to avoid.
    from types import SimpleNamespace

    tick = [h for h in ui.checkbox_handlers if callable(h)]
    assert len(tick) == 2, ui.checkbox_handlers
    # The checklist is rendered in the loaded set's sorted order, so the checkbox
    # handlers line up with it positionally.
    order = sorted(["ecommerce.orders", "ecommerce.customers"])
    tick[order.index("ecommerce.orders")](SimpleNamespace(value=True))
    _CONFIRM_LABELS = {
        "Confirm and start", "Append and load", "Drop, recreate and load",
        "Recreate and load", "Re-run anyway (CDC is live)",
    }
    confirm = [h for (label, h) in ui.handlers if label in _CONFIRM_LABELS]
    assert confirm, ui.buttons
    import asyncio as _asyncio

    result = confirm[-1]()
    if _asyncio.iscoroutine(result):
        _asyncio.run(result)
    assert picked == [["ecommerce.orders"]], picked


def test_scoped_reload_is_absent_while_tables_are_still_unfinished(monkeypatch) -> None:
    # With unfinished tables the recovery row ("Retry unfinished tables") owns this
    # space; the scoped reload must not compete with it.
    from dsql_migrator.core.models import ChunkState, MigrationJob

    job = MigrationJob(job_id="j1")
    job.status = "FAILED"
    job.chunks = [
        ChunkState(chunk_id="ecommerce.orders", status="DONE", rows_loaded=5, attempts=1),
        ChunkState(chunk_id="ecommerce.customers", status="FAILED", rows_loaded=0, attempts=1),
    ]

    ui = _ConfirmDialogUi()
    noop = lambda *_a, **_k: None  # noqa: E731

    class _NoJobs:
        def get_status(self, job_id):
            from dsql_migrator.core.job_manager import JobNotFoundError

            raise JobNotFoundError(job_id)

        def get_error(self, job_id):
            return None  # a terminal job with no job-level failure

    from dsql_migrator.ui import data_migration as dm

    dm._render_full_load_step(
        ui, DataMigrationState(), _NoJobs(), _VerifiedSession(),
        job=job, status=StepStatus.FAILED,
        selected_names=["ecommerce.orders", "ecommerce.customers"],
        guard_reason=None, start_full_load=noop, retry_failed_load=noop,
        reload_table=noop, accept_quarantine_and_continue=noop, stop_full_load=noop,
        refresh=noop, retry_tables=noop,
        schema_recreate_candidates=lambda: [],
    )

    assert not any("Reload specific tables" in b for b in ui.buttons), ui.buttons
    assert any("Retry unfinished tables" in b for b in ui.buttons), ui.buttons


def test_scoped_reload_is_disabled_while_cdc_streams(monkeypatch) -> None:
    # Reloading under a live sink can drop streamed rows, and CDC resumes from the
    # ORIGINAL watermark -- the same rule Re-run already follows.
    from dsql_migrator.core.models import ChunkState, MigrationJob
    from dsql_migrator.ui.data_migration import _full_load_ui as fl

    monkeypatch.setattr(fl, "cdc_streaming_started", lambda *a, **k: True)

    job = MigrationJob(job_id="j1")
    job.status = "DONE"
    job.chunks = [
        ChunkState(chunk_id="ecommerce.orders", status="DONE", rows_loaded=5, attempts=1)
    ]

    class _BtnRecorder(_ConfirmDialogUi):
        def __init__(self):
            super().__init__()
            self.btn_props: list[tuple[str, str]] = []

        def button(self, text="", *_a, on_click=None, **_k):
            label = str(text)
            if label:
                self.buttons.append(label)
            if on_click is not None:
                self.handlers.append((label, on_click))
            recorder = self

            class _Btn:
                def props(self, *a, **k):
                    for value in a:
                        recorder.btn_props.append((label, str(value)))
                    return self

                def disable(self):
                    recorder.btn_props.append((label, "disable"))
                    return self

                def tooltip(self, *a, **k):
                    recorder.btn_props.append(
                        (label, " ".join(str(x) for x in a))
                    )
                    return self

                def __getattr__(self, _n):
                    return lambda *a, **k: self

                def __enter__(self):
                    return self

                def __exit__(self, *exc):
                    return False

            return _Btn()

    noop = lambda *_a, **_k: None  # noqa: E731

    class _NoJobs:
        def get_status(self, job_id):
            from dsql_migrator.core.job_manager import JobNotFoundError

            raise JobNotFoundError(job_id)

        def get_error(self, job_id):
            return None  # a terminal job with no job-level failure

    from dsql_migrator.ui import data_migration as dm

    ui = _BtnRecorder()
    dm._render_full_load_step(
        ui, DataMigrationState(), _NoJobs(), _VerifiedSession(),
        job=job, status=StepStatus.DONE,
        selected_names=["ecommerce.orders"],
        guard_reason=None, start_full_load=noop, retry_failed_load=noop,
        reload_table=noop, accept_quarantine_and_continue=noop, stop_full_load=noop,
        refresh=noop, retry_tables=noop,
        schema_recreate_candidates=lambda: [],
    )

    reload_props = [p for label, p in ui.btn_props if "Reload specific" in label]
    assert any("disable" == p for p in reload_props), ui.btn_props
    assert any("Stop CDC first" in p for p in reload_props), ui.btn_props


# ---------------------------------------------------------------------------
# CDC teardown: the queue survives Start over, and a live delete is not a failure
# ---------------------------------------------------------------------------


def test_start_over_reset_preserves_the_multi_stack_teardown_queue() -> None:
    """The queue's only writer runs in the SAME handler as the reset.

    So it was written and wiped in one event, EVERY time -- which made
    teardown_queue_progress / next_unfinished_teardown / advance_cdc_teardown dead code
    in production: the banner never said "1 of 3", the advance was gated on
    len(queue) > 1 and never fired, and a multi-stack teardown announced that MSK / NAT
    billing had stopped after only the FIRST stack while the rest kept deleting and kept
    billing. Both fields' own docstrings claimed they were preserved.
    """
    from dsql_migrator.ui.data_migration._state import DataMigrationStore

    store = DataMigrationStore()
    state = store.get_or_create("S1")
    state.set_cdc_teardown("j1", kind="delete", stack="dsql-cdc-a", ctx={"region": "x"})
    state.set_cdc_teardown_queue(
        [("j1", "dsql-cdc-a"), ("j2", "dsql-cdc-b"), ("j3", "dsql-cdc-c")]
    )
    state.set_cdc_teardown_done(kind="delete", stacks=["dsql-cdc-z"])

    store.reset_in_place("S1")
    after = store.get_or_create("S1")

    assert after.cdc_teardown_job_id == "j1"
    assert after.cdc_teardown_queue == [
        ("j1", "dsql-cdc-a"), ("j2", "dsql-cdc-b"), ("j3", "dsql-cdc-c")
    ]
    assert after.cdc_teardown_done.get("stacks") == ["dsql-cdc-z"]


def test_a_preserved_queue_makes_the_multi_stack_banner_work() -> None:
    """The consequences the wipe made unreachable, driven through the real helpers.

    With an empty queue (the old post-reset state) the banner cannot say which stack of
    how many, cannot advance to the next one, and the completion notice names only the
    tracked stack -- so the first stack settling announced the whole teardown done.
    """
    from dsql_migrator.ui.data_migration._cdc_status import (
        finished_teardown_stacks,
        next_unfinished_teardown,
        teardown_queue_progress,
    )

    queue = [("j1", "dsql-cdc-a"), ("j2", "dsql-cdc-b"), ("j3", "dsql-cdc-c")]

    # "1 of 3" is only possible with the queue.
    assert teardown_queue_progress(queue, "j1") == (1, 3)
    assert teardown_queue_progress([], "j1") is None

    # The advance to the next unfinished stack, likewise.
    mgr = _StubJobManager({
        "j1": _StubJob("DONE"), "j2": _StubJob("RUNNING"), "j3": _StubJob("PENDING"),
    })
    assert next_unfinished_teardown(mgr, queue) == ("j2", "dsql-cdc-b", 2, 3)
    assert next_unfinished_teardown(mgr, []) is None

    # And the completion notice names EVERY stack, not just the tracked one.
    assert finished_teardown_stacks(queue, "dsql-cdc-a") == [
        "dsql-cdc-a", "dsql-cdc-b", "dsql-cdc-c"
    ]
    assert finished_teardown_stacks([], "dsql-cdc-a") == ["dsql-cdc-a"]


def test_a_teardown_no_longer_blocks_the_prerequisite_checks() -> None:
    """A delete must not disable Check -- and so must not block Full Load.

    The gate lumped DELETE_IN_PROGRESS in with a live connector operation and explained
    it as "A migration operation is in progress". With no prereq report,
    full_load_run_guard_reason then refuses to start a load, so a ~15-45 min teardown
    silently gated the main flow behind a false reason. Stop CDC (UPDATE_IN_PROGRESS)
    must keep blocking: it leaves MSK, the topics and the immutable partition plan in
    place, so it really is a live pipeline operation.
    """
    from dsql_migrator.ui.data_migration import cdc_delete_in_flight
    from dsql_migrator.ui.data_migration._cdc_status import (
        _is_inflight_stack_status,
        is_infra_create_stack_status,
        is_stack_teardown_status,
    )

    assert is_stack_teardown_status("DELETE_IN_PROGRESS") is True
    assert is_stack_teardown_status("delete_in_progress") is True
    for other in ("UPDATE_IN_PROGRESS", "CREATE_IN_PROGRESS", "DELETE_FAILED", None, ""):
        assert is_stack_teardown_status(other) is False, other

    # The composite the Prerequisites panel now uses.
    def _live_operation(status, state=None, mgr=None) -> bool:
        tearing = is_stack_teardown_status(status) or (
            cdc_delete_in_flight(state, mgr) if state is not None else False
        )
        return (
            bool(_is_inflight_stack_status(status))
            and not is_infra_create_stack_status(status)
        ) and not tearing

    assert _live_operation("CREATE_IN_PROGRESS") is False   # infra create: never blocked
    assert _live_operation("UPDATE_IN_PROGRESS") is True    # Stop CDC: still blocked
    assert _live_operation("DELETE_IN_PROGRESS") is False   # teardown: no longer blocked

    # The job-level half: an in-session delete records kind="delete", which
    # cdc_streaming_started counts as streaming, so the status test alone is not enough.
    state = DataMigrationState()
    state.set_cdc_deploy_job_id("del-1", kind="delete")
    mgr = _StubJobManager({"del-1": _StubJob("RUNNING")})
    assert cdc_delete_in_flight(state, mgr) is True
    from dsql_migrator.ui.data_migration import cdc_streaming_started

    assert cdc_streaming_started(state, mgr) is True, "the gate's other half still fires"
    assert _live_operation(None, state, mgr) is False

    # A start/stop job is NOT a teardown.
    other = DataMigrationState()
    other.set_cdc_deploy_job_id("start-1", kind="start")
    assert cdc_delete_in_flight(other, _StubJobManager(
        {"start-1": _StubJob("RUNNING")}
    )) is False


def test_in_flight_teardown_is_split_from_a_stuck_one() -> None:
    # "Needs cleanup" folds a delete that is still running with one that is stuck. The
    # failure copy then diagnosed a normal delete as "a previous teardown did not finish"
    # and recommended 'Retain resources' -- which would abandon the resources the delete
    # is about to remove cleanly, the opposite of stopping the billing.
    from dsql_migrator.ui.data_migration._cdc_status import split_cleanup_by_progress

    in_flight, terminal = split_cleanup_by_progress([
        ("a", "DELETE_IN_PROGRESS"),
        ("b", "DELETE_FAILED"),
        ("c", "ROLLBACK_IN_PROGRESS"),
        ("d", "ROLLBACK_COMPLETE"),
    ])
    assert in_flight == [("a", "DELETE_IN_PROGRESS"), ("c", "ROLLBACK_IN_PROGRESS")]
    assert terminal == [("b", "DELETE_FAILED"), ("d", "ROLLBACK_COMPLETE")]
    assert split_cleanup_by_progress([]) == ([], [])


def test_cdc_prep_section_does_not_paint_a_deleting_stack_green() -> None:
    """One screen must not contradict itself.

    prep == "ready" folds EVERY non-stable status, so a stack being torn down -- or stuck
    in ROLLBACK_COMPLETE / DELETE_FAILED -- was announced in a green success box as
    "already deployed, so there is nothing to provision", while the CDC card one sub-step
    below, reading the same state, said "CDC infrastructure is being deleted".
    """
    from dsql_migrator.ui.data_migration._cdc_ui import (
        _cdc_prep_ready_badge,
        cdc_infra_prep_state,
    )

    class _NoJobs:
        def get_status(self, job_id):
            from dsql_migrator.core.job_manager import JobNotFoundError

            raise JobNotFoundError(job_id)

    state = DataMigrationState()
    state.set_cdc_stack_phase("unstable", status="DELETE_IN_PROGRESS")

    # The prep-state contract is unchanged (hiding the deploy form is correct: CreateStack
    # against a same-named deleting stack raises AlreadyExistsException).
    assert cdc_infra_prep_state(state, _NoJobs()) == "ready"
    # ...but the badge is no longer a green "Ready".
    badge, tone = _cdc_prep_ready_badge(state)
    assert badge != "Ready"
    assert tone != "positive"
    assert badge == "Deleting…"

    # A genuinely deployed stack keeps the green badge.
    ok = DataMigrationState()
    ok.set_cdc_stack_phase("running", status="CREATE_COMPLETE")
    assert _cdc_prep_ready_badge(ok) == ("Ready", "positive")
    # And so does one whose raw status was never recorded (no false alarm).
    bare = DataMigrationState()
    bare.set_cdc_stack_phase("running")
    assert _cdc_prep_ready_badge(bare) == ("Ready", "positive")


def test_cdc_prep_ready_branch_renders_the_status_message_not_already_deployed() -> None:
    import inspect

    from dsql_migrator.ui.data_migration import _cdc_ui as cu

    src = inspect.getsource(cu._render_cdc_infra_prep_section)
    # The unstable branch must consult the RAW status and reuse the shared pure helper,
    # and must return before the "already deployed" copy.
    assert "cdc_stack_phase_status" in src
    assert "cdc_unstable_message(_raw_status)" in src
    assert "not is_stable_stack_status(_raw_status)" in src
    # Re-poll only while the status can still change on its own.
    assert "_is_inflight_stack_status(_raw_status)" in src


def test_a_still_deleting_stack_is_not_reported_as_a_failed_teardown() -> None:
    """The job settling is not the stack being gone -- and not a failure either.

    ``stack_status_needs_cleanup`` is True for the ``*_IN_PROGRESS`` statuses as well as
    the terminal ones, so a delete that was simply still running (a job that timed out, or
    was reconciled after a restart) was announced as "CDC teardown failed — action
    needed", telling the operator to retry a cleanup that was already working.
    """
    from dsql_migrator.ui.data_migration._cdc_status import (
        settled_teardown_banner_state,
    )

    # Still working -> the RUNNING banner, not a failure.
    assert settled_teardown_banner_state("DELETE_IN_PROGRESS") == "running"
    assert settled_teardown_banner_state("ROLLBACK_IN_PROGRESS") == "running"
    assert settled_teardown_banner_state("UPDATE_ROLLBACK_IN_PROGRESS") == "running"
    # Terminal and needing action -> failed.
    assert settled_teardown_banner_state("DELETE_FAILED") == "failed"
    assert settled_teardown_banner_state("ROLLBACK_COMPLETE") == "failed"
    assert settled_teardown_banner_state("CREATE_FAILED") == "failed"
    # Gone / clean / unknown -> clear the banner.
    assert settled_teardown_banner_state(None) is None
    assert settled_teardown_banner_state("") is None
    assert settled_teardown_banner_state("CREATE_COMPLETE") is None


def test_the_banner_getter_uses_the_settled_state_helper() -> None:
    # Structural: the decision must come from the shared helper, so the in-flight case
    # cannot drift back to "failed" inside the closure where no test can reach it.
    import inspect

    from dsql_migrator.ui import app as app_mod

    src = inspect.getsource(app_mod)
    assert "_settled_teardown_banner_state(_last_status)" in src
    assert '"state": _settled_state,' in src
    # And the observed status is carried for the copy to echo.
    assert '"status": _last_status,' in src


def test_no_one_shot_poller_bare_returns_on_a_lost_job() -> None:
    """A one-shot poll chain has no next tick, so a bare return kills it for good.

    ``ui.timer(..., once=True)`` chains re-arm only by rendering again, so
    ``except JobNotFoundError: return`` left the screen at IN_PROGRESS with a live spinner
    for the rest of the session -- nothing remained to advance it, and only a restart
    triggers the reconcile in ``session_persistence``. Checked structurally across both
    pollers because each is a closure no test can call directly, and a behavioural test
    of one does not protect the other.
    """
    import ast
    import inspect

    from dsql_migrator.ui import validation as val
    from dsql_migrator.ui.data_migration import _full_load_ui as flu

    targets = [
        (flu, "_render_full_load_step"),
        (val, "_install_poll_timer"),
    ]
    checked = 0
    for module, func_name in targets:
        src = inspect.getsource(getattr(module, func_name))
        tree = ast.parse(textwrap_dedent(src))
        for node in ast.walk(tree):
            if not isinstance(node, ast.ExceptHandler):
                continue
            name = ""
            if isinstance(node.type, ast.Name):
                name = node.type.id
            if name != "JobNotFoundError":
                continue
            checked += 1
            first = node.body[0]
            assert not (
                isinstance(first, ast.Return) and first.value is None
            ), (
                f"{func_name}: a JobNotFoundError handler bare-returns; it must either "
                "re-arm (refresh a refreshable that installs the next timer) or do a "
                "terminal reconcile + one full refresh"
            )
    assert checked >= 2, f"expected both pollers' handlers, saw {checked}"


def textwrap_dedent(src: str) -> str:
    import textwrap

    return textwrap.dedent(src)


def test_the_cutover_foreign_key_pass_is_logged_as_a_cutover_event(monkeypatch) -> None:
    """The same pass, but the audit line must say WHERE it ran.

    For a CDC migration this pass runs ONLY at cut over -- the post-load pass is a no-op
    there -- so recording it under FULL_LOAD with no marker made the single most important
    pre-repoint fact read as something that happened back during the load. The
    identity-sequence sync standing beside it on the same screen already logs
    "(cut-over)" under VALIDATION, so the two halves of one operator action were recorded
    differently. Still exactly ONE line: only its category and label vary.
    """
    import dsql_migrator.ui.data_migration._full_load_engine as engine

    _ddls, conv = _three_fk_conv()
    monkeypatch.setattr(engine, "_pregate_orphans", lambda pending, *a, **k: {0: 0, 1: 0, 2: 0})
    monkeypatch.setattr(engine, "validate_foreign_key", lambda *a, **k: None)
    monkeypatch.setattr(engine, "apply_foreign_key", lambda *a, **k: None)
    events: list[tuple] = []
    monkeypatch.setattr(
        engine, "log_activity",
        lambda category, action, **kw: events.append((category, action, kw)),
    )

    engine.apply_preserved_foreign_keys(
        {"child": conv}, lambda: _FkProbeConnection(0), origin="cut-over"
    )

    # One STARTED + one OUTCOME, both carrying the cut-over label/category.
    assert len(events) == 2, f"still exactly one outcome line per pass: {events}"
    assert events[0][2]["status"] is engine.ActivityStatus.STARTED
    assert events[0][0] is engine.ActivityCategory.VALIDATION, events
    assert events[0][1] == "apply foreign keys (cut-over)", events
    category, action, kw = events[1]
    assert category is engine.ActivityCategory.VALIDATION
    assert action == "apply foreign keys (cut-over)"
    assert kw["status"] is engine.ActivityStatus.SUCCESS
    # The detail says when it ran and why it is the only chance for a CDC migration.
    assert "cut over" in kw["detail"].lower(), kw
    assert "only pass" in kw["detail"], kw

    # The DEFAULT (post-load / Data Migration action) is unchanged.
    events.clear()
    engine.apply_preserved_foreign_keys({"child": conv}, lambda: _FkProbeConnection(0))
    category, action, kw = events[-1]
    assert category is engine.ActivityCategory.FULL_LOAD
    assert action == "apply foreign keys"
    assert "cut over" not in kw["detail"].lower(), kw


