def test_a_table_loop_abort_also_writes_run_failed(monkeypatch) -> None:
    """The table loop can abort at RUN level too, before any chunk leaves PENDING.

    Traced live: run_full_load -> _migrate_tables_in_parallel -> recreate ->
    SchemaApplyError, raised by the loop's run-level DROP+recreate pre-pass when a target
    foreign key still referenced a table being replaced. That raise skips _finalize_run, so
    nothing wrote a terminal line -- the same dangling "run started" as a pre-loop failure.
    My first fix bracketed only the pre-passes and I asserted the remainder was a
    "multiprocess relay" path; the traceback shows it is the same process, one frame further
    in. Verified against the real failure, not inferred.
    """
    import dsql_migrator.ui.data_migration._full_load_engine as engine
    from dsql_migrator.core.error_log import ErrorLogStore
    from dsql_migrator.core.models import (
        ChunkState,
        ColumnDef,
        MigrationJob,
        TableDef,
    )

    events: list[tuple] = []
    monkeypatch.setattr(
        engine, "log_activity",
        lambda category, action, **kw: events.append((category, action, kw)),
    )
    boom = RuntimeError("Cannot replace this table: the foreign key db.child.fk still depends")
    monkeypatch.setattr(
        engine, "_migrate_tables_in_parallel",
        lambda *a, **k: (_ for _ in ()).throw(boom),
    )
    monkeypatch.setattr(engine, "_predrop_blocking_foreign_keys", lambda *a, **k: None)
    monkeypatch.setattr(engine, "_predrop_dependent_views", lambda *a, **k: None)

    class _Migrator:
        def capture_watermark(self, tables):
            return None

    class _Handle:
        def __init__(self, done):
            self._job = MigrationJob(job_id="j1")
            self._job.chunks = [
                ChunkState(chunk_id=f"db.t{i}", status="DONE" if i < done else "PENDING")
                for i in range(2)
            ]

        def snapshot(self):
            return self._job

        def update(self, *_a, **_k):
            return None

        def __getattr__(self, _n):
            return lambda *a, **k: None

    table = TableDef(
        name="db.t0",
        columns=[ColumnDef(name="id", mysql_type="int", nullable=False)],
        primary_key=["id"],
    )

    # NOTHING finished -> the run-level line is the only record there will be.
    with pytest.raises(RuntimeError):
        engine.run_full_load(
            _Handle(done=0), [table], migrator=_Migrator(), error_log=ErrorLogStore()
        )
    failed = [e for e in events if e[1] == "run failed"]
    assert len(failed) == 1, [e[1] for e in events]
    assert "no rows were written" in failed[0][2]["detail"]
    assert "foreign key" in failed[0][2]["detail"]

    # Tables DID finish -> their per-table lines plus _finalize_run's "run incomplete"
    # already tell the story, so a second run-level line would be duplicate reporting.
    events.clear()
    with pytest.raises(RuntimeError):
        engine.run_full_load(
            _Handle(done=1), [table], migrator=_Migrator(), error_log=ErrorLogStore()
        )
    assert [e for e in events if e[1] == "run failed"] == [], events


def test_an_operator_stopped_run_writes_a_terminal_line(monkeypatch) -> None:
    """A stopped run returned from _finalize_run silently.

    So the audit log held "run started" and nothing else -- the same dangling-start shape as
    an aborted run, but for the one case where the operator knows what happened and a reader
    six weeks later does not. WARNING: nothing broke and the loaded tables are kept, but a
    partial target is a fact someone must act on.
    """
    import dsql_migrator.ui.data_migration._full_load_engine as engine
    from dsql_migrator.core.error_log import ErrorLogStore
    from dsql_migrator.core.models import ChunkState, MigrationJob

    events: list[tuple] = []
    monkeypatch.setattr(
        engine, "log_activity",
        lambda category, action, **kw: events.append((category, action, kw)),
    )

    class _Handle:
        cancelled = True

        def __init__(self):
            self._job = MigrationJob(job_id="j1")
            self._job.chunks = [
                ChunkState(chunk_id="db.a", status="DONE"),
                ChunkState(chunk_id="db.b", status="PENDING"),
                ChunkState(chunk_id="db.c", status="PENDING"),
            ]

        def snapshot(self):
            return self._job

        def __getattr__(self, _n):
            return lambda *a, **k: None

    engine._finalize_run(
        _Handle(), "j1", ["db.a", "db.b", "db.c"],
        engine._RunCounts(real_failed=0, quarantined=0),
        ErrorLogStore(),
        accept_quarantined_rows=False,
    )
    stopped = [e for e in events if e[1] == "run stopped"]
    assert len(stopped) == 1, [e[1] for e in events]
    _cat, _action, kw = stopped[0]
    assert kw["status"] is engine.ActivityStatus.WARNING
    assert "1 of 3 table(s) loaded" in kw["detail"]
    assert "kept" in kw["detail"]
    # A stopped run must NOT also claim completion.
    assert not [e for e in events if e[1] == "run completed"]


def test_the_stop_request_itself_is_recorded() -> None:
    # The stop is cooperative, so minutes can pass between the click and the run ending.
    # Without the request line the log cannot tell an operator stop from a crash that
    # happened to end the run at the same moment.
    import inspect

    from dsql_migrator.ui import data_migration as dm

    src = inspect.getsource(dm._render_data_migration_content) if hasattr(
        dm, "_render_data_migration_content"
    ) else inspect.getsource(dm)
    assert '"stop requested"' in src
    assert "operator requested a stop" in src
    # And it is in the click handler, not a poll path.
    i = src.index('"stop requested"')
    assert "def stop_full_load" in src[max(0, i - 1200):i]


def test_a_deleting_stack_does_not_lock_the_table_selector() -> None:
    """The lock's remedy was to start the deletion that was already running.

    cdc_infra_prep_state folds EVERY non-stable status into "ready", so a stack being torn
    down reached the clause and the message said "delete the CDC infrastructure on the CDC
    step first" -- impossible to comply with, and it unlocked ~15-25 min later with no
    explanation. The lock's premise does not hold there either: it exists because the stack
    owns each table's immutable Kafka partition count, and a stack on its way out owns
    nothing.
    """
    from dsql_migrator.ui.data_migration import selection_lock_reason
    from dsql_migrator.ui.data_migration._models import MigrationType

    class _NoJobs:
        def get_status(self, job_id):
            from dsql_migrator.core.job_manager import JobNotFoundError

            raise JobNotFoundError(job_id)

    def _reason(status):
        state = DataMigrationState()
        state.set_cdc_stack_phase("unstable", status=status)
        return selection_lock_reason(
            state, _NoJobs(),
            status=StepStatus.NOT_STARTED,
            migration_type=MigrationType.FULL_LOAD_AND_CDC,
            has_job=False,
        )

    # Being deleted -> NOT locked by the CDC-infra clause.
    deleting = _reason("DELETE_IN_PROGRESS")
    assert deleting is None or "delete the CDC infrastructure" not in deleting, deleting

    # Stop CDC is an UPDATE that keeps MSK, the topics and the immutable partition plan,
    # so it must KEEP locking -- unlocking there is how a table gets added and then
    # streamed forever on one partition.
    stopping = _reason("UPDATE_IN_PROGRESS")
    assert stopping is not None and "partition" in stopping, stopping

    # A terminal rollback also still owns its resources.
    failed = _reason("ROLLBACK_COMPLETE")
    assert failed is not None, failed


def test_the_lob_panel_is_never_locked_without_a_reason() -> None:
    """A frozen card with nothing explaining it -- the invariant an adjacent comment names.

    lob_exclusion_lock's phase tuple lacked "unstable" (the phase for every non-stable
    status), so it returned (False, None) while the caller's OR still rendered the card
    locked. Fixed in two places: the tuple, and the call site's reason fallback -- the tuple
    closes today's instance, the fallback closes the class.
    """
    import inspect

    from dsql_migrator.ui import data_migration as dm
    from dsql_migrator.ui.data_migration._cdc_monitoring import lob_exclusion_lock

    for status in ("DELETE_IN_PROGRESS", "ROLLBACK_COMPLETE", "UPDATE_IN_PROGRESS"):
        state = DataMigrationState()
        state.set_cdc_stack_phase("unstable", status=status)
        locked, reason = lob_exclusion_lock(state, None)
        assert locked is True, status
        assert reason, f"locked with no reason for {status}"

    # And the caller falls back to the selection lock's reason for ANY future contributor.
    src = inspect.getsource(dm)
    assert "lock_reason=_lob_reason or selection_lock," in src


def test_start_cdc_logs_the_resume_point_through_the_real_ui_path(monkeypatch) -> None:
    """Closes the verification gap left open by the live run.

    The resume-point STRING was verified live (a real Full Load watermark through the real
    formatter), but its WIRING was pinned only by a source-text assertion, because the E2E
    harness drives CloudFormation through the aws CLI and never enters _start_cdc_deploy --
    so nothing proved the UI actually passes that detail to the log. This drives the REAL
    _start_cdc_deploy with the AWS and NiceGUI seams injected (the repo's standard UI-test
    shape) and asserts what _log_cdc_event actually receives, which is the part a browser
    pass would otherwise have to confirm by eye.
    """
    from types import SimpleNamespace

    from dsql_migrator.core.models import Watermark
    from dsql_migrator.ui.data_migration import _cdc_ui as _cdcui

    events: list[tuple] = []
    monkeypatch.setattr(
        _cdcui, "_log_cdc_event",
        lambda action, **kw: events.append((action, kw)),
    )
    # The deploy itself must not run: only the SUBMIT-time detail is under test.
    monkeypatch.setattr(_cdcui, "build_cdc_stack_deployer", lambda *a, **k: object(),
                        raising=False)
    monkeypatch.setattr(_cdcui, "_read_cdc_template_body", lambda *a, **k: "{}",
                        raising=False)

    class _SubmitOnlyJM:
        def __init__(self):
            self.work = None

        def submit(self, work):
            self.work = work
            return "job-1"

        def get_status(self, job_id):
            # The Full Load job carries the watermark the CDC start must resume from.
            return SimpleNamespace(
                job_id=job_id,
                status="DONE",
                watermark=Watermark(
                    binlog_file="mysql-bin-changelog.000007",
                    binlog_position=76653880,
                    gtid_executed=None,
                    snapshot_timestamp=datetime(2026, 9, 21, 7, 34, tzinfo=timezone.utc),
                ),
                chunks=[],
            )

    class _Ui:
        def notify(self, *_a, **_k):
            return None

        def __getattr__(self, _n):
            return lambda *a, **k: None

    session = SimpleNamespace(
        target_config=SimpleNamespace(
            region="ap-northeast-2", cluster_endpoint="ep.dsql.amazonaws.com",
            database="postgres", username="admin",
        ),
        aws_profile=None, source_password=None, source_config=None,
        source_secret_id=None,
    )
    state = DataMigrationState()
    state.set_selection(TableSelection(selected_tables=["orders"]))
    state.job_id = "fl-1"

    _cdcui._start_cdc_deploy(
        _Ui(), state, _SubmitOnlyJM(), lambda: None,
        inventory=_inventory(), session=session,
    )

    started = [e for e in events if "start CDC" in e[0]]
    assert started, [e[0] for e in events]
    detail = started[0][1]["detail"]
    # The coordinate the Full Load captured, carried into the CDC start's audit line.
    assert "binlog mysql-bin-changelog.000007:76653880" in detail, detail
    assert "gapless" in detail
    assert "mode " in detail
    # No GTID claimed for a source that has none (this one's gtid_executed is None).
    assert "GTID" not in detail


def test_format_watermark_trusts_the_known_engine_over_an_absent_lsn() -> None:
    """F-2: the panel inferred the engine from `bool(watermark.wal_lsn)`. A PostgreSQL
    Full-Load-only LSN read is best-effort (probe_scalar -> None without the privilege), so
    a PG run whose one LSN read came back empty rendered the MySQL binlog/GTID/server-UUID
    rows and reported an "unavailable binlog coordinate" for a source with no binlog."""
    from datetime import datetime, timezone

    from dsql_migrator.core.models import SourceType, Watermark

    no_lsn = Watermark(
        snapshot_timestamp=datetime(2026, 1, 2, 3, 4, 5, tzinfo=timezone.utc)
    )
    # Inference alone gets it wrong.
    assert format_watermark(no_lsn).is_postgres is False
    # The engine the caller KNOWS wins.
    assert (
        format_watermark(no_lsn, source_type=SourceType.POSTGRES).is_postgres is True
    )
    # A MySQL session is unaffected, and the LSN fallback still stands on its own for a
    # caller with no session.
    assert format_watermark(no_lsn, source_type=SourceType.MYSQL).is_postgres is False
    with_lsn = Watermark(
        snapshot_timestamp=datetime(2026, 1, 2, 3, 4, 5, tzinfo=timezone.utc),
        wal_lsn="3/AF012B8",
    )
    assert format_watermark(with_lsn).is_postgres is True


def test_quarantine_recovery_offers_the_button_and_preticks_for_a_pg_source() -> None:
    """A/B3 + P-4 through the REAL body, not a lambda.

    This replaces an AST test that only asserted the ``source_type`` KEYWORD appears at the
    call site -- which a hard-coded ``source_type=SourceType.MYSQL`` would also satisfy, and
    which guarded neither of the two links that actually matter. A behavioural test was
    written off as impossible because the helper was a closure inside the page builder; the
    honest fix was to stop making it a closure, so ``make_lob_candidates_for`` is now a
    module-level factory and the shipped body runs here.

    Every other test of this button injects a lambda for ``lob_candidates_for``, bypassing
    that body -- which is exactly how the engine-unaware call inside it shipped.
    """
    from dsql_migrator.core.models import (
        ColumnDef,
        SourceConnectionConfig,
        SourceInventory,
        SourceType,
        TableDef,
    )
    from dsql_migrator.ui.data_migration._models import (
        make_lob_candidates_for,
        preselect_lob_columns_for_reason,
        session_source_type,
    )

    inventory = SourceInventory(
        tables=[
            TableDef(
                name="shop.product_media",
                columns=[
                    ColumnDef(name="id", mysql_type="bigint"),
                    ColumnDef(name="content", mysql_type="bytea"),
                    ColumnDef(name="caption", mysql_type="character varying(200)"),
                ],
                primary_key=["id"],
            )
        ]
    )

    class _Session:
        def __init__(self, source_type):
            self.source_config = (
                None
                if source_type is None
                else SourceConnectionConfig(
                    source_type=source_type, host="h", port=5432, database="app"
                )
            )

    reason = "datatype limit greater than 1048576 bytes not supported for bytea"

    # PostgreSQL: the button gets candidates (so it renders) AND the bytea column is
    # pre-ticked (so the recovery is one confirm).
    pg = make_lob_candidates_for(inventory, _Session(SourceType.POSTGRES))
    columns = pg("shop.product_media")
    assert columns == (("content", "bytea"),)
    assert preselect_lob_columns_for_reason(
        columns, reason, source_type=session_source_type(_Session(SourceType.POSTGRES))
    ) == ("content",)

    # MySQL is unaffected: a PG inventory yields nothing under the MySQL type names, which
    # is the correct answer for a MySQL session and the behaviour the default preserves.
    assert make_lob_candidates_for(inventory, _Session(SourceType.MYSQL))(
        "shop.product_media"
    ) == ()

    # A RESTORED session whose snapshot carried no connection coordinates still knows the
    # engine, so the PG behaviour must survive it (S-2).
    class _Restored:
        source_config = None
        restored_source_type = SourceType.POSTGRES

    assert make_lob_candidates_for(inventory, _Restored())("shop.product_media") == (
        ("content", "bytea"),
    )


def test_preselect_lob_columns_is_engine_aware() -> None:
    """P-4: the quarantine reason names the DSQL TYPE, and PG -> DSQL is the IDENTITY for
    these types -- so the MySQL map (mediumblob/longblob -> bytea) matched nothing for a PG
    source and the dialog opened with nothing pre-ticked."""
    from dsql_migrator.core.models import SourceType
    from dsql_migrator.ui.data_migration._models import (
        preselect_lob_columns_for_reason,
    )

    pg_columns = [("content", "bytea"), ("body", "text"), ("doc", "jsonb")]
    reason_bytea = (
        "datatype limit greater than 1048576 bytes not supported for bytea"
    )
    assert preselect_lob_columns_for_reason(pg_columns, reason_bytea) == ()
    assert preselect_lob_columns_for_reason(
        pg_columns, reason_bytea, source_type=SourceType.POSTGRES
    ) == ("content",)
    # A text reason narrows to the text column, not the bytea one.
    assert preselect_lob_columns_for_reason(
        pg_columns,
        "datatype limit greater than 1048576 bytes not supported for text",
        source_type=SourceType.POSTGRES,
    ) == ("body",)
    # "jsonb" must not also match the "json" entry (substring) and pre-tick a json column.
    assert preselect_lob_columns_for_reason(
        [("doc", "jsonb"), ("meta", "json")],
        "datatype limit greater than 1048576 bytes not supported for jsonb",
        source_type=SourceType.POSTGRES,
    ) == ("doc",)
    # MySQL is unchanged.
    assert preselect_lob_columns_for_reason(
        [("content", "longblob"), ("body", "longtext")], reason_bytea
    ) == ("content",)


