def test_the_renderer_supplies_the_engine_to_the_pretick() -> None:
    """The gap the previous test did NOT cover. `_render_full_load_progress` is what hands
    `source_type` to `preselect_lob_columns_for_reason`; deleting that one argument left the
    ENTIRE suite green (measured: 4009 passed), so the wiring could regress silently. The
    earlier behavioural test exercised the factory and the helper -- both in `_models.py` --
    not this call site, which is the second of the two links."""
    import inspect as _inspect

    from dsql_migrator.core.models import SourceType
    from dsql_migrator.ui.data_migration import _full_load_ui

    # The renderer must ACCEPT the engine ...
    assert "source_type" in _inspect.signature(
        _full_load_ui._render_full_load_progress
    ).parameters
    # ... and the step must PASS it, resolved through the one helper (so the restored-session
    # hint is honoured) rather than a raw getattr that ignores it.
    step_source = _inspect.getsource(_full_load_ui._render_full_load_step)
    assert "source_type=session_source_type(session)" in " ".join(step_source.split()), (
        "_render_full_load_step must pass source_type=session_source_type(session) to "
        "_render_full_load_progress; without it the PG quarantine dialog pre-ticks nothing"
    )
    # And the renderer must forward it to the pre-select, not default to MySQL.
    renderer_source = " ".join(
        _inspect.getsource(_full_load_ui._render_full_load_progress).split()
    )
    assert "preselect_lob_columns_for_reason(" in renderer_source
    assert "source_type=source_type or SourceType.MYSQL" in renderer_source


def test_every_session_engine_site_uses_the_one_helper() -> None:
    """`session_source_type` exists so the RESTORED hint is honoured at every PG-aware
    surface. It was applied to 2 of the session-based sites; the others kept a raw getattr
    that ignores the hint, so after a restore the watermark panel labelled MySQL rows, CDC
    config dispatched MySQL, and Schema Conversion converted a PG inventory with the MySQL
    dialect (which also reopened the AUTO_INCREMENT wording in the PK picker)."""
    import pathlib

    import dsql_migrator.ui.data_migration as dm
    import dsql_migrator.ui.schema_conversion as sc

    root = pathlib.Path(dm.__file__).parent
    raw = 'getattr(getattr(session, "source_config", None), "source_type"'
    offenders = []
    for path in list(root.glob("*.py")) + [pathlib.Path(sc.__file__)]:
        text = path.read_text(encoding="utf-8")
        if raw in text and path.name != "_models.py":
            offenders.append(path.name)
    assert not offenders, (
        "these read source_config directly and so ignore restored_source_type; route them "
        f"through session_source_type: {offenders}"
    )


def test_start_over_preserves_the_cdc_secret_cmk() -> None:
    """The source-secret CMK is deploy-time config and must outlive Start over.

    It is threaded onto the state ONCE at screen-build time (from the process config,
    ``data_migration/__init__.py:375-376``) and the builder does not re-run afterwards --
    so a reset that wiped it silently downgraded the next CDC deploy to the account's
    default ``aws/secretsmanager`` key with no UI signal. ``cdc_deploy_role_arn``, set on
    the adjacent line, was already preserved; this pins its twin.
    """
    from dsql_migrator.ui.data_migration._state import DataMigrationStore

    store = DataMigrationStore()
    state = store.get_or_create("cmk-reset")
    state.cdc_deploy_role_arn = "arn:aws:iam::123456789012:role/CdcDeployRole"
    state.cdc_secret_kms_key_id = "arn:aws:kms:us-east-1:123456789012:key/abc-123"

    store.reset_in_place("cmk-reset")
    after = store.get_or_create("cmk-reset")

    assert after is state, "reset_in_place must keep the captured object identity"
    assert after.cdc_deploy_role_arn == "arn:aws:iam::123456789012:role/CdcDeployRole"
    assert after.cdc_secret_kms_key_id == (
        "arn:aws:kms:us-east-1:123456789012:key/abc-123"
    ), "Start over dropped the operator's CMK; the next CDC deploy would use the "
    "account default key silently"


def test_start_over_lets_cdc_events_be_announced_again() -> None:
    """Start over must clear the AI-feed dedupe markers so a fresh run announces.

    ``reset_in_place`` re-runs ``__init__`` on the SAME object (so the builders' captured
    closures stay valid), which is exactly why keying the markers on ``id(state)`` in a
    module-level dict did not reset them: the id never changed. A fresh CDC-only run after
    a Start over therefore posted NO "CDC streaming started" / drift / DLQ event at all --
    the regression that keying was introduced to prevent.
    """
    from types import SimpleNamespace

    from dsql_migrator.ui.data_migration import _cdc_monitoring as cm
    from dsql_migrator.ui.data_migration._state import DataMigrationStore

    posted: list = []
    view = SimpleNamespace(dlq_depth=0, schema_drift=[])
    store = DataMigrationStore()
    state = store.get_or_create("announce-reset")
    state.job_id = "cdc-reset-test"
    state.cdc_activity = SimpleNamespace(sink_stall_confirmed=False)

    cm._announce_cdc_events(state, view, lambda **kw: posted.append(kw["text"]))
    assert any("streaming started" in t for t in posted), posted
    # Same state, same poll -> still edge-triggered, nothing re-announced.
    posted.clear()
    cm._announce_cdc_events(state, view, lambda **kw: posted.append(kw["text"]))
    assert posted == []

    store.reset_in_place("announce-reset")
    after = store.get_or_create("announce-reset")
    assert after is state, "reset_in_place must keep the captured object identity"
    after.job_id = "cdc-reset-test"
    after.cdc_activity = SimpleNamespace(sink_stall_confirmed=False)

    posted.clear()
    cm._announce_cdc_events(after, view, lambda **kw: posted.append(kw["text"]))
    assert any("streaming started" in t for t in posted), (
        "after Start over the stale dedupe markers still suppress every CDC event, so "
        f"the assistant never learns the stream started: {posted}"
    )


def test_slot_wal_retention_is_tagged_cdc_only_like_its_mysql_counterpart() -> None:
    """SLOT_WAL_RETENTION had drifted out of _CDC_ONLY_CHECK_IDS.

    It is the PostgreSQL counterpart of BINLOG_RETENTION -- which IS in the set -- so the
    combined "Full load + CDC" panel tagged a CDC-handoff-only check as needed by Full
    Load too. Every PostgreSQL CDC-only id must be in the set, or a PG source's CDC-only
    finding reads as "Full Load: Blocked".
    """
    from dsql_migrator.core.models import PrerequisiteCheckId as Id
    from dsql_migrator.ui.data_migration import _CDC_ONLY_CHECK_IDS, prereq_phase_tag

    # Derived from the PostgreSQL CDC preview itself rather than enumerated by hand: an
    # enumerated list is exactly how SLOT_WAL_RETENTION drifted out unnoticed, and it
    # cannot fail for a PG CDC id added later.
    from dsql_migrator.core.prerequisites_postgres import (
        postgres_cdc_prerequisites_skipped,
    )

    pg_cdc_ids = {r.check_id for r in postgres_cdc_prerequisites_skipped()}
    assert len(pg_cdc_ids) >= 8  # the preview is the source of truth, and it is populated
    for check_id in pg_cdc_ids | {Id.BINLOG_RETENTION, Id.GTID_MODE}:
        assert check_id in _CDC_ONLY_CHECK_IDS, check_id
        assert "CDC" in prereq_phase_tag(check_id, combined=True)
    # ...and a check Full Load genuinely needs is NOT tagged CDC-only.
    assert Id.TABLE_PRIMARY_KEY not in _CDC_ONLY_CHECK_IDS
    assert prereq_phase_tag(Id.TABLE_PRIMARY_KEY, combined=True) == "Full Load + CDC"


def test_prereq_table_shows_the_observed_value_and_the_remediation() -> None:
    """The row must carry BOTH: what was measured, then what to do about it.

    It used to render ``remediation or detail``, so every FAIL/WARN row dropped the
    measurement -- SLOT_WAL_RETENTION told the operator to raise a cap whose current value
    the panel never showed, and a partition REPLICA IDENTITY failure named no partition.
    """
    import inspect

    from dsql_migrator.core.models import (
        PrerequisiteCheckId,
        PrerequisiteResult,
        PrerequisiteStatus,
    )
    from dsql_migrator.ui import data_migration as dm

    src = inspect.getsource(dm._render_prereq_table)
    assert "result.remediation or result.detail" not in src, (
        "the observed value is being dropped again"
    )

    captured: list = []

    class _Ui:
        def table(self, columns=None, rows=None, row_key=None):
            captured.append(rows)

            class _E:
                def classes(self, *_a, **_k):
                    return self

                def props(self, *_a, **_k):
                    # Real NiceGUI elements are chainable through .props too, and the
                    # prerequisite table now sets one (wrap-cells) after .classes().
                    return self

            return _E()

    dm._render_prereq_table(
        _Ui(),
        [
            PrerequisiteResult(
                check_id=PrerequisiteCheckId.SLOT_WAL_RETENTION,
                title="WAL retention covers the CDC handoff",
                status=PrerequisiteStatus.WARN,
                required=False,
                detail="max_slot_wal_keep_size caps slot WAL retention at 512 MB.",
                remediation="Raise max_slot_wal_keep_size (or set -1 for unlimited).",
            )
        ],
    )
    (rows,) = captured
    detail = rows[0]["detail"]
    assert "512 MB" in detail, f"the measured value vanished: {detail!r}"
    assert "Raise max_slot_wal_keep_size" in detail, f"the instruction vanished: {detail!r}"


# --- 0.1.499: an unknown row estimate is not 0; quarantine advice names every recovery ---


def test_unknown_source_estimate_stays_unknown_instead_of_becoming_zero() -> None:
    """PostgreSQL 14+ reports reltuples = -1 for a never-analyzed table.

    The dialect maps that to None on purpose ("unknown", not a real 0). Collapsing it
    with ``or 0`` made the load panel read "5 / 0" -- a target apparently ahead of its
    source, which looks like a migration bug rather than a missing estimate. It is the
    normal state of a freshly bulk-loaded source, which is exactly what gets migrated.
    """
    from dsql_migrator.core.models import Watermark

    # The model must be able to HOLD unknown; typed dict[str, int] it could not.
    watermark = Watermark(
        snapshot_timestamp=datetime.now(timezone.utc),
        table_row_counts={"app.known": 5, "app.never_analyzed": None},
        row_counts_approximate=True,
    )
    assert watermark.table_row_counts["app.never_analyzed"] is None

    # ...and the panel renders it as an em dash, not "0".
    from dsql_migrator.ui.data_migration._full_load_ui import _abbrev_count

    assert _abbrev_count(None) == "—"
    assert _abbrev_count(0) == "0"


def test_unknown_estimate_is_not_labelled_an_estimate_in_the_table_rows() -> None:
    """An absent figure must not be dressed up as "estimate"; it has no figure at all.

    The fallback branch keyed on mere PRESENCE in the watermark, so a table whose
    estimate is None took it and reported source_rows=None with source_estimate=True.
    """
    from types import SimpleNamespace

    from dsql_migrator.core.models import Watermark
    from dsql_migrator.ui.data_migration._models import build_migration_table_status

    job = SimpleNamespace(
        chunks=[],
        watermark=Watermark(
            snapshot_timestamp=datetime.now(timezone.utc),
            table_row_counts={"app.known": 5, "app.unknown": None},
            row_counts_approximate=True,
        ),
    )
    rows = {
        r.table: r
        for r in build_migration_table_status(
            ["app.known", "app.unknown"], full_load_job=job
        )
    }
    assert rows["app.known"].source_rows == 5
    assert rows["app.known"].source_estimate is True
    assert rows["app.unknown"].source_rows is None
    assert rows["app.unknown"].source_estimate is False, (
        "a table with no figure must not claim to have an estimate"
    )


def test_every_quarantine_surface_offers_the_exclude_column_recovery() -> None:
    """"Fix the source value" alone is impossible on a read-only source.

    And it is impossible in principle when the value is legitimately over the 1 MiB cap
    -- which is the common cause of this drop. Excluding the column is the tool's own
    answer there, and it had a button right next to the banner while all three advice
    surfaces named only the impossible option.
    """
    from dsql_migrator.ui.data_migration import _full_load_engine as fle
    from dsql_migrator.ui.data_migration import _full_load_ui as flu
    from dsql_migrator.ui.data_migration._models import FullLoadTableRow

    # Asserted on the EMITTED text, never on inspect.getsource: the first draft of this
    # test grepped the function source, and the explanatory COMMENT above the string
    # contains the phrase too -- so it passed even with the advice stripped from the
    # user-facing message. A source grep cannot tell a comment from an output.

    # 1. The per-row durable activity entry.
    logged: list = []
    real = fle.log_activity
    try:
        fle.log_activity = lambda *a, **k: logged.append(k.get("detail", ""))
        fle._log_quarantined_row("app.t", "id=7", "value too large", "54000")
    finally:
        fle.log_activity = real
    (row_detail,) = logged
    assert "Exclude column & reload" in row_detail, (
        f"the audit entry names no workable way out: {row_detail}"
    )

    # 2. The per-table "N dropped" badge tooltip.
    badge = flu._quarantined_cell_tooltip(
        FullLoadTableRow(
            table="app.t", state="DONE", rows_loaded=10, expected_rows=12,
            attempts=1, errors=0, rows_quarantined=2,
        )
    )
    assert "Exclude column & reload" in badge, badge

    # 3. The run-level guidance carried on the raised incompleteness error.
    run_level = fle.incomplete_load_message(
        incomplete=1, total=2, quarantined_rows=2, quarantine_only=True
    )
    assert "Exclude column & reload" in run_level, run_level


def test_run_level_quarantine_guidance_survives_the_persisted_error_cap() -> None:
    """JobManager caps the persisted job error at 300 chars -- so the advice must fit.

    The cap exists to redact psycopg DETAIL lines that can carry row values, so it is
    not going away. Anything past it is silently dropped: a longer, richer wording lost
    the last recovery option (and once lost "re-run" itself), leaving the operator with
    an error that names fewer ways out than the tool actually has.
    """
    from dsql_migrator.ui.data_migration._full_load_engine import (
        incomplete_load_message,
    )

    message = incomplete_load_message(
        incomplete=12, total=40, quarantined_rows=1234, quarantine_only=True
    )
    assert len(message) <= 300, (
        f"the guidance is {len(message)} chars, so JobManager will truncate it and the "
        "operator loses the tail: " + message[290:]
    )
    low = message.lower()
    for option in ("re-run", "exclude column & reload", "accept quarantined rows"):
        assert option in low, f"{option!r} did not survive: {message}"


def test_a_source_reread_discards_the_batch_ordinal_resume_watermark() -> None:
    """A retry re-reads a DIFFERENT snapshot, so an ordinal resume skip loses rows.

    ``BatchedImporter`` skips a batch when ``index <= high-water``, valid only while
    batch index *i* denotes the same rows. The source-drop retry deliberately opens a new
    snapshot (its own docstring explains why resuming the dead one would splice two points
    in time), and it promises the cost is only re-read I/O because ``ON CONFLICT`` skips
    rows already written. The ordinal skip broke that promise: it does not re-write, it
    skips by count.

    Reproduced independently by the lead: with batches 0-2 committed (ids 1..6) and the
    application deleting id=1 before the retry, the re-read's batch 3 becomes [8, 9] and
    row 7 is never written -- while the loader reports ``failures=0`` and the table DONE.
    """
    from types import SimpleNamespace

    from dsql_migrator.core.batched_import import (
        BatchedImporter,
        OnConflictMode,
        _SkipCounter,
    )
    from dsql_migrator.core.models import ColumnDef, TableDef

    table = TableDef(
        name="app.t",
        columns=[ColumnDef(name="id", mysql_type="integer", nullable=False)],
        primary_key=["id"],
        indexes=[],
    )
    importer = BatchedImporter.__new__(BatchedImporter)  # pure generator; no connection
    importer._options = SimpleNamespace(batch_size=2)

    def batches(rows, watermark):
        counter = _SkipCounter()
        out = [
            [r["id"] for r in work.rows]
            for work in importer._iter_work(
                iter(rows), table, ["id"], ["id"], watermark, counter,
                OnConflictMode.SKIP_EXISTING,
            )
        ]
        return out, counter.value

    first, _ = batches([{"id": i} for i in range(1, 11)], {})
    assert first[:3] == [[1, 2], [3, 4], [5, 6]]
    committed = {i for b in first[:3] for i in b}   # batches 0-2 landed, then the drop

    # The retry re-reads a fresh snapshot in which id=1 no longer exists.
    reread = [{"id": i} for i in range(2, 11)]
    stale, skipped = batches(reread, {"": 2})       # carrying the ordinal watermark
    assert skipped == 3
    never_written = {r["id"] for r in reread} - (committed | {i for b in stale for i in b})
    assert never_written == {7}, (
        "fixture no longer demonstrates the loss, so this test proves nothing: "
        f"{never_written}"
    )

    # With the watermark discarded -- what the fix does before every re-read -- the
    # re-read covers every row, and ON CONFLICT makes re-writing the committed ones safe.
    fresh, skipped_fresh = batches(reread, {})
    assert skipped_fresh == 0
    assert {r["id"] for r in reread} - {i for b in fresh for i in b} == set()


def test_the_in_process_retry_clears_the_resume_watermark_before_rereading() -> None:
    """The wiring: every whole-table re-read must discard the ordinal watermark.

    Pins the hook itself, so a future caller that forgets ``before_reread`` cannot
    silently reintroduce the skip. A shard with a SHARED snapshot is the one exception --
    it reopens the same snapshot, so its row sequence is stable.
    """
    import inspect
    from types import SimpleNamespace

    from dsql_migrator.ui.data_migration import _full_load_engine as fle

    job = SimpleNamespace(resume_batch_watermark={"": 7})
    fle._discard_ordinal_resume_state(job)
    assert job.resume_batch_watermark == {}, "the stale ordinal watermark survived"
    fle._discard_ordinal_resume_state(None)  # tolerates a missing job

    attempts: list = []

    class _Dropped(Exception):
        """A MySQL "lost connection" (errno 2013) -- what an Aurora failover raises."""

        def __init__(self) -> None:
            super().__init__(2013, "Lost connection to MySQL server during query")
            self.errno = 2013

    def _work():
        attempts.append(len(attempts))
        if len(attempts) == 1:
            raise _Dropped()
        return "ok"

    live = SimpleNamespace(resume_batch_watermark={"": 3})
    result = fle._retry_source_drops_in_process(
        _work,
        cancelled=lambda: False,
        table_name="app.t",
        before_reread=lambda: fle._discard_ordinal_resume_state(live),
    )
    assert result == "ok" and len(attempts) == 2
    assert live.resume_batch_watermark == {}, (
        "the retry re-read a fresh snapshot while still carrying the batch ordinals"
    )

    # Both in-process workers must pass the hook (the shard one gated on the shared
    # snapshot); a caller that omits it reopens the data-loss path. Scoped PER WORKER --
    # a whole-module count also matches the parameter's own default and so survives a
    # call site being deleted.
    for worker in (fle._migrate_one_table_in_process, fle._migrate_shard_in_process):
        body = inspect.getsource(worker)
        assert "before_reread=" in body, (
            f"{worker.__name__} no longer discards the ordinal watermark before a "
            "re-read, reopening the silent data loss"
        )
    # The shard worker keeps the watermark only when it reopens the SAME snapshot.
    assert "args.shared_snapshot_id" in inspect.getsource(fle._migrate_shard_in_process)


def test_a_resumed_import_keeps_and_dedups_the_previous_attempt_quarantine() -> None:
    """A resumed attempt must not erase rows a previous attempt permanently dropped.

    ``import_rows`` cleared its quarantine sink at the start of EVERY call, so an attempt
    that skips the already-committed batches never re-reads their rows and the surviving
    result carried ``quarantined=0``. The table then logged SUCCESS, no primary key reached
    the error log, ``_finalize_run`` saw nothing incomplete, and the Validation gate that
    exists for exactly this never fired -- rows silently missing with no record anywhere.

    Only reachable where the batch watermark survives a re-read (a shard reopening one
    shared PostgreSQL snapshot; every other path discards it now), but there the loss is
    total. And because a retry re-reads rows a previous attempt already dropped -- the cause
    is deterministic -- the records must DEDUP by primary key, or the drop total the operator
    reconciles would inflate on every retry.

    Drives the REAL ``_quarantine_one``; an earlier draft re-implemented the dedup in the
    test and so proved only that the copy worked.
    """
    import threading

    from dsql_migrator.core.batched_import import BatchedImporter, _BatchWork

    importer = BatchedImporter.__new__(BatchedImporter)
    importer._quarantine_lock = threading.Lock()
    importer._quarantine = []
    importer._quarantine_total = 0
    importer._quarantine_seen = set()
    importer._max_quarantine = 1000   # the cap __init__ would have set

    def work_for(pk: int) -> _BatchWork:
        return _BatchWork(
            chunk_id=f"app.t#{pk}", table_name="app.t", columns=("id",),
            key_columns=("id",), on_conflict=None, rows=({"id": pk},),
        )

    class _Poison(Exception):
        sqlstate = "54000"

    importer._quarantine_one(work_for(1), _Poison("value too large"))
    importer._quarantine_one(work_for(2), _Poison("value too large"))
    assert importer._quarantine_total == 2

    # The same rows re-read on a retry must NOT be counted again, even when the driver
    # text differs for the same failure.
    importer._quarantine_one(work_for(1), _Poison("value too large"))
    importer._quarantine_one(work_for(2), _Poison("value too large for the column"))
    assert importer._quarantine_total == 2, "a re-read inflated the permanent-drop total"

    # ...and a genuinely new drop still lands.
    importer._quarantine_one(work_for(3), _Poison("value too large"))
    assert importer._quarantine_total == 3
    assert len(importer._quarantine) == 3


def test_the_resume_carry_is_gated_on_an_actual_resume() -> None:
    """A fresh load starts with an EMPTY sink; only a resumed call carries records over.

    Pins both halves of the condition, so neither a leak into an unrelated load nor a
    silent return of the erase can slip back in.
    """
    import inspect

    from dsql_migrator.core.batched_import import BatchedImporter

    src = inspect.getsource(BatchedImporter.import_rows)
    assert 'getattr(job, "resume_batch_watermark", None)' in src, (
        "the carry is no longer gated on the resume watermark"
    )
    assert "carried = list(self._quarantine) if resuming else []" in src, (
        "a resumed attempt no longer carries the previous attempt's quarantine forward"
    )


def test_a_plain_insert_shortfall_fails_loudly_instead_of_counting_as_skipped() -> None:
    """Under NONE there is no ON CONFLICT clause, so a shortfall is LOST ROWS.

    ``_execute_insert`` derived ``conflicts`` as ``attempted - inserted`` for every mode.
    With no conflict target there is nothing to conflict WITH, so a server that stored
    fewer rows than were sent had silently dropped them -- and the run reported them as
    "already on target (skipped)" and completed. That is exactly the row-drop the NONE mode
    exists to rule out.
    """
    import pytest as _pytest

    from dsql_migrator.core.batched_import import (
        BatchedImportError,
        BatchedImporter,
        OnConflictMode,
    )

    class _Cursor:
        def __init__(self, rowcount: int) -> None:
            self.rowcount = rowcount

        def execute(self, *a, **k):
            return None

        def close(self):
            return None

    class _Conn:
        def __init__(self, rowcount: int) -> None:
            self._rowcount = rowcount

        def cursor(self):
            return _Cursor(self._rowcount)

    class _Pool:
        def __init__(self, rowcount: int) -> None:
            self._rowcount = rowcount

        def lease(self):
            from contextlib import contextmanager

            @contextmanager
            def _cm():
                yield _Conn(self._rowcount)

            return _cm()

    importer = BatchedImporter.__new__(BatchedImporter)

    # NONE: 8 of 10 stored -> two rows vanished -> hard error, not a "conflict".
    with _pytest.raises(BatchedImportError) as excinfo:
        importer._execute_insert(
            _Pool(8), "stmt", [], 10, on_conflict=OnConflictMode.NONE
        )
    assert "8 of 10" in str(excinfo.value)
    assert "silently absent" in str(excinfo.value)

    # NONE with everything stored is fine.
    assert importer._execute_insert(
        _Pool(10), "stmt", [], 10, on_conflict=OnConflictMode.NONE
    ) == (10, 0)

    # SKIP_EXISTING / DO_NOTHING DO have a conflict target, so a shortfall is a real
    # conflict and must stay a count, not an error.
    assert importer._execute_insert(
        _Pool(8), "stmt", [], 10, on_conflict=OnConflictMode.SKIP_EXISTING
    ) == (8, 2)


def test_a_failed_shard_does_not_discard_its_siblings_quarantine_evidence() -> None:
    """Per-row evidence must be recorded before the aggregate verdict branches.

    The quarantine and index-failure loops lived in the all-shards-clean branch only, so a
    single FAILED or STOPPED shard threw away every OTHER shard's records: rows those
    shards permanently dropped left no primary key in the error log and no audit entry,
    with "one or more shards failed" as the only trace -- precisely when the detail matters
    most.
    """
    import inspect

    from dsql_migrator.ui.data_migration import _full_load_engine as fle

    src = inspect.getsource(fle)
    marker = "for rec in all_quarantine:"
    assert src.count(marker) == 1, (
        "the shard quarantine loop was duplicated rather than hoisted"
    )
    recorded_at = src.index(marker)
    branch_at = src.index("if any_failed:")
    assert recorded_at < branch_at, (
        "the shard quarantine records are still written inside a success-only branch, so a "
        "failed sibling discards them"
    )
    # The index-failure evidence must be hoisted with it.
    assert src.index("_record_index_failures(\n                            error_log") < branch_at


def test_accepting_a_quarantine_gap_does_not_auto_accept_a_bigger_one_later() -> None:
    """The acceptance is scoped to the gap the operator actually consented to.

    ``accept_quarantined_rows`` was a sticky, unscoped bool: consenting to a 3-row gap
    auto-accepted every LATER run's gap, of any size, in any table -- so a second load that
    dropped thousands completed as a success nobody had agreed to, with the banner still
    saying "you accepted that gap".
    """
    from dsql_migrator.ui.data_migration._state import DataMigrationStore

    store = DataMigrationStore()
    state = store.get_or_create("accept-scope")

    state.set_accept_quarantined_rows(True, gap=3)
    assert state.accept_quarantined_rows is True
    assert state.accepted_quarantine_rows == 3

    # Clearing the flag clears the number with it -- a stale count must not outlive it.
    state.set_accept_quarantined_rows(False)
    assert state.accepted_quarantine_rows is None

    # The finaliser's gate: the same gap (or smaller) is covered; a larger one is not.
    import inspect

    from dsql_migrator.ui.data_migration import _full_load_engine as fle

    gate = inspect.getsource(fle._finalize_run)
    assert "quarantined_rows <= accepted_quarantine_rows" in gate, (
        "the auto-accept no longer compares the new gap against the accepted one"
    )
    assert "accepted_quarantine_rows is None" in gate, (
        "an acceptance recorded before the count was tracked must keep the old behaviour "
        "rather than retroactively blocking a run"
    )
    assert "gap_within_acceptance" in gate


def test_identity_sync_survives_a_dropped_connection_and_keeps_its_results() -> None:
    """One dead backend must not discard the tables already synced, nor the ones after it.

    This pass runs at the END of a load that can take hours, so its connection is the most
    likely in the tool to be dead -- a DSQL IAM token is short-lived. It held ONE connection
    for the whole table list with no reconnect, so a drop made the function RAISE: measured
    on a real backend kill, 5 of 6 tables were left at ``nextval=1`` with ``max(id)=11`` and
    even the one recorded success was thrown away. Nothing was reported, which is the silent
    post-cut-over duplicate-key outage this function's docstring calls the worst shape a
    migration failure can take.
    """
    from dsql_migrator.core.target_introspector import (
        partition_identity_sync,
        sync_identity_sequences,
    )

    class _Cursor:
        def __init__(self, conn) -> None:
            self._conn = conn

        def execute(self, statement, *a, **k):
            self._conn.statements.append(str(statement))
            limit = self._conn.die_after
            if limit is not None and len(self._conn.statements) > limit:
                self._conn.dead = True
            if self._conn.dead:
                raise RuntimeError("consuming input failed: server closed the connection")
            return None

        def fetchall(self):
            return [("id",)]          # every table has an identity column

        def fetchone(self):
            return (11,)              # max(id) = 11

        def close(self):
            return None

    class _Conn:
        def __init__(self) -> None:
            self.dead = False
            self.die_after = None
            self.statements: list[str] = []

        def cursor(self):
            return _Cursor(self)

        def close(self):
            return None

    built: list = []

    def factory():
        conn = _Conn()
        # The FIRST connection dies after it has already synced one table -- the real shape:
        # a backend/token loss partway through a long list. Later connections are healthy, so
        # a correct pass records the drop for the affected table and syncs the rest.
        conn.die_after = 3 if not built else None   # 3 statements ~= one table's work
        built.append(conn)
        return conn

    tables = [f"app.t{i}" for i in range(4)]
    result = sync_identity_sequences(tables, connection_factory=factory)

    advanced, failed = partition_identity_sync(result)
    assert set(result) == set(tables), "a table was dropped from the result entirely"
    assert advanced, "every table was lost to one dead connection"
    assert failed, "the dead connection was not reported at all"
    # The failure is confined: the tables after it still synced.
    assert len(advanced) >= 2, (advanced, failed)
    assert all(value == 12 for value in advanced.values()), advanced
    assert len(built) > 1, "the pass never reconnected after the drop"


def test_the_progress_drain_survives_a_failing_job_store_write() -> None:
    """The drain thread is the only path for Stop and for the watchdog's liveness clock.

    Its loop body was unguarded, so ONE exception out of ``handle.update()`` -- which writes
    the job store on every message -- killed the thread. After that a user Stop never
    reached the workers (``cancel_event`` is set only here) and a healthy run was reaped by
    the 900s stall watchdog blaming an unresponsive connection. ``drain.join(timeout=5)``
    notices nothing, so the failure was invisible.

    Driven, not grepped: an earlier draft asserted on the source text and still passed when
    the except was narrowed to a type that never fires.
    """
    import queue
    import threading

    from dsql_migrator.ui.data_migration import _full_load_engine as fle

    applied: list = []

    class _Handle:
        cancelled = False

        def update(self, fn):
            applied.append(fn)
            # Every job-store write fails -- the shape that used to kill the thread.
            raise RuntimeError("database is locked")

    class _Event:
        def __init__(self) -> None:
            self._set = False

        def is_set(self) -> bool:
            return self._set

        def set(self) -> None:
            self._set = True

    progress: "queue.Queue[object]" = queue.Queue()
    for i in range(3):
        progress.put((f"app.t{i}", 10, 0))
    progress.put(fle._PROGRESS_SENTINEL)

    handle = _Handle()
    cancel_event = _Event()
    stop_event = threading.Event()

    # Must RETURN, not raise, and must have attempted EVERY message rather than dying on
    # the first one.
    fle._drain_progress_queue(progress, handle, cancel_event, stop_event)
    assert len(applied) >= 3, (
        f"the drain thread died after {len(applied)} message(s), so Stop and liveness stop "
        "with it"
    )

    # And it still mirrors cancellation while updates are failing -- the half whose loss
    # leaves workers running after a user Stop.
    handle2 = _Handle()
    handle2.cancelled = True
    progress2: "queue.Queue[object]" = queue.Queue()
    progress2.put(("app.t0", 1, 0))
    progress2.put(fle._PROGRESS_SENTINEL)
    cancel2 = _Event()
    fle._drain_progress_queue(progress2, handle2, cancel2, threading.Event())
    assert cancel2.is_set(), "a user Stop never reached the workers"


def test_a_failed_unique_index_is_reported_as_a_missing_constraint() -> None:
    """A UNIQUE index that did not get created is a missing CONSTRAINT, not a slow query.

    A failed CREATE INDEX is deliberately not a table failure -- the data is complete -- but
    "no data was lost and you do not need to re-run" was true of the data and false of the
    constraint: the target now accepts duplicates the source forbids. A COMPOSITE_KEY
    table's post-load pass can contain ONLY such an index, and that path is not opt-in.
    """
    import inspect

    from dsql_migrator.core.batched_import import BatchedImporter
    from dsql_migrator.ui.data_migration import _full_load_ui as flu

    # The uniqueness bit must be carried from the DDL, which is the only place that knows.
    create = inspect.getsource(BatchedImporter._create_indexes)
    assert "CREATE\\\\s+UNIQUE" in create or "CREATE\\s+UNIQUE" in create, (
        "the UNIQUE keyword is thrown away again, so the notice cannot tell them apart"
    )

    # ...and the notice must split on it.
    class _Row:
        def __init__(self, message: str) -> None:
            self.error_message = message

    assert flu._has_unique_index_failure([_Row("UNIQUE ux_orders_id: boom")]) is True
    assert flu._has_unique_index_failure([_Row("idx_orders_user: boom")]) is False
    assert flu._has_unique_index_failure([]) is False

    notice = inspect.getsource(flu._render_full_load_progress)
    assert "_has_unique_index_failure(index_only)" in notice, (
        "the notice no longer distinguishes a missing constraint from a missing index"
    )
    assert "BEFORE cutting over" in notice, (
        "a missing uniqueness constraint must say when it has to be fixed"
    )


def test_the_shared_snapshot_anchor_is_kept_alive_and_its_loss_stops_the_load() -> None:
    """The anchor sits idle in transaction for the whole sharded load.

    Every shard imports its exported snapshot id as it STARTS, and a bounded pool means the
    last shard may import it hours later -- so an idle timeout or
    ``idle_in_transaction_session_timeout`` can end the transaction and take the snapshot
    with it. Shards that start afterwards then read their OWN snapshot and the table is
    consistent as of no single point in time, with nothing said.
    """
    import inspect

    from dsql_migrator.ui.data_migration import _full_load_engine as fle

    assert fle._ANCHOR_KEEPALIVE_SECONDS > 0
    src = inspect.getsource(fle)
    ping_at = src.index("_anchor_next_ping")
    window = src[ping_at : ping_at + 3000]
    assert 'exec_driver_sql("SELECT 1")' in window, "the anchor is no longer kept alive"
    # Losing it must STOP the load, not let later shards diverge.
    assert "cancel_event.set()" in window, (
        "a lost anchor no longer stops the shards, so they read different snapshots"
    )


def test_an_accepted_quarantine_gap_survives_the_live_poll() -> None:
    """The poll must not undo "Accept quarantined rows & continue" within a tick.

    The job is terminally FAILED -- its rows really were dropped -- and the acceptance is an
    operator decision recorded on the SESSION, so the job status can never express it. The
    poll wrote that status back to the workflow step unconditionally and re-armed on every
    refresh, so the acceptance was reverted immediately: the Full Load panel showed
    "complete -- with an accepted gap" and `product_media` showed `Done · 3 dropped`, while
    the sidebar said Data Migration FAILED and Validation stayed locked. That is a dead end,
    because re-running drops the same rows again. Observed live on 0.1.500; the defect dates
    to v0.1.350.
    """
    import inspect

    from dsql_migrator.ui.data_migration import _full_load_ui as flu

    poll = inspect.getsource(flu)
    start = poll.index("mapped = job_status_to_step_status(current.status)")
    window = poll[start : start + 2200]
    assert "accept_quarantined_rows" in window, (
        "the poll no longer honours an accepted quarantine gap, so it reverts the step"
    )
    assert "_incomplete_is_quarantine_only(current" in window, (
        "the override must stay gated on quarantine-ONLY so a real retryable failure is "
        "never waved through by a stale flag"
    )
    # The promotion must happen BEFORE the FAILED branch, or set_error still fires and the
    # "Migration failed" banner comes back with it.
    promote_at = window.index("mapped = StepStatus.DONE")
    fail_at = window.index("if mapped is StepStatus.FAILED:\n            migration_state.set_error")
    assert promote_at < fail_at, (
        "the accepted gap is promoted after the failure branch, so the error is re-recorded"
    )


def test_the_accepted_gap_override_needs_both_the_flag_and_quarantine_only() -> None:
    """Behavioural half: the override's two conditions, driven not grepped.

    Mirrors the poll's decision so a change to either condition is caught: a set flag alone
    must not promote a run with retryable work left, and quarantine-only alone must not
    promote without the operator's consent.
    """
    from types import SimpleNamespace

    from dsql_migrator.core.models import StepStatus
    from dsql_migrator.ui.data_migration._full_load_ui import (
        _incomplete_is_quarantine_only,
    )

    def chunk(name: str, status: str, quarantined: int = 0):
        return SimpleNamespace(chunk_id=name, status=status, rows_quarantined=quarantined)

    log = SimpleNamespace(records=lambda *a, **k: [])

    # Quarantine-only: every chunk DONE, one carrying dropped rows.
    quarantine_only_job = SimpleNamespace(
        chunks=[chunk("app.a", "DONE"), chunk("app.b", "DONE", 3)], status="FAILED"
    )
    assert _incomplete_is_quarantine_only(quarantine_only_job, log) is True

    # A FAILED chunk is retryable work and must keep blocking, flag or no flag.
    retryable_job = SimpleNamespace(
        chunks=[chunk("app.a", "FAILED"), chunk("app.b", "DONE", 3)], status="FAILED"
    )
    assert _incomplete_is_quarantine_only(retryable_job, log) is False

    def poll_decision(job, accepted: bool) -> StepStatus:
        mapped = StepStatus.FAILED
        if accepted and _incomplete_is_quarantine_only(job, log):
            mapped = StepStatus.DONE
        return mapped

    assert poll_decision(quarantine_only_job, True) is StepStatus.DONE
    assert poll_decision(quarantine_only_job, False) is StepStatus.FAILED
    assert poll_decision(retryable_job, True) is StepStatus.FAILED


def test_the_cdc_vpc_is_prefilled_from_the_source_and_only_when_empty() -> None:
    """Derive the VpcId, show where it came from, and never overwrite the operator.

    The comment claiming "VpcId is the one input the tool cannot infer" was wrong: the value
    is on the SAME DescribeDBInstances response the tool already reads for the source
    security group. Prefilling silently and prefilling visibly are different things, so the
    provenance is recorded for the field to show -- and an operator's own value is left
    alone, because the pipeline may legitimately belong in another VPC.
    """
    from types import SimpleNamespace

    from dsql_migrator.core.rds_metadata import SourceInstanceInfo
    from dsql_migrator.ui.data_migration import _cdc_ui
    from dsql_migrator.ui.data_migration._state import DataMigrationStore

    info = SourceInstanceInfo(
        vpc_id="vpc-0ea4",
        subnet_ids=("subnet-0fbf", "subnet-0dfe"),
        db_subnet_group="workshop-base-dbsubnetgroup",
        db_identifier="pgtest-ecommerce",
    )
    session = SimpleNamespace(
        source_config=SimpleNamespace(host="pgtest-ecommerce.cluster-x.us-east-2.rds.amazonaws.com"),
        aws_profile=None,
    )

    real_fetch = _cdc_ui.__dict__.get("fetch_source_network")
    import dsql_migrator.core.rds_metadata as rds

    saved_fetch, saved_client = rds.fetch_source_network, rds.build_rds_client
    try:
        rds.fetch_source_network = lambda *a, **k: info
        rds.build_rds_client = lambda *a, **k: object()

        store = DataMigrationStore()
        state = store.get_or_create("vpc-derive")
        assert _cdc_ui.derive_cdc_vpc_from_source(state, session) is True
        fields = state.cdc_infra_inputs()
        assert fields["vpc_id"] == "vpc-0ea4"
        assert fields["connector_subnet_ids"] == "subnet-0fbf,subnet-0dfe"
        assert "pgtest-ecommerce" in (state.cdc_vpc_provenance or "")
        assert "workshop-base-dbsubnetgroup" in (state.cdc_vpc_provenance or "")

        # An operator's own value is NOT overwritten on a later pass.
        state.set_cdc_infra_inputs({"vpc_id": "vpc-mine", "connector_subnet_ids": ""})
        assert _cdc_ui.derive_cdc_vpc_from_source(state, session) is False
        assert state.cdc_infra_inputs()["vpc_id"] == "vpc-mine"

        # Best effort: nothing derivable leaves the field for the operator.
        rds.fetch_source_network = lambda *a, **k: None
        state2 = store.get_or_create("vpc-none")
        assert _cdc_ui.derive_cdc_vpc_from_source(state2, session) is False
        assert not (state2.cdc_infra_inputs().get("vpc_id") or "")
        assert state2.cdc_vpc_provenance is None
        # No source host at all (no session) is silent too.
        assert _cdc_ui.derive_cdc_vpc_from_source(state2, None) is False
    finally:
        rds.fetch_source_network, rds.build_rds_client = saved_fetch, saved_client


def _drive_cdc_infra_dialog(
    monkeypatch, *, source_vpc_warning="", source_inbound_hint="", admission=None,
    net=None, pg_objects_required=False,
):
    """Open the REAL Deploy-CDC-infrastructure dialog; return (notices, buttons).

    Behavioral, not a source-text check: an ``inspect.getsource`` assertion here once
    passed against the author's own explanatory COMMENT. The two blocking probes are
    patched at the module boundary and ``run.io_bound`` is made pass-through, so the
    dialog builds in-process with no AWS.
    """
    import asyncio

    import nicegui.run as nrun

    import dsql_migrator.ui.data_migration._cdc_ui as cdc_ui
    from dsql_migrator.core.cdc import MskSeedAdmission

    ui = _DialogUi()
    notices: list[dict] = []

    async def _io_bound(fn, *a, **k):
        return fn(*a, **k)

    monkeypatch.setattr(nrun, "io_bound", _io_bound)
    monkeypatch.setattr(cdc_ui, "cdc_deploy_connection_blocker", lambda *_a, **_k: None)
    monkeypatch.setattr(
        cdc_ui,
        "_diagnose_for_dialog",
        lambda *_a, **_k: net or ("Found existing NAT subnets.", "discovered", ""),
    )
    monkeypatch.setattr(
        cdc_ui,
        "_source_vpc_warning_for_dialog",
        # Returns BOTH readings of the one DescribeDBInstances response the dialog already
        # makes: the VPC mismatch, and the inbound rule the operator must open themselves.
        lambda *_a, **_k: (source_vpc_warning, source_inbound_hint),
    )
    monkeypatch.setattr(
        cdc_ui, "_msk_seed_admission", lambda *_a, **_k: admission or MskSeedAdmission()
    )
    monkeypatch.setattr(
        cdc_ui,
        "_render_notice",
        lambda _ui, *, tone="info", icon=None, header="", body="": notices.append(
            {"tone": tone, "header": header, "body": body}
        ),
    )
    monkeypatch.setattr(cdc_ui, "_render_cdc_cost_estimate", lambda *_a, **_k: None)

    state = DataMigrationState()
    state.set_cdc_infra_inputs({"vpc_id": "vpc-app"})
    asyncio.run(
        cdc_ui._open_cdc_infra_dialog(
            ui, state, lambda: None, session=_SimpleSourceSession(),
            pg_objects_required=pg_objects_required,
        )
    )
    return notices, ui


