def _drive_infra_deploy_submit(monkeypatch, *, admission, source_type=None):
    """Click Deploy for real; return (captured host_subnet_cidr or None, notifications).

    Patched at the module boundary only: the click path makes a DSQL GetCluster, EC2
    describes and a Secrets Manager upsert, none of which a unit test may do.
    ``dispatch_cdc_infra_params`` is the capture point -- reaching it at all proves the
    deploy was NOT aborted.
    """
    import asyncio
    from types import SimpleNamespace

    import nicegui.run as nrun

    import dsql_migrator.ui.data_migration._cdc_ui as cdc_ui
    from dsql_migrator.core.models import SourceType

    captured: dict = {}
    notes: list[tuple[str, str]] = []

    async def _io_bound(fn, *a, **k):
        return fn(*a, **k)

    monkeypatch.setattr(nrun, "io_bound", _io_bound)
    monkeypatch.setattr(
        cdc_ui,
        "_cdc_target_region",
        lambda *_a, **_k: (SimpleNamespace(region="us-east-1"), "us-east-1"),
    )
    monkeypatch.setattr(
        cdc_ui,
        "_cdc_infra_prefill",
        lambda *_a, **_k: {
            "vpc_id": "vpc-app",
            "dsql_cluster_arn": "arn:aws:dsql:us-east-1:1:cluster/c",
            "connector_subnet_ids": "subnet-a,subnet-b",
        },
    )
    monkeypatch.setattr(
        cdc_ui,
        "_resolve_cdc_source_secret",
        lambda *_a, **_k: SimpleNamespace(
            ok=True, arn="arn:secret", name="sec", error=None, error_type=None
        ),
    )
    monkeypatch.setattr(
        cdc_ui, "_msk_seed_admission", lambda *_a, **_k: admission
    )

    def _dispatch(*_a, **kw):
        captured["host_subnet_cidr"] = kw.get("host_subnet_cidr")
        raise _StopAfterDispatch()

    monkeypatch.setattr(cdc_ui, "dispatch_cdc_infra_params", _dispatch)

    class _Ui:
        def notify(self, message="", *, type="info", **_k):
            notes.append((type, str(message)))

    state = DataMigrationState()
    state.set_cdc_infra_inputs({"vpc_id": "vpc-app"})
    session = SimpleNamespace(
        aws_profile=None,
        target_config=SimpleNamespace(region="us-east-1"),
        source_config=SimpleNamespace(
            source_type=source_type or SourceType.POSTGRES, database="app"
        ),
    )
    try:
        asyncio.run(
            cdc_ui._start_cdc_infra_deploy(
                _Ui(), state, _NoopJobManager(), lambda: None, session=session
            )
        )
    except _StopAfterDispatch:
        pass
    return captured.get("host_subnet_cidr"), notes


class _StopAfterDispatch(Exception):
    """Sentinel: params were built, so the deploy was not aborted."""


class _NoopJobManager:
    def submit(self, work):
        return "job-1"


def test_infra_deploy_submits_the_resolved_admission_cidr_and_aborts_when_blocked(
    monkeypatch,
) -> None:
    from dsql_migrator.core.cdc import MskSeedAdmission

    # Resolved: the admission's CIDR -- NOT the raw config value -- becomes the
    # cdc-stack's HostSubnetCidr, which is what arms ConnectorHostDiagnosticsIngress.
    cidr, notes = _drive_infra_deploy_submit(
        monkeypatch, admission=MskSeedAdmission(cidr="10.0.0.0/16")
    )
    assert cidr == "10.0.0.0/16"
    assert notes == []

    # Blocked: the deploy is ABORTED. Reaching dispatch would mean an MSK Serverless
    # cluster gets created that this app could never seed, so "params were never built"
    # is the assertion that matters -- a notify alone would not prove it stopped.
    cidr, notes = _drive_infra_deploy_submit(
        monkeypatch,
        admission=MskSeedAdmission(blocker="no 9098 egress on this deployment"),
    )
    assert cidr is None
    # "negative", matching the dialog's error tone for the same string: a refusal.
    assert [t for t, _m in notes] == ["negative"]
    assert "9098" in notes[0][1]

    # A Lambda-seeded (MySQL) deploy still submits an EMPTY HostSubnetCidr, so no
    # ingress rule is created -- byte-identical to before this feature.
    cidr, notes = _drive_infra_deploy_submit(
        monkeypatch, admission=MskSeedAdmission()
    )
    assert cidr == ""
    assert notes == []


def test_the_deploy_dialog_reports_a_failed_lookup_as_its_own_stage(monkeypatch) -> None:
    """The ONLY test that runs `_msk_seed_admission -> discover_host_network` for real.

    Every other UI test replaces `_msk_seed_admission` wholesale at the module boundary,
    which is exactly how v0.1.503 shipped 27 green tests around a value nobody ever
    computed. Do not add a `_msk_seed_admission` monkeypatch here.
    """
    from types import SimpleNamespace

    import dsql_migrator.config as _config
    import dsql_migrator.core.ec2_metadata as _em
    import dsql_migrator.ui.data_migration._cdc_ui as cdc_ui
    from dsql_migrator.core.models import SourceType

    calls = []

    def _boom(*_a, **_k):
        calls.append(1)
        raise RuntimeError("AccessDeniedException on ec2:DescribeNetworkInterfaces")

    monkeypatch.setattr(_em, "build_ec2_client", _boom)
    monkeypatch.setattr(
        _config,
        "load_config",
        lambda *_a, **_k: SimpleNamespace(
            cdc_seed_mode="lambda", cdc_host_subnet_cidr="", cdc_msk_access=True
        ),
    )

    state = DataMigrationState()
    state.set_cdc_infra_inputs({"vpc_id": "vpc-app"})
    pg = SimpleNamespace(
        aws_profile=None,
        target_config=SimpleNamespace(region="us-east-1"),
        source_config=SimpleNamespace(source_type=SourceType.POSTGRES, database="app"),
    )

    got = cdc_ui._msk_seed_admission(state, pg)
    # A denied describe is ITS OWN stage: it used to render the same message as
    # "no interface found", and left no log line either.
    assert got.header == "Could not look up this app's network"
    assert "AccessDeniedException" in got.warning
    assert not got.blocker
    assert calls  # the real chain ran

    # MySQL resolves to the Lambda seed, so discovery must not even be attempted --
    # without this half, a fix that always returns "lookup-failed" would pass.
    calls.clear()
    mysql = SimpleNamespace(
        aws_profile=None,
        target_config=SimpleNamespace(region="us-east-1"),
        source_config=SimpleNamespace(
            source_type=SourceType.MYSQL, database="app", port=3306
        ),
    )
    quiet = cdc_ui._msk_seed_admission(state, mysql)
    assert (quiet.cidr, quiet.blocker, quiet.warning, quiet.note) == ("", "", "", "")
    assert calls == []


# --- PostgreSQL CDC start: the publication/slot precondition --------------------


def test_the_pg_replication_probe_fails_open_and_is_engine_scoped(monkeypatch) -> None:
    # Unreadable is NOT absent: a denied catalog read, a missing source password after a
    # restart, or a MySQL source must all degrade to silence, because a missing
    # publication kills the connector LOUDLY anyway. A probe that blocked on uncertainty
    # would strand operators whose source the tool merely could not ask.
    from types import SimpleNamespace

    import dsql_migrator.ui.data_migration._cdc_ui as cdc_ui
    from dsql_migrator.core.models import SourceType

    state = DataMigrationState()
    wm = SimpleNamespace(slot_name=None, publication_name=None)

    # MySQL: never probed at all.
    calls = []
    monkeypatch.setattr(
        "dsql_migrator.ui.connect.make_source_engine_factory",
        lambda *_a, **_k: (lambda *_b, **_c: calls.append(1) or (_ for _ in ()).throw(RuntimeError("x"))),
    )
    mysql = SimpleNamespace(
        source_config=SimpleNamespace(source_type=SourceType.MYSQL), source_password=None
    )
    assert cdc_ui._probe_pg_replication_objects(state, mysql, [], wm) is None
    assert calls == []

    # PostgreSQL with an unusable engine -> silence, not a block.
    pg = SimpleNamespace(
        source_config=SimpleNamespace(source_type=SourceType.POSTGRES, database="app"),
        source_password=None,
    )
    assert cdc_ui._probe_pg_replication_objects(state, pg, [], wm) is None

    # No source_config at all (a fresh session) -> silence.
    assert (
        cdc_ui._probe_pg_replication_objects(
            state, SimpleNamespace(source_config=None), [], wm
        )
        is None
    )


def test_the_probe_checks_the_objects_the_connector_will_actually_use(monkeypatch) -> None:
    # The probe and dispatch_source_config must resolve the SAME names, or the check is
    # about different objects than the connector. Both prefer the watermark's recorded
    # names and fall back to the stack-derived ones.
    from types import SimpleNamespace

    import dsql_migrator.core.cdc_pg_slot as pg_slot
    import dsql_migrator.ui.data_migration._cdc_ui as cdc_ui
    from dsql_migrator.core.models import SourceType

    seen: dict = {}

    def _read(_conn, *, publication_name, slot_name):
        seen["pub"], seen["slot"] = publication_name, slot_name
        return pg_slot.PgReplicationObjects(
            publication_name=publication_name, slot_name=slot_name,
            publication_present=True, publication_publishes_all_dml=True,
            publication_tables=frozenset({"app.orders"}),
            slot_present_any_database=True, slot_usable=True,
        )

    class _Conn:
        def __enter__(self):
            return self

        def __exit__(self, *_e):
            return False

    class _Eng:
        def connect(self):
            return _Conn()

        def dispose(self):
            return None

    monkeypatch.setattr(pg_slot, "read_pg_replication_objects", _read)
    monkeypatch.setattr(
        "dsql_migrator.ui.connect.make_source_engine_factory",
        lambda *_a, **_k: (lambda *_b, **_c: _Eng()),
    )
    state = DataMigrationState()
    state.cdc_stack_name = "dsql-cdc-stack"
    pg = SimpleNamespace(
        source_config=SimpleNamespace(source_type=SourceType.POSTGRES, database="app"),
        source_password=None,
    )
    tables = [SimpleNamespace(name="app.orders")]

    # No recorded names -> derived from the stack, exactly like dispatch_source_config.
    cdc_ui._probe_pg_replication_objects(
        state, pg, tables, SimpleNamespace(slot_name=None, publication_name=None)
    )
    assert seen["pub"] == pg_slot.pg_publication_name("dsql-cdc-stack")
    assert seen["slot"] == pg_slot.pg_slot_name("dsql-cdc-stack")

    # Recorded names win, so a stack rename after Full Load cannot point the check at a
    # different object than the connector resumes from.
    cdc_ui._probe_pg_replication_objects(
        state, pg, tables,
        SimpleNamespace(slot_name="recorded_slot", publication_name="recorded_pub"),
    )
    assert (seen["pub"], seen["slot"]) == ("recorded_pub", "recorded_slot")


def test_start_cdc_is_blocked_on_the_worker_thread_when_the_publication_is_missing(
    monkeypatch,
) -> None:
    # The dialog blocks first, but "Retry CDC" submits this job with NO dialog and a
    # cached verdict can be stale -- so the job itself must refuse before creating
    # anything. Nothing may be built: reaching build_cdc_stack_deployer means the
    # connectors get created and the Debezium task dies after the stack update.
    import dsql_migrator.ui.data_migration._cdc_ui as cdc_ui
    from dsql_migrator.core.models import SourceType

    monkeypatch.setattr(
        cdc_ui, "_probe_pg_replication_objects",
        lambda *_a, **_k: ("CDC's publication does not exist on the source", "do X"),
    )
    with pytest.raises(RuntimeError) as exc:
        _run_start_cdc_capture_seed_mode(
            monkeypatch, source_type=SourceType.POSTGRES, host_seed_mode="lambda"
        )
    # The refusal names the cause. It raises BEFORE run_cdc_start, so no connector is
    # created and the cdc-stack is untouched -- exactly the waste the block prevents.
    assert "Start CDC blocked" in str(exc.value)
    assert "publication does not exist" in str(exc.value)

    # PAIRED: with the objects present the same job runs THROUGH the backstop and reaches
    # run_cdc_start. Without this half the test would pass for a backstop that refuses
    # unconditionally, which would break the mode that works.
    monkeypatch.setattr(cdc_ui, "_probe_pg_replication_objects", lambda *_a, **_k: None)
    seed_mode, _notices, submitted = _run_start_cdc_capture_seed_mode(
        monkeypatch, source_type=SourceType.POSTGRES, host_seed_mode="lambda"
    )
    assert submitted and seed_mode == "external"


def test_pg_connector_failures_are_diagnosed_instead_of_left_to_cloudwatch() -> None:
    # The reporter had to open the MSK Connect log group to learn why the task died: every
    # existing needle was MySQL/MSK-flavoured, so a PostgreSQL failure produced the
    # content-free "<connector> entered FAILED state."
    from dsql_migrator.core.cdc_deployer import _diagnose_connector_log

    real_log = (
        "[dsql-cdc-stack-debezium-source|task-0] Creating new publication "
        "'dsqlmig_pub_dsql_cdc_stack_e39edcbe' for plugin 'PGOUTPUT'\n"
        "ERROR WorkerSourceTask{id=dsql-cdc-stack-debezium-source-0} Task threw an "
        "uncaught and unrecoverable exception.\n"
        "org.apache.kafka.connect.errors.ConnectException: Publication autocreation is "
        "disabled, please create one and restart the connector."
    )
    guidance = _diagnose_connector_log("dsql-cdc-stack-debezium-source", real_log)
    assert guidance is not None
    assert "Re-snapshot every table instead" in guidance
    # ...and it must warn OFF the remedy that silently loses data.
    assert "cannot start at a past position" in guidance
    # An unrelated log still yields nothing rather than a wrong diagnosis.
    assert _diagnose_connector_log("c", "something else entirely") is None


def test_the_probe_only_demands_a_slot_when_the_start_would_resume_from_one(
    monkeypatch,
) -> None:
    """``resumes_from_slot`` must come from the WATERMARK, matching the config invariant.

    Hardcoding it True would block every re-snapshot start -- the one path a Full-load-only
    operator has left -- leaving them nothing at all. Hardcoding it False would let a
    resume-from-slot start proceed against a slot that does not exist, which is the silent
    gap. So drive the real probe both ways with a source that has a publication but NO
    usable slot, and assert the two verdicts differ.
    """
    from types import SimpleNamespace

    import dsql_migrator.core.cdc_pg_slot as pg_slot
    import dsql_migrator.ui.data_migration._cdc_ui as cdc_ui
    from dsql_migrator.core.models import SourceType

    def _read(_conn, *, publication_name, slot_name):
        return pg_slot.PgReplicationObjects(
            publication_name=publication_name, slot_name=slot_name,
            publication_present=True, publication_publishes_all_dml=True,
            publication_tables=frozenset({"app.orders"}),
            slot_present_any_database=False, slot_usable=False,
        )

    class _Conn:
        def __enter__(self):
            return self

        def __exit__(self, *_e):
            return False

    class _Eng:
        def connect(self):
            return _Conn()

        def dispose(self):
            return None

    monkeypatch.setattr(pg_slot, "read_pg_replication_objects", _read)
    monkeypatch.setattr(
        "dsql_migrator.ui.connect.make_source_engine_factory",
        lambda *_a, **_k: (lambda *_b, **_c: _Eng()),
    )
    state = DataMigrationState()
    state.cdc_stack_name = "dsql-cdc-stack"
    pg = SimpleNamespace(
        source_config=SimpleNamespace(source_type=SourceType.POSTGRES, database="app"),
        source_password=None,
    )
    tables = [SimpleNamespace(name="app.orders")]

    # NO recorded slot -> the start re-snapshots, Debezium makes its own slot, so a
    # missing slot is not a gap and must NOT block.
    assert (
        cdc_ui._probe_pg_replication_objects(
            state, pg, tables, SimpleNamespace(slot_name=None, publication_name="p")
        )
        is None
    )
    # A recorded slot -> the start would resume from it (snapshot.mode=never), and it is
    # not there. That IS the silent gap, so it must block.
    blocked = cdc_ui._probe_pg_replication_objects(
        state, pg, tables, SimpleNamespace(slot_name="recorded", publication_name="p")
    )
    assert blocked is not None
    assert "cannot be created at a past position" in blocked[1]


def test_the_post_full_load_invite_does_not_recommend_the_broken_path_on_postgres() -> None:
    """The TOP of the complaint chain, and the report missed it entirely.

    After a Full-load-only PostgreSQL run the tool RECOMMENDED, in its own voice, setting
    the type to "CDC only" because it "streams from this Full Load's watermark onto the
    already-loaded target (no re-snapshot)" -- false on BOTH counts for PostgreSQL (no slot
    was created, and a slot cannot be positioned in the past) -- and handed over a
    one-click jump link. MySQL's wording is true and must stay byte-identical.
    """
    import inspect

    from dsql_migrator.ui import data_migration as dm

    src = inspect.getsource(dm.build_data_migration_screen)
    # Both branches exist and the PostgreSQL one is reached by engine, not by guesswork.
    assert "is SourceType.POSTGRES" in src
    pg_body = src[src.index("This run created no replication slot") :][:1200]
    # It must name the cost and the two honest routes, and must NOT claim "no re-snapshot".
    assert "re-snapshotting every selected" in pg_body
    assert "Full load + CDC" in pg_body
    assert "BEFORE" in pg_body
    # The MySQL claim must not appear inside the PostgreSQL branch.
    assert "no re-snapshot" not in pg_body
    # ...and the MySQL branch keeps it, so this is a split, not a rewrite of both.
    assert "watermark onto the already-loaded target (no " in src


def test_the_deploy_infra_dialog_refuses_a_cdc_only_deploy_with_nothing_to_stream_from(
    monkeypatch,
) -> None:
    """The COST gate: refuse before the ~5-minute billable MSK Serverless create.

    Asymmetric by migration type on purpose -- in "Full load + CDC" the objects are
    SUPPOSED to be absent (the Full Load creates them) and deploying the infra first is the
    flow this very card recommends, so that case must stay silent and enabled.
    """
    import dsql_migrator.ui.data_migration._cdc_ui as cdc_ui
    from dsql_migrator.ui.data_migration._models import MigrationType

    monkeypatch.setattr(
        cdc_ui, "_probe_pg_replication_objects",
        lambda *_a, **_k: ("CDC's publication does not exist on the source", "do X"),
    )

    def _drive(migration_type, *, objects_required=None):
        state = DataMigrationState()
        state.set_cdc_infra_inputs({"vpc_id": "vpc-app"})
        state.migration_type = migration_type
        return _drive_cdc_infra_dialog_with_state(
            monkeypatch,
            state,
            pg_objects_required=(
                migration_type is MigrationType.CDC_ONLY
                if objects_required is None
                else objects_required
            ),
        )

    notices, ui = _drive(MigrationType.CDC_ONLY)
    blocked = [
        n for n in notices if n["header"] == "CDC's publication does not exist on the source"
    ]
    assert [n["tone"] for n in blocked] == ["error"]
    assert "billable MSK Serverless cluster" in blocked[0]["body"]
    assert ui.buttons["Deploy"].enabled is False

    # PAIRED: a FRESH combined run (no watermark -> objects not required yet) must NOT be
    # blocked -- deploying the infrastructure before the load is the flow the card itself
    # recommends, and the objects legitimately do not exist yet.
    notices2, ui2 = _drive(MigrationType.FULL_LOAD_AND_CDC)
    assert not [
        n for n in notices2
        if n["header"] == "CDC's publication does not exist on the source"
    ]
    assert ui2.buttons["Deploy"].enabled is True

    # ...but switching to the combined type AFTER a finished Full-load-only run re-grades
    # the prerequisite to SKIP and un-gates Deploy while the objects still do not exist. The
    # caller detects that from the watermark, so the cost gate must still fire.
    notices3, ui3 = _drive(MigrationType.FULL_LOAD_AND_CDC, objects_required=True)
    assert [
        n["tone"] for n in notices3
        if n["header"] == "CDC's publication does not exist on the source"
    ] == ["error"]
    assert ui3.buttons["Deploy"].enabled is False


def test_the_deploy_gate_blocks_a_failing_publication_check_but_nothing_softer() -> None:
    """The FAIL must block Deploy; SKIP / WARN / INFO / PASS must not.

    The row's remediation says "Fix this BEFORE deploying the CDC infrastructure — MSK
    Serverless and both connectors are billed from creation", and until this gate existed
    the button it referred to stayed enabled: the cluster was created and billed, then
    Start CDC refused, leaving a cluster nobody could use. The GRADING already draws the
    line, so the gate only has to read it -- which is why the softer states are the real
    assertion here: over-blocking would take away the re-snapshot route, the one path a
    Full-load-only operator has left.
    """
    from dsql_migrator.core.models import (
        ColumnDef,
        MigrationMode,
        PrerequisiteCheckId,
        PrerequisiteReport,
        PrerequisiteResult,
        PrerequisiteStatus,
        TableDef,
    )
    from dsql_migrator.core.prerequisites_postgres import (
        PostgresCdcFacts,
        check_cdc_replication_objects,
    )
    from dsql_migrator.ui.data_migration import cdc_prerequisite_block_reason

    wal_ok = PrerequisiteResult(
        check_id=PrerequisiteCheckId.WAL_LEVEL_LOGICAL,
        title="wal_level",
        status=PrerequisiteStatus.PASS,
        required=True,
        detail="logical",
    )
    table = TableDef(
        name="app.orders",
        columns=[ColumnDef(name="id", mysql_type="int", nullable=False)],
        primary_key=["id"],
    )

    def row(*, provisions, **facts_kw):
        base = dict(
            checked_publication_name="dsqlmig_pub_x",
            checked_slot_name="dsqlmig_x",
            publication_present=True,
            publication_publishes_all_dml=True,
            publication_tables=("app.orders",),
            slot_usable=True,
            slot_present_any_database=True,
        )
        base.update(facts_kw)
        return check_cdc_replication_objects(
            PostgresCdcFacts(**base), [table], provisions_replication=provisions
        )

    def gate(result):
        return cdc_prerequisite_block_reason(
            PrerequisiteReport(
                mode=MigrationMode.CDC,
                results=[wal_ok, result],
                can_proceed=result.status is not PrerequisiteStatus.FAIL,
            ),
            cdc_checks_already_passed=True,
        )

    # BLOCKS: the publication is absent -- streaming cannot work against this source.
    absent = row(provisions=False, publication_present=False, publication_tables=())
    assert absent.status is PrerequisiteStatus.FAIL
    blocked = gate(absent)
    assert blocked is not None
    # The tooltip/notice carries the ROW's own remediation, so the operator sees the route
    # (including the re-snapshot option) without going back to the prerequisite table.
    assert "BEFORE deploying" in blocked
    assert "re-snapshot" in blocked

    # ...and a coverage gap, which is worse than a crash (RUNNING while replicating
    # nothing for those tables), blocks too.
    assert gate(row(provisions=False, publication_tables=())) is not None

    # DOES NOT BLOCK -- each for its own reason, and each would be a false block:
    #   SKIP: "Full load + CDC" creates the objects, so absent is CORRECT there.
    assert row(provisions=True, publication_present=False, publication_tables=()).status \
        is PrerequisiteStatus.SKIP
    assert gate(row(provisions=True, publication_present=False, publication_tables=())) is None
    #   WARN: only the slot is missing -> the start re-snapshots. Blocking would remove
    #   the one route a Full-load-only operator has left.
    slotless = row(provisions=False, slot_usable=False, slot_present_any_database=False)
    assert slotless.status is PrerequisiteStatus.WARN
    assert gate(slotless) is None
    #   INFO: the catalog could not be read. Unreadable is not absent.
    assert gate(row(provisions=False, publication_present=None)) is None
    #   PASS.
    assert gate(row(provisions=False)) is None


def test_the_block_notice_header_stops_saying_run_the_checks_once_they_have_run() -> None:
    from dsql_migrator.core.models import MigrationMode, PrerequisiteReport
    from dsql_migrator.ui.data_migration import cdc_prerequisite_block_header

    # No report and no recorded pass -> the checks really have not run.
    assert "Run the CDC prerequisite" in cdc_prerequisite_block_header(None)
    # A report EXISTS and something in it failed -> telling the operator to run the checks
    # is wrong; they ran, and one failed.
    report = PrerequisiteReport(mode=MigrationMode.CDC, results=[], can_proceed=False)
    header = cdc_prerequisite_block_header(report)
    assert "failing" in header and "Run the CDC prerequisite" not in header


