def test_the_prerequisite_request_carries_the_rekey_map_from_state() -> None:
    """The last hop of the fix, and the one no other test covered.

    Proven by mutation: deleting this keyword from the request left the ENTIRE suite green
    (4215 passed) while the check it feeds became permanently silent -- the check would exist,
    be tested, and never grade anything in the running app. The map cannot be re-derived
    inside the checker: it comes from the APPLIED target DDL, which only the UI has.
    """
    import ast
    import inspect

    from dsql_migrator.ui import data_migration as dm

    tree = ast.parse(inspect.getsource(dm.build_data_migration_screen))
    requests = [
        node
        for node in ast.walk(tree)
        if isinstance(node, ast.Call)
        and isinstance(node.func, ast.Name)
        and node.func.id == "PrerequisiteCheckRequest"
    ]
    assert len(requests) == 1, f"expected one prerequisite request, found {len(requests)}"
    kwargs = {kw.arg: kw for kw in requests[0].keywords}
    assert "message_key_columns" in kwargs, (
        "the request must carry the connector's re-key map, or a re-keyed table's silently "
        "lost DELETE is never graded"
    )
    # ...and sourced from the state the UI already recomputes on every render, not from a
    # second derivation that could drift from what the connector is configured with.
    names = {
        sub.attr
        for sub in ast.walk(kwargs["message_key_columns"].value)
        if isinstance(sub, ast.Attribute)
    }
    assert "cdc_message_key_columns" in names, sorted(names)


def test_every_required_cdc_failure_blocks_except_the_documented_exception() -> None:
    """The structural guard the allowlist never had — and the reason it failed twice.

    ``cdc_prerequisite_block_reason`` gated on an ALLOWLIST of three check ids. Adding a new
    blocking check therefore required editing two places, and the second edit was missed
    twice: CDC_REPLICATION_OBJECTS had to be retro-fitted in v0.1.509, and
    REPLICA_IDENTITY_COVERS_KEY (v0.1.516) was never added at all -- so it diagnosed a
    silently-lost DELETE in full detail while Deploy CDC infrastructure and Start CDC stayed
    enabled next to the red FAIL. An audit found 13 of the 14 required FAILs a CDC report can
    carry were ignored, including REPLICA_IDENTITY='nothing', which ARMS a write outage on
    the production SOURCE (every UPDATE/DELETE on that table then ERRORs on the publisher).

    An allowlist fails SILENTLY; a denylist fails LOUDLY. This test drives EVERY check id
    through the gate so a future blocking check is enforced by existing, not by remembering.
    """
    from dsql_migrator.core.models import (
        MigrationMode,
        PrerequisiteCheckId,
        PrerequisiteReport,
        PrerequisiteResult,
        PrerequisiteStatus,
    )
    from dsql_migrator.ui.data_migration import cdc_prerequisite_block_reason
    from dsql_migrator.ui.data_migration._models import _CDC_NON_BLOCKING_FAILURES

    def report_with(check_id, *, status=PrerequisiteStatus.FAIL, required=True):
        # The engine's change-stream check must PASS, or its own earlier branch fires first
        # and this test would pass for the wrong reason.
        passing_stream = PrerequisiteResult(
            check_id=PrerequisiteCheckId.WAL_LEVEL_LOGICAL,
            title="wal_level is logical",
            status=PrerequisiteStatus.PASS,
            required=True,
        )
        row = PrerequisiteResult(
            check_id=check_id,
            title=f"{check_id.value} row",
            status=status,
            required=required,
            target="app.orders",
            detail="detail text",
            remediation="remediation text",
        )
        return PrerequisiteReport.build(MigrationMode.CDC, [passing_stream, row])

    blocked, allowed = [], []
    for check_id in PrerequisiteCheckId:
        if check_id in (
            PrerequisiteCheckId.WAL_LEVEL_LOGICAL,
            PrerequisiteCheckId.BINLOG_ROW_FORMAT,
        ):
            continue  # graded by the change-stream branch above, not the sweep
        reason = cdc_prerequisite_block_reason(report_with(check_id))
        (blocked if reason else allowed).append(check_id)

    # Exactly the documented exceptions are allowed through; everything else blocks.
    assert set(allowed) == set(_CDC_NON_BLOCKING_FAILURES), (
        f"unexpected non-blocking required FAILs: {sorted(c.value for c in allowed)}"
    )
    assert blocked, "the sweep must actually block something"

    # The two that motivated this: the reported omission, and the most severe one the audit
    # found. Named explicitly so a future exception-list edit cannot quietly re-admit them.
    for must_block in (
        PrerequisiteCheckId.REPLICA_IDENTITY_COVERS_KEY,
        PrerequisiteCheckId.REPLICA_IDENTITY,
        PrerequisiteCheckId.TABLE_PRIMARY_KEY,
    ):
        assert must_block in blocked, must_block

    # A required=False FAIL never blocks: that flag is the ONLY thing carrying "advisory",
    # and it is what makes the denylist safe (BINLOG_RETENTION, GTID_MODE, MSK_AVAILABLE,
    # MSK_CONNECT_AVAILABLE, SLOT_WAL_RETENTION and the WARN branches of REPLICA_IDENTITY /
    # CDC_REPLICATION_OBJECTS all rely on it). Asserted with a FAIL, not a WARN: a WARN is
    # not a FAIL either way, so a WARN-based assertion survives dropping the required
    # condition entirely (proven by mutation).
    advisory = cdc_prerequisite_block_reason(
        report_with(
            PrerequisiteCheckId.REPLICA_IDENTITY,
            status=PrerequisiteStatus.FAIL,
            required=False,
        )
    )
    assert advisory is None, "a required=False failure is advisory and must not block"


def test_the_block_reason_names_the_failing_check_and_its_remedy() -> None:
    """A disabled button's tooltip must say which check and what to do, not just "blocked"."""
    from dsql_migrator.core.models import (
        MigrationMode,
        PrerequisiteCheckId,
        PrerequisiteReport,
        PrerequisiteResult,
        PrerequisiteStatus,
    )
    from dsql_migrator.ui.data_migration import cdc_prerequisite_block_reason

    rows = [
        PrerequisiteResult(
            check_id=PrerequisiteCheckId.WAL_LEVEL_LOGICAL,
            title="wal_level is logical",
            status=PrerequisiteStatus.PASS,
            required=True,
        ),
        PrerequisiteResult(
            check_id=PrerequisiteCheckId.REPLICA_IDENTITY_COVERS_KEY,
            title="Re-keyed table's before-image carries the record key",
            status=PrerequisiteStatus.FAIL,
            required=True,
            target="ecommerce.orders",
            detail="user_id would be NULL in a DELETE",
            remediation="Run ALTER TABLE ecommerce.orders REPLICA IDENTITY FULL",
        ),
        PrerequisiteResult(
            check_id=PrerequisiteCheckId.SOURCE_IS_WRITER,
            title="Source is the writer",
            status=PrerequisiteStatus.FAIL,
            required=True,
        ),
    ]
    reason = cdc_prerequisite_block_reason(
        PrerequisiteReport.build(MigrationMode.CDC, rows)
    )
    assert reason is not None
    assert "Re-keyed table's before-image" in reason
    assert "ecommerce.orders" in reason          # the per-table target
    assert "REPLICA IDENTITY FULL" in reason     # the row's own remediation
    assert "1 more required check(s) also failed" in reason


# ---------------------------------------------------------------------------
# A teardown that left a hazard behind must not log SUCCESS
# ---------------------------------------------------------------------------


def test_a_teardown_that_left_a_slot_behind_logs_warning_not_success(monkeypatch) -> None:
    """The one teardown outcome that can take the customer's source down later.

    Dropping the PostgreSQL replication slot is deliberately non-fatal -- the stack is
    already gone, so it must not fail the job -- which meant a surviving slot (the code's
    own "production hazard": it pins source WAL until the disk fills) was reported ONLY
    into the in-memory deploy log that the next lifecycle action wipes, while the durable
    audit line said ``delete CDC infrastructure (success)``.
    """
    import dsql_migrator.ui.data_migration._cdc_ui as cdc_ui

    events = _capture_cdc_events(monkeypatch)
    left = ["the PostgreSQL logical replication slot 'dsqlmig_s' is STILL ON THE SOURCE"]
    wrapped = cdc_ui._logged_cdc_lifecycle(
        "delete CDC infrastructure",
        detail="stack s1",
        work=lambda _h: None,
        residue=lambda: tuple(left),
    )
    wrapped(_RecordingHandle())

    (action, status, detail) = events[-1]
    assert action == "delete CDC infrastructure"
    assert status == "warning", (status, detail)
    assert "LEFT BEHIND" in detail, detail
    assert "STILL ON THE SOURCE" in detail, detail
    # It did complete -- the elapsed time is still recorded, so this is not a FAILURE.
    assert "completed in" in detail, detail


def test_a_clean_teardown_still_logs_success(monkeypatch) -> None:
    import dsql_migrator.ui.data_migration._cdc_ui as cdc_ui

    events = _capture_cdc_events(monkeypatch)
    wrapped = cdc_ui._logged_cdc_lifecycle(
        "delete CDC infrastructure",
        detail="stack s1",
        work=lambda _h: None,
        residue=lambda: (),
    )
    wrapped(_RecordingHandle())
    (_action, status, detail) = events[-1]
    assert status == "success", (status, detail)
    assert "LEFT BEHIND" not in detail


def test_the_delete_action_wires_both_audit_channels() -> None:
    """Wiring: the residue + source-write channels are dead code unless passed.

    Asserted on the parse tree so a reworded comment cannot satisfy it -- dropping either
    keyword restores the exact defect (a SUCCESS line over a surviving slot, and a
    source-destroying write with no durable record).
    """
    import ast
    import inspect

    import dsql_migrator.ui.data_migration._cdc_ui as cdc_ui

    tree = ast.parse(inspect.getsource(cdc_ui._start_cdc_delete))
    delete_calls = [
        node
        for node in ast.walk(tree)
        if isinstance(node, ast.Call)
        and isinstance(node.func, ast.Name)
        and node.func.id == "run_cdc_delete"
    ]
    assert len(delete_calls) == 1, "expected one run_cdc_delete call"
    kwargs = {kw.arg for kw in delete_calls[0].keywords}
    assert "on_residue" in kwargs, "a surviving slot would log as SUCCESS again"
    assert "on_source_write" in kwargs, (
        "destroying the slot/publication on the customer's source would go unaudited"
    )
    lifecycle = [
        node
        for node in ast.walk(tree)
        if isinstance(node, ast.Call)
        and isinstance(node.func, ast.Name)
        and node.func.id == "_logged_cdc_lifecycle"
    ]
    assert lifecycle and any(
        kw.arg == "residue" for kw in lifecycle[0].keywords
    ), "the lifecycle wrapper must be given the residue to read"


# ---------------------------------------------------------------------------
# The FK pass must not report SUCCESS over unenforced constraints
# ---------------------------------------------------------------------------


def test_orphan_skipped_constraints_make_the_pass_a_warning(monkeypatch) -> None:
    """An orphan-skipped FK is NOT enforced, so the pass did not fully succeed.

    ``status=FAILURE if failed else SUCCESS`` reported a pass that silently left
    constraints off the target as a clean success -- exactly the line a cut-over reviewer
    reads to conclude referential integrity is in place.
    """
    import dsql_migrator.ui.data_migration._full_load_engine as engine

    _ddls, conv = _three_fk_conv()
    monkeypatch.setattr(engine, "_pregate_orphans", lambda pending, *a, **k: {0: 0, 1: 7, 2: 0})
    monkeypatch.setattr(engine, "validate_foreign_key", lambda *a, **k: None)
    monkeypatch.setattr(engine, "apply_foreign_key", lambda *a, **k: None)
    events: list[tuple] = []
    monkeypatch.setattr(
        engine, "log_activity",
        lambda category, action, **kw: events.append((category, action, kw)),
    )
    applied, skipped, failed = engine.apply_preserved_foreign_keys(
        {"child": conv}, lambda: _FkProbeConnection(0)
    )
    assert (applied, skipped, failed) == (2, 1, 0)
    outcome = [
        e for e in events if e[2]["status"] is not engine.ActivityStatus.STARTED
    ][-1]
    assert outcome[2]["status"] is engine.ActivityStatus.WARNING, outcome
    assert "NOT enforced" in outcome[2]["detail"], outcome
    # Not FAILURE: nothing broke, and the remedy is the operator's.
    assert outcome[2]["status"] is not engine.ActivityStatus.FAILURE


def test_a_pass_stopped_part_way_names_the_unattempted_constraints(monkeypatch) -> None:
    """Stop mid-pass logged "3 applied, 0 skipped, 0 failed." as a SUCCESS.

    For a 15-FK schema that reads as a completed pass; the un-attempted constraints went
    only to ``_LOGGER.info``, which is the app stream, not the audit file.
    """
    import dsql_migrator.ui.data_migration._full_load_engine as engine

    _ddls, conv = _three_fk_conv()
    monkeypatch.setattr(engine, "_pregate_orphans", lambda pending, *a, **k: {0: 0, 1: 0, 2: 0})
    monkeypatch.setattr(engine, "validate_foreign_key", lambda *a, **k: None)
    monkeypatch.setattr(engine, "apply_foreign_key", lambda *a, **k: None)
    events: list[tuple] = []
    monkeypatch.setattr(
        engine, "log_activity",
        lambda category, action, **kw: events.append((category, action, kw)),
    )
    calls = {"n": 0}

    def _stopped() -> bool:
        calls["n"] += 1
        return calls["n"] > 1  # let exactly one FK through, then stop

    engine.apply_preserved_foreign_keys(
        {"child": conv}, lambda: _FkProbeConnection(0), should_cancel=_stopped
    )
    outcome = [
        e for e in events if e[2]["status"] is not engine.ActivityStatus.STARTED
    ][-1]
    assert outcome[2]["status"] is engine.ActivityStatus.WARNING, outcome
    assert "NOT ATTEMPTED" in outcome[2]["detail"], outcome
    assert "of 3" in outcome[2]["detail"], outcome


def test_an_interrupted_pass_still_left_a_started_line(monkeypatch) -> None:
    """A pass killed before its roll-up must not be invisible.

    The target can already carry enforced constraints while the audit trail has no
    evidence the pass ever ran (Fargate task replaced, or an expired IAM token raising
    inside the loop).
    """
    import dsql_migrator.ui.data_migration._full_load_engine as engine

    _ddls, conv = _three_fk_conv()
    monkeypatch.setattr(engine, "_pregate_orphans", lambda pending, *a, **k: {0: 0, 1: 0, 2: 0})
    events: list[tuple] = []
    monkeypatch.setattr(
        engine, "log_activity",
        lambda category, action, **kw: events.append((category, action, kw)),
    )

    def _boom(*_a, **_k):
        raise RuntimeError("token expired")

    monkeypatch.setattr(engine, "apply_foreign_key", _boom)
    monkeypatch.setattr(engine, "validate_foreign_key", lambda *a, **k: None)

    def _explode():
        raise RuntimeError("task replaced")

    with pytest.raises(RuntimeError):
        engine.apply_preserved_foreign_keys(
            {"child": conv}, lambda: _FkProbeConnection(0), heartbeat=_explode
        )
    started = [e for e in events if e[2]["status"] is engine.ActivityStatus.STARTED]
    assert len(started) == 1, events
    assert "3 constraint(s)" in started[0][2]["detail"], started


# ---------------------------------------------------------------------------
# CDC's applied rows reach the DURABLE log (L-1)
# ---------------------------------------------------------------------------


def _ops(inserts: int = 0, updates: int = 0, deletes: int = 0) -> dict:
    return {"inserts": inserts, "updates": updates, "deletes": deletes}


def test_applied_totals_sum_across_tables() -> None:
    from dsql_migrator.ui.data_migration._cdc_status import cdc_applied_totals

    assert cdc_applied_totals(None) == (0, 0, 0)
    assert cdc_applied_totals({}) == (0, 0, 0)
    assert cdc_applied_totals(
        {"a": _ops(1, 2, 3), "b": _ops(10, 0, 0)}
    ) == (11, 2, 3)


def test_a_rollup_is_due_once_and_then_only_after_the_interval() -> None:
    """Throttled + change-gated: the log is a milestone file, not a metrics stream.

    The original design decision -- applied counts stay OUT of the log because a per-poll
    line would flood the rotated file -- is preserved by this predicate, which is what
    makes logging them at all acceptable.
    """
    from dsql_migrator.ui.data_migration._cdc_status import cdc_applied_rollup_due

    # First activity always writes, so a short stream still leaves evidence.
    assert cdc_applied_rollup_due((5, 0, 0), last_totals=None, last_at=None, now=100.0)
    # An idle stream must not tick out identical lines forever.
    assert not cdc_applied_rollup_due(
        (5, 0, 0), last_totals=(5, 0, 0), last_at=100.0, now=100_000.0
    )
    # Changed, but inside the interval -> wait.
    assert not cdc_applied_rollup_due(
        (6, 0, 0), last_totals=(5, 0, 0), last_at=100.0, now=200.0,
        interval_seconds=600.0,
    )
    # Changed and the interval has passed -> write.
    assert cdc_applied_rollup_due(
        (6, 0, 0), last_totals=(5, 0, 0), last_at=100.0, now=701.0,
        interval_seconds=600.0,
    )
    # Nothing applied yet -> nothing to say.
    assert not cdc_applied_rollup_due(
        (0, 0, 0), last_totals=None, last_at=None, now=1.0
    )


def test_the_rollup_detail_is_bounded_and_value_free() -> None:
    from dsql_migrator.core.activity_log import _MAX_DETAIL_CHARS
    from dsql_migrator.ui.data_migration._cdc_status import cdc_applied_rollup_detail

    detail = cdc_applied_rollup_detail(
        {f"t{i}": _ops(i, i, i) for i in range(50)}
    )
    assert "more table(s)" in detail, "a capped list must say how many it dropped"
    assert len(detail) < _MAX_DETAIL_CHARS, len(detail)
    # Busiest table first, so the cap keeps the tables that matter.
    assert detail.index("t49") < detail.index("t48"), detail


def test_a_streaming_poll_writes_one_applied_rows_line_then_throttles(monkeypatch) -> None:
    """For a CDC migration the durable log had NO record of what the stream moved.

    Between "start CDC connectors" and "validation started" there were zero lines, so the
    counters proving rows flowed lived only on screen and died with the browser tab --
    half the evidence a cut-over approval rests on.
    """
    import dsql_migrator.core.activity_log as act
    import dsql_migrator.ui.data_migration._cdc_status as status

    events: list[tuple] = []
    monkeypatch.setattr(
        act, "log_activity",
        lambda category, action, **kw: events.append((action, kw)),
    )
    state = DataMigrationState()
    for _poll in range(5):
        status._apply_cdc_status(
            state, ([], {}, [], {"orders": _ops(3, 1, 1)}, {}, [])
        )
    applied = [e for e in events if e[0] == "CDC applied rows"]
    assert len(applied) == 1, f"throttled to one line, got {len(applied)}: {events}"
    detail = applied[0][1]["detail"]
    assert "3 insert(s), 1 update(s), 1 delete(s)" in detail, detail
    assert "orders 3i/1u/1d" in detail, detail
    # The state markers carry the throttle, so Start over (__init__) clears them.
    assert state.cdc_applied_logged_totals == (3, 1, 1)
    assert state.cdc_applied_logged_at is not None


def test_a_reset_clears_the_rollup_throttle_so_a_new_run_logs_again() -> None:
    """A module-level marker would silence the next run -- the v0.1.498 Start-over bug."""
    from dsql_migrator.ui.data_migration._state import DataMigrationStore

    store = DataMigrationStore()
    state = store.get_or_create("s1")
    state.cdc_applied_logged_totals = (9, 9, 9)
    state.cdc_applied_logged_at = 123.0
    store.reset_in_place("s1")
    # Same object (reset_in_place re-runs __init__ in place), so the markers must be gone.
    assert store.get_or_create("s1") is state
    assert state.cdc_applied_logged_totals is None
    assert state.cdc_applied_logged_at is None


def _stop_cdc_capturing_events(monkeypatch, state):
    """Run the real Stop CDC submit path with doubles; return the logged CDC events."""
    from types import SimpleNamespace

    import dsql_migrator.ui.data_migration._cdc_ui as cdc_ui

    events = _capture_cdc_events(monkeypatch)
    monkeypatch.setattr(
        cdc_ui, "build_cdc_stack_deployer", lambda *a, **k: object(), raising=False
    )

    class _JM:
        def submit(self, _work):
            return "job-1"

    class _Ui:
        def notify(self, *_a, **_k):
            return None

    session = SimpleNamespace(
        target_config=SimpleNamespace(
            region="us-east-1",
            cluster_endpoint="ep.dsql.amazonaws.com",
            database="postgres",
            username="admin",
        ),
        aws_profile=None,
        source_password=None,
        source_config=None,
        source_secret_id=None,
    )
    cdc_ui._start_cdc_stop(_Ui(), state, _JM(), lambda: None, session=session)
    return events


def test_stop_closes_the_record_with_a_final_cumulative_line(monkeypatch) -> None:
    """Stop is the last moment the applied-ops metrics exist.

    The periodic roll-up is throttled, so without a line here the final interval -- often
    the one immediately before cut over -- is missing from the audit trail, and the
    connectors (with their CloudWatch dimensions) are about to be deleted. Asserted by
    RUNNING the submit path, not by reading its source: a source check passes even if the
    logging call is renamed to something that never writes.
    """
    state = DataMigrationState()
    state.set_cdc_applied_ops_by_table(
        {"orders": _ops(10, 4, 1), "customers": _ops(2, 0, 0)}
    )
    events = _stop_cdc_capturing_events(monkeypatch, state)

    finals = [e for e in events if e[0] == "CDC applied rows (final)"]
    assert len(finals) == 1, f"one closing line at Stop: {events}"
    detail = finals[0][2]
    assert "12 insert(s), 4 update(s), 1 delete(s)" in detail, detail
    assert "orders 10i/4u/1d" in detail, detail
    # Honest about freshness -- these are last-poll values, not a drain confirmation.
    assert "as of the last status poll before Stop" in detail, detail


def test_stopping_a_stream_that_applied_nothing_logs_no_final_line(monkeypatch) -> None:
    # No noise for a stop before any row flowed (or a Stop on an idle pipeline).
    state = DataMigrationState()
    events = _stop_cdc_capturing_events(monkeypatch, state)
    assert not [e for e in events if e[0] == "CDC applied rows (final)"], events


