def test_the_prereq_gate_is_given_the_lob_columns_to_size_check() -> None:
    """Without this keyword the oversized-value check never runs at all.

    The at-risk columns must be derived HERE (the helper lives in this UI layer and core
    must not import it) and handed to the gate — so the one thing the Evaluation finding
    tells the operator to check would silently go unasked again.
    """
    import ast
    import inspect

    from dsql_migrator.ui import data_migration as dm

    tree = ast.parse(inspect.getsource(dm.build_data_migration_screen))
    calls = [
        node
        for node in ast.walk(tree)
        if isinstance(node, ast.Call)
        and isinstance(node.func, ast.Attribute)
        and node.func.attr == "check"
        and isinstance(node.func.value, ast.Name)
        and node.func.value.id == "checker"
    ]
    assert calls, "the prerequisite gate is no longer invoked"
    for call in calls:
        kwargs = {kw.arg for kw in call.keywords}
        assert "lob_columns" in kwargs, (
            "checker.check must be given lob_columns, or the per-value size check "
            "never runs"
        )
    flat = ast.unparse(tree)
    assert "lob_exclusion_candidates(" in flat, (
        "the at-risk columns must come from the shared helper, not be re-derived"
    )


def test_migrate_table_omits_a_target_generated_column_from_the_load() -> None:
    """Sending a value to a generated column is a PERMANENT 428C9 for every batch.

    Aurora DSQL rejects an INSERT that supplies a value for a generated column, so with the
    clause now preserved the loader MUST omit it -- otherwise every row of the table is
    quarantined. One TableDef filter covers the keyset SELECT, the INSERT column list and
    the ON CONFLICT DO UPDATE SET list.
    """
    import dataclasses

    from dsql_migrator.core.converter import SchemaConverter
    from dsql_migrator.core.models import ColumnDef, SourceType, TableDef

    table = TableDef(
        name="ecommerce.order_items",
        columns=[
            ColumnDef(name="id", mysql_type="bigint", nullable=False),
            ColumnDef(name="quantity", mysql_type="integer", nullable=False),
            ColumnDef(
                name="line_total",
                mysql_type="numeric(12,2)",
                generated=True,
                generated_kind="STORED",
                generated_expression="((quantity)::numeric * 2)",
            ),
        ],
        primary_key=["id"],
    )
    conversion = SchemaConverter(source_type=SourceType.POSTGRES).convert_table(table)

    def _migrator_for(reader=None) -> BatchedTableMigrator:
        return BatchedTableMigrator(
            dataclasses.replace(
                _inputs(), table_conversions={table.name: conversion}
            ),
            exporter=_FakeExporter(),  # type: ignore[arg-type]
            importer_factory=lambda _i: _FakeImporter(),  # type: ignore[arg-type,return-value]
            target_generated_reader=reader,
        )

    # The REPLACE path recreates the target from this applied DDL, so the DDL is the
    # authority and no catalog read is needed.
    assert _migrator_for().resolve_generated_columns(
        table, conversion, target_is_final=True
    ) == {"line_total"}

    # On the APPEND path the applied DDL is NOT authoritative -- an older build stripped
    # the clause, so the live target can be ordinary. The catalog wins.
    assert _migrator_for(lambda _t: set()).resolve_generated_columns(
        table, conversion, target_is_final=False
    ) == set()
    assert _migrator_for(lambda _t: {"line_total"}).resolve_generated_columns(
        table, conversion, target_is_final=False
    ) == {"line_total"}
    # An unreadable catalog is UNKNOWN, never "nothing to exclude": sending the value
    # quarantines every row and omitting the wrong column writes NULLs.
    assert _migrator_for(lambda _t: None).resolve_generated_columns(
        table, conversion, target_is_final=False
    ) is None

    # A table with NOTHING generated anywhere takes the ordinary path with NO catalog read,
    # so the common case gains neither a round-trip nor a new failure mode.
    plain = TableDef(
        name="ecommerce.plain",
        columns=[ColumnDef(name="id", mysql_type="bigint", nullable=False)],
        primary_key=["id"],
    )
    plain_conv = SchemaConverter(source_type=SourceType.POSTGRES).convert_table(plain)

    def _must_not_be_called(_t):  # pragma: no cover - asserted by not running
        raise AssertionError("the catalog must not be read when nothing is generated")

    plain_migrator = BatchedTableMigrator(
        dataclasses.replace(_inputs(), table_conversions={plain.name: plain_conv}),
        exporter=_FakeExporter(),  # type: ignore[arg-type]
        importer_factory=lambda _i: _FakeImporter(),  # type: ignore[arg-type,return-value]
        target_generated_reader=_must_not_be_called,
    )
    assert plain_migrator.resolve_generated_columns(
        plain, plain_conv, target_is_final=False
    ) == set()


def test_a_replace_load_with_no_applied_ddl_refuses_rather_than_guessing() -> None:
    """``target_is_final`` with no applied DDL is UNKNOWN, not "nothing to exclude".

    On the replace path the recreator re-derives its OWN conversion, so if this run has no
    applied DDL to read, what the target will end up with is genuinely unknown -- and both
    defaults are harmful: sending a value to a generated column quarantines every row
    (428C9), while omitting one from an ordinary column writes NULLs silently.
    """
    import dataclasses

    from dsql_migrator.core.converter import SchemaConverter
    from dsql_migrator.core.models import ColumnDef, SourceType, TableDef

    table = TableDef(
        name="ecommerce.order_items",
        columns=[
            ColumnDef(name="id", mysql_type="bigint", nullable=False),
            ColumnDef(name="q", mysql_type="integer", nullable=False),
            ColumnDef(
                name="g",
                mysql_type="numeric(12,2)",
                generated=True,
                generated_kind="STORED",
                generated_expression="((q)::numeric * 2)",
            ),
        ],
        primary_key=["id"],
    )
    conversion = SchemaConverter(source_type=SourceType.POSTGRES).convert_table(table)
    migrator = BatchedTableMigrator(
        dataclasses.replace(_inputs(), table_conversions={table.name: conversion}),
        exporter=_FakeExporter(),  # type: ignore[arg-type]
        importer_factory=lambda _i: _FakeImporter(),  # type: ignore[arg-type,return-value]
    )
    # No applied conversion for this table -> unknown -> refuse.
    assert migrator.resolve_generated_columns(table, None, target_is_final=True) is None
    # With one, the DDL is authoritative on that path.
    assert migrator.resolve_generated_columns(
        table, conversion, target_is_final=True
    ) == {"g"}


def test_migrate_table_drops_a_target_generated_column_from_read_and_write() -> None:
    """The filter has to REACH the load, or the preserved clause quarantines every row.

    Aurora DSQL rejects an INSERT that supplies a value for a generated column (428C9,
    permanent), so the column must leave the keyset SELECT and the INSERT column list -- the
    same single-filter mechanism the LOB exclusions use. Reproduced before the fix: 64 rows
    became 127 statements, 0 loaded and 64 permanently dropped.
    """
    import dataclasses

    from dsql_migrator.core.converter import SchemaConverter
    from dsql_migrator.core.models import SourceType

    table = TableDef(
        name="order_items",
        columns=[
            ColumnDef(name="id", mysql_type="bigint", nullable=False),
            ColumnDef(name="quantity", mysql_type="integer", nullable=False),
            ColumnDef(
                name="line_total",
                mysql_type="numeric(12,2)",
                generated=True,
                generated_kind="STORED",
                generated_expression="((quantity)::numeric * 2)",
            ),
        ],
        primary_key=["id"],
    )
    conversion = SchemaConverter(source_type=SourceType.POSTGRES).convert_table(table)
    assert "GENERATED ALWAYS AS" in conversion.target_ddl  # the preserved clause

    exporter = _FakeExporter(rows_by_table={"order_items": [{"id": 1}, {"id": 2}]})
    importer = _FakeImporter()
    migrator = BatchedTableMigrator(
        dataclasses.replace(
            _inputs(),
            inventory=SourceInventory(tables=[table]),
            table_conversions={table.name: conversion},
        ),
        exporter=exporter,  # type: ignore[arg-type]
        watermark_capturer=_FakeWatermarkCapturer(_watermark()),  # type: ignore[arg-type]
        importer_factory=lambda _inputs: importer,  # type: ignore[arg-type,return-value]
        # Append path -> the LIVE catalog is the authority, and it agrees.
        target_generated_reader=lambda _t: {"line_total"},
    )

    result = migrator.migrate_table(table)

    assert exporter.stream_columns_by_table["order_items"] == ["id", "quantity"]
    assert importer.import_columns_by_table["order_items"] == ["id", "quantity"]
    assert result.rows_loaded == 2

    # And when the LIVE target has an ORDINARY column (an older build stripped the clause),
    # the column must still be LOADED -- dropping it there would write NULLs silently.
    exporter2 = _FakeExporter(rows_by_table={"order_items": [{"id": 1}]})
    importer2 = _FakeImporter()
    BatchedTableMigrator(
        dataclasses.replace(
            _inputs(),
            inventory=SourceInventory(tables=[table]),
            table_conversions={table.name: conversion},
        ),
        exporter=exporter2,  # type: ignore[arg-type]
        watermark_capturer=_FakeWatermarkCapturer(_watermark()),  # type: ignore[arg-type]
        importer_factory=lambda _inputs: importer2,  # type: ignore[arg-type,return-value]
        target_generated_reader=lambda _t: set(),
    ).migrate_table(table)
    assert exporter2.stream_columns_by_table["order_items"] == [
        "id",
        "quantity",
        "line_total",
    ]


def test_the_completeness_banner_aggregates_only_when_it_has_something_to_add() -> None:
    """Two boxes said one fact: the panel and the banner both named the count and the
    table, the banner added "the dropped rows are listed above", and it restated the three
    remedies in prose while the same three sit on the panel as BUTTONS.

    So with ONE affected table and no other problem the aggregate is collapsed into a
    verdict that adds what the panel cannot say -- the consequence of doing nothing -- and
    the aggregate returns as soon as it has something to aggregate: a SECOND affected
    table, a failure, or a real row-count mismatch.
    """
    from dsql_migrator.ui.data_migration._full_load_ui import (
        _render_completeness_banner,
    )

    from dsql_migrator.ui.data_migration import FullLoadCompleteness

    def banner(**kwargs) -> str:
        ui = _BannerUi()
        _render_completeness_banner(
            ui, FullLoadCompleteness(**kwargs), quarantine_accepted=False
        )
        return " ".join(ui.texts)

    one = banner(
        total=2, settled=2, complete=1, failed=0, quarantined_rows=3,
        quarantined_tables=["ecommerce.product_media"], mismatched=["ecommerce.product_media"],
        unknown=0,
    )
    assert "did not load every row" in one, one
    assert "3 rows permanently dropped" in one, one
    # Nothing the panel already carries: no table name, no remedy prose.
    assert "ecommerce.product_media" not in one, one
    assert "listed above" not in one, one
    assert "Exclude column" not in one, one
    # ... and the one thing it uniquely adds.
    assert "Validation (Step 4) reports the shortfall" in one, one

    # A SECOND affected table gives the aggregate a job, so it comes back and names them.
    two = banner(
        total=3, settled=3, complete=1, failed=0, quarantined_rows=5,
        quarantined_tables=["ecommerce.product_media", "ecommerce.users"],
        mismatched=["ecommerce.product_media", "ecommerce.users"], unknown=0,
    )
    assert "finished with issues" in two, two
    assert "ecommerce.product_media" in two and "ecommerce.users" in two, two

    # So does a failure alongside the drop.
    with_failure = banner(
        total=3, settled=3, complete=1, failed=1, quarantined_rows=1,
        quarantined_tables=["ecommerce.product_media"], mismatched=[], unknown=0,
    )
    assert "finished with issues" in with_failure, with_failure
    assert "Retry the failed tables" in with_failure, with_failure


def test_no_source_count_to_compare_is_disclosed_apart_from_a_real_loss() -> None:
    """It was welded into the same sentence as permanently-dropped rows.

    "3 rows permanently dropped (product_media); 4 without a source count to compare" put
    a benign disclosure -- the "--" in the Rows column, i.e. no pre-load estimate -- next
    to a real loss, so the four read as four more faults. It is now its own `info` line,
    and it must come AFTER the verdict, never instead of it.
    """
    from dsql_migrator.ui.data_migration._full_load_ui import (
        _render_completeness_banner,
    )

    from dsql_migrator.ui.data_migration import FullLoadCompleteness

    ui = _BannerUi()
    _render_completeness_banner(
        ui,
        FullLoadCompleteness(
            total=5, settled=5, complete=1, failed=0, quarantined_rows=2,
            quarantined_tables=["ecommerce.product_media"],
            mismatched=["ecommerce.product_media"], unknown=4,
        ),
        quarantine_accepted=False,
    )
    body = " ".join(ui.texts)
    # The loss is stated FIRST and is not diluted by the disclosure.
    assert body.index("permanently dropped") < body.index("no source count to compare")
    assert "no pre-load count to compare" in body
    # The two are separate notices, not one sentence.
    assert "dropped; 4" not in body and "dropped; 4 without" not in body


def test_a_vpc_prefill_that_cannot_run_says_why_instead_of_leaving_it_blank() -> None:
    """The prefill looked like a feature that had disappeared.

    ``derive_cdc_vpc_from_source`` reads the source DB's own DBSubnetGroup, and on a managed
    deployment that read was AccessDenied -- the task role had no ``rds:DescribeDBInstances``
    (verified with IAM simulate: implicitDeny; neither deploy template granted any
    ``rds:Describe*``). The exception was discarded, so the field simply stayed empty,
    indistinguishable from "the tool never tried" -- and it DID work from a laptop whose
    credentials happened to have RDS access, which is why it read as a regression rather
    than a missing grant.
    """
    from dsql_migrator.ui.data_migration import derive_cdc_vpc_from_source

    class _State:
        def __init__(self):
            self._fields = {}
            self.cdc_vpc_provenance = None
            self.cdc_vpc_derivation_note = None

        def cdc_infra_inputs(self):
            return dict(self._fields)

        def set_cdc_infra_inputs(self, fields):
            self._fields = dict(fields)

    class _Session:
        aws_profile = None

        class source_config:  # noqa: N801 - a stand-in for the pydantic config
            host = "src.cluster-abc.us-east-1.rds.amazonaws.com"

    import dsql_migrator.core.rds_metadata as rds_metadata

    def _denied(*_a, **_k):
        raise RuntimeError(
            "An error occurred (AccessDenied) when calling the DescribeDBInstances "
            "operation: not authorized"
        )

    state = _State()
    original = rds_metadata.fetch_source_network
    try:
        rds_metadata.fetch_source_network = _denied
        assert derive_cdc_vpc_from_source(state, _Session()) is False
    finally:
        rds_metadata.fetch_source_network = original

    note = state.cdc_vpc_derivation_note
    assert note, "an AccessDenied prefill must not fail silently"
    assert "rds:DescribeDBInstances" in note, note
    assert "rds:DescribeDBClusters" in note, note  # an Aurora source is a CLUSTER endpoint
    assert "Update the app stack" in note, note  # the actual fix, not just the symptom
    # The field is still left for the operator -- the prefill never blocks.
    assert not (state.cdc_infra_inputs().get("vpc_id") or "")

    # A NON-RDS source is a different reason and must say so, not blame permissions.
    state2 = _State()
    try:
        rds_metadata.fetch_source_network = lambda *_a, **_k: None
        assert derive_cdc_vpc_from_source(state2, _Session()) is False
    finally:
        rds_metadata.fetch_source_network = original
    assert "does not resolve to an RDS/Aurora instance" in (
        state2.cdc_vpc_derivation_note or ""
    ), state2.cdc_vpc_derivation_note
    assert "rds:DescribeDBInstances" not in (state2.cdc_vpc_derivation_note or "")

    # ... and the reason is actually RENDERED on the VpcId field. A note nothing shows is
    # the same silence this fixes, so the render path is pinned too.
    # ... and the reason is actually RENDERED on the VpcId field, driven through the form:
    # a reason nothing shows is the same silence this fixes.
    from dsql_migrator.ui.data_migration import _render_cdc_infra_form

    labels: list[str] = []
    classes_seen: list[str] = []

    class _El:
        def classes(self, *a, **_k):
            classes_seen.extend(str(x) for x in a)
            return self

        def props(self, *_a, **_k):
            return self

        def on(self, *_a, **_k):
            return self

        def on_value_change(self, *_a, **_k):
            return self

        def __enter__(self):
            return self

        def __exit__(self, *_e):
            return False

    class _Ui:
        def input(self, *_a, **_k):
            return _El()

        def label(self, text="", *_a, **_k):
            if text:
                labels.append(str(text))
            return _El()

        row = column = expansion = lambda self, *_a, **_k: _El()

    class _FormState:
        cdc_stack_name = "dsql-cdc-stack"
        cdc_vpc_provenance = None
        cdc_vpc_derivation_note = (
            "This deployment cannot read the source database's network placement: its task "
            "role is missing rds:DescribeDBInstances"
        )

        def cdc_infra_inputs(self):
            return {}  # VpcId EMPTY -- the case the note explains

        def set_cdc_infra_inputs(self, _v):
            pass

    _render_cdc_infra_form(_Ui(), _FormState(), session=None)
    rendered = " ".join(labels)
    assert "rds:DescribeDBInstances" in rendered, rendered
    # Amber, not gray: an AccessDenied here is a real, fixable gap in the deployment.
    assert any("text-amber-700" in c for c in classes_seen), classes_seen
